/* 平成20年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h20.committeeSessions.push(...[{"id":"h20-20080317-3","meetingId":"h20-c-budget","date":"2008年3月17日","dateIso":"2008-03-17","committee":"予算特別委員会","time":"午前１０時０３分～午後６時０５分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を137件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"大沢委員","kind":"質問・要望","question":"品川自民党区議団を代表いたしまして、私と須藤委員とで総括質疑をさせていただきたいと思います。順次質問します。本日の私の質問は、役所内、庁内におけます危機管理、そして、もう１点目におきましては駐輪対策について、この２点についてお伺いをさせていただきたいと思います。１点目です。庁内の危機管理についてお伺いをさせていただきたいと思います。お願いします。","respondent":"田中総務部長","answer":"人的という意味ですと、やはり職員の故意過失、あるいは不作為による違法行為など、行政サービスや区民の信頼を損ねる事象をやはり危機管理としてとらえるべきものと認識しています。","voiceIndex":2,"id":"exchange-001"},{"speaker":"大沢委員","kind":"質問・要望","question":"その危機を回避または解消するために、故意過失に対する予防策はどのようにお考えですか。一つとして、危機管理のそもそもの主たる目的、これはまさに組織の存続が一つに挙げられると思いますが、それを含めましてどのような目標、そして目的があるのか、具体的にお示しをいただきたいと思います。","respondent":"田中総務部長","answer":"区政運営におきましては、やはりこの危機事象の未然防止を図る、これが大事かと思います。そういう意味では、いろいろな事象に対する対応手順、作業手順の確認、それから組織の分担、チェック体制の明確化、関係法令の確認等を行っているところです。","voiceIndex":4,"id":"exchange-002"},{"speaker":"大沢委員","kind":"質問・要望","question":"そこには横断的、そして縦断的に仕事が細部にわたっておりますが、このリスクマネジメント、横断的・縦断的な事業部の仕事、作業が行われるにおいて、先ほど職員のということで文言をいただきましたけれども、どのような意識啓発を含めて、何がそのリスクマネジメント、危機を管理するには必要なものなのか、教えていただきたいと思います。","respondent":"田中総務部長","answer":"課題に対応しまして、例えば平成１９年度ですと緊急地震速報あるいは不当要求防止の研修を実施いたしています。","voiceIndex":6,"id":"exchange-003"},{"speaker":"大沢委員","kind":"質問","question":"ただいま意識啓発という点で、さまざまな啓発事業を伺わせていただきましたけれども、どんなにいい事業、そしてどんなにいい規則、例えば実際に小さな団体で言えば、一つの憲法というものができ上がっていると思いますが、それが形骸化してはいないのか、また形骸化しないためにはどういうふうにすればいいのか、何かご所見がありましたらお伺いをしたいと思います。","respondent":"田中総務部長","answer":"そういう意味では、きちっとした事前からの対応は先ほど申し上げたとおりですが、こういう際にはきちんと、私ども何が問題点かを把握して、新たなリスクが生じないように教訓として生かすよう、職員についてリスクマネジメントをしていく。","voiceIndex":8,"id":"exchange-004"},{"speaker":"大沢委員","kind":"提案","question":"形骸化しないためのお考えをちょっと今聞かせていただきましたけれども、私は一つ、提案を込めてお話をしたい、質問をさせていただきたいと思います。その中で専門的な知識を持ち、その専門的に対応するリスクマネジメントの人的な資源が必要だと思いますけれども、そこのところをどういうふうにお考えになりますでしょうか、ご所見をお伺いしたいと思います。","respondent":"田中総務部長","answer":"そういう意味で、先ほど申し上げましたとおり、各危機事象に対する組織がそれぞれ役割分担を明確にして当たっているということも事実ですし、それから、そういう意味ではやはり専門的に危機管理に対応するという意味で。","voiceIndex":10,"id":"exchange-005"},{"speaker":"大沢委員","kind":"質問・要望","question":"いずれにいたしましても、この複雑多岐な世の中です。危機管理をしっかりしていただきたい、これを念頭に起きまして、私の最初の質問は終わらせていただきます。では、次の質問に移らせていただきます。駐輪対策についてをお伺いしたいと思います。この駐輪対策、区内放置自転車が論じられて久しくなりました。地域特性を含めました品川区の駐輪の現状をお知らせください。","respondent":"岩田まちづくり事業部長","answer":"区内の駐輪場、有料無料を含めまして、区営は２０駅３４カ所設置しています。そのうち有料の自転車駐輪場は１６駅２４カ所、自転車が約７,６００台、バイクは８００台、無料駐輪場は４駅１０カ所、無料が約１,７００台、バイクは０台です。","voiceIndex":12,"id":"exchange-006"},{"speaker":"大沢委員","kind":"質問・要望","question":"ただいま品川区の駐輪の現状、状況をお伺いさせていただきました。今度は数字といいますか、品川区の立地、城南、東京湾に面し、内陸部そして沿岸部ということで、立地を考えた場合の質問をさせていただきたいと思います。今、有料無料２０駅そして１６駅と、それぞれ駐輪の状況を伺わせていただきましたけれども、利用率、自転車においては７０％、そしてバイクにおいては８０％強ということです。","respondent":"岩田まちづくり事業部長","answer":"しかし、何度も当議会でお答え申し上げておりますけれども、品川区は４km四方の非常に小さな面積の中に、非常に多くの鉄道の駅が存在しております。","voiceIndex":14,"id":"exchange-007"},{"speaker":"大沢委員","kind":"質問","question":"一つの例として、西葛西の駅は現行で４,５００台駐輪の収容施設が５,７００台、１,２００台増えています。並行して自転車を２台ずつツリー形式に地下に潜らせることができる駐輪の施設ができました。１台当たりの単価は５０万円から７０万円ぐらいの費用がかかります。費用対効果を含めまして、この取り組み、今江戸川区でやっておりますが、この取り組みについてのご所見をお伺いしたいと思います。","respondent":"岩田まちづくり事業部長","answer":"したがって、駅の通勤通学時は７時半から８時半の時間帯に多くの方が集中して入ってくるような駅前駐輪場では、それをさばくのは、数カ所のこういった機械施設でないと並んでしまうということも考えられますので、これは今後の検討の課題の一つとさせていただきたいと思います。","voiceIndex":16,"id":"exchange-008"},{"speaker":"大沢委員","kind":"質問・要望","question":"持ち時間も限られましたので、いずれにいたしましても、立地条件、地域特性はさまざまなところがありますので、この駐輪対策、創意工夫をこらしながら、多種多様な方法を求めて、これからも駐輪対策を講じていただきたいと思います。要望して、私の質問のほうを終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-009"},{"speaker":"須藤委員","kind":"質問・要望","question":"大沢委員に続きまして質問します。この点につきまして、東京都では６２の市区町村が一つになりまして、広域連合をつくったというふうに伺っております。そこで、この点につきまして、まず質問をします。そのあたりもご説明願いたいと思います。それから、この保険料とそれから介護保険のドッキングしたり、７５歳ですので、そのあたりの組み合わせについての配慮があったら教えていただきたいと思います。","respondent":"木下福祉高齢事業部長","answer":"３月１６日以降、今、保険証を個別にお送りしておりますけれども、その中に小冊子を同封しています。２月から３月にかけまして地域の住民説明会を行ってまいりました。ということで、私どもとしては可能な限りの周知に努めてきたところです。","voiceIndex":20,"id":"exchange-010"},{"speaker":"須藤委員","kind":"質問・要望","question":"続きまして、一般会計のほうで、適正な財政運営ということについてお尋ねいたしますけれども、まず、国や都の支出金、国支出金、都支出金の中に補助金、負担金、委託金等々ありますけれども、そのあたりの仕組みについて、また近年、地方分権が非常に進んできていますけれども、そのあたりと、こういった補助金等のあり方について変化がございましたら、ご説明をいただきたいと思います。","respondent":"日下部企画財政課長","answer":"地方分権の関係ですけれども、この間、地方分権改革ということで、地方の自主的、自立的な行財政運営の実現を目的に推進をされてきているというところでございまして、国による画一的な仕事の押しつけでありますとか、過度な干渉等につきましては。","voiceIndex":22,"id":"exchange-011"},{"speaker":"須藤委員","kind":"質問・要望","question":"国の制度が少しずつ変わってくる中にあって、やはり健全な財政運営というものを常に意識していただかなくてはいけないと思います。それから、今年は計上されていませんけれども、起債につきましては、その時期とか規模とか、どういう考え方でもって起債を起こしているのか、教えていただきたいと思います。","respondent":"日下部企画財政課長","answer":"したがいまして、その活用に当たりましては、後年度の負担、それから将来にわたって財政運営にどのような影響が出てくるのか、そういったことについて十分考慮いたしまして慎重に検討をすべきである、このように考えているところです。","voiceIndex":24,"id":"exchange-012"},{"speaker":"須藤委員","kind":"質問","question":"区民のニーズと、それから国や都の動向、そういったものをチェックする体制というか、その動向をつかんでくるという体制がどうなっているのかもあわせてお聞きしたいと思いますけれども、それと同時に目、節の流用で、金額的に上限が決まるとか、そういう話は別にないんですか。金額的には構わないという形になっているのか、そのあたりを教えてください。","respondent":"日下部企画財政課長","answer":"そこで、区といたしましても、こうした交付金を有効に活用できるように、国や都の動向の把握に努めておりまして、その点、日ごろから各所管はもとより、企画部におきましても、できる限りアンテナを高くして情報の収集を進めているです。","voiceIndex":26,"id":"exchange-013"},{"speaker":"須藤委員","kind":"意見","question":"職員の皆さん方も、単に品川区だけでなくて、国あるいは都はどうあるべきか、あるいは区民のニーズがどうなのだという形で、かなり神経を四方八方に目を光らせていただかなくてはいけない。そういうふうに思っております。そんな中にありまして、区の職員の採用ということが、どういう流れで来ているのかなというふうに思っております。","respondent":"田中総務部長","answer":"その中で経験者採用です。平成１９年度特別区人事委員会が初めて試験を実施いたしまして、４月から採用ということになります。２３区合計では３４４名合格者が出てありますが、品川区では４月１日に事務１５名、技術３名、１８名を採用する予定です。","voiceIndex":28,"id":"exchange-014"},{"speaker":"須藤委員","kind":"提案","question":"そういった意味で職員の研修、それから採用時、いろいろとご指導していただいて、本当に区民サービスができる職員になっていただきたい、このように願っております。続きまして、昨年の４回目の定例会で議員提案させていただきました、文化芸術・スポーツの振興のまちづくりについての条例に絡みまして質問をしますけれども、まず基本的な認識をお聞かせ願いたいと思います。","respondent":"田中区民生活事業部長","answer":"区民生活事業部で、昨年、地域貢献団体の表彰を始めましたが、その中で、荏原地区等で祭りばやしの伝承を子どもたちに行っているですとか、継続的に少年野球や少年サッカーを通じまして人と人のつながりが広がっているということで。","voiceIndex":30,"id":"exchange-015"},{"speaker":"須藤委員","kind":"提案","question":"第１回定例会で、我が会派の林宏議員が、教育委員会の生涯学習部を区長部局へ移されたらどうだというようなご提案をさせていただきました。これも地域の活動が、教育委員会あるいは区長部局というふうに分かれているのだと非常にやりにくいのではないかというようなことがあって、そのあたりのご提案をさせていただいたんですけれども、そのあたりについてもお聞かせ願いたいと思います。","respondent":"田中区民生活事業部長、長田教育次長","answer":"なかなかこの点では課題があるというふうに考えておりまして、今後は地域の実態に合った形で、柔軟な運用ができるように検討していく必要があるというふうに考えております。こうした動きの中で、品川区につきましても、区民のニーズに関する問題に対して、できるだけスピーディーに対応できるようにというような観点の中から、平成２０年度にかけて、この部分についてはどちらが効果的に施策を展開できるのか。","voiceIndex":32,"id":"exchange-016"},{"speaker":"須藤委員","kind":"意見","question":"平成２０年度予算を見ますと、またいろいろな答弁を聞いていますと、親の支援という形でいろいろ組まれてきていますけれども、子どもから見て、いわゆる母親の手で育てられる仕組みというのがお子さんにとっては一番いい形ですので、そういった方向性については、行政としてはどのように今包括的な次世代育成支援の二つの点について、どういうふうにバランスをとっていっていただけるのか、お尋ねいたします。","respondent":"古川児童保健事業部長","answer":"そしてそれを親、家族、地域、行政、さまざまな周囲のものがどう支えていくか、こういう考え方がないと、子どもの本来の育ちに対する支障があってはならない、こういうふうに思ってございまして、まさしく子育ちを支援する、子育ちにふさわしい環境づくり、そしてそれを取り巻く。","voiceIndex":35,"id":"exchange-017"},{"speaker":"須藤委員","kind":"質問","question":"教育委員会のほうで、過日これも既に予算特別委員会の中でご答弁いただいていますけれども、指導要領が変えられて、教育長のご見解を聞こうと思いましたら、もう３月１０日に日経新聞に寄稿されていまして、そこに教育長のお考えが載っていますので、それを読ませていただいて、改めて再度質問をつくらせていただきました。そのときに、教員の定員の増が必要ではないか。","respondent":"若月教育長","answer":"その提案の内容を拝見いたしますと、品川区が率先して取り組んできましたさまざまな改善、あるいは改革の視点がかなり多く含まれているものというふうに認識をしています。","voiceIndex":37,"id":"exchange-018"},{"speaker":"須藤委員","kind":"質問・要望","question":"プラン２１と、本当に先駆的な事業をもう１０年ぐらい前から始めまして、今着々とその成果が上がっていると。それから今、品川区が独自教員の採用というのを始めますけれども、そのあたりにつきまして、進捗状況と、それから今後毎年どういうふうな形でこの何年間かこういうふうに進めるんだということがわかれば、教えていただきたいと思います。","respondent":"若月教育長、長田教育次長","answer":"その際、品川区はさまざまな方面から、ありとあらゆる角度からシミュレーションを綿密に行い、法的な部分でも最大限の検証をし、関係機関と綿密な連携をとりながら、絶対に子どもたちに迷惑をかけないよう。区の教員の独自採用についてのご質問です。現況ですけれども、小中一貫教育を品川区は平成１８年度から推進をしてきまして、施設一体型の一貫校と、それから連携型の一貫教育を進めているというようなことは既にご案内かと思います。","voiceIndex":39,"id":"exchange-019"},{"speaker":"須藤委員","kind":"質問・要望","question":"品川の教育が、単に日本だけではなくて世界の中でやはり注目を浴びていると。何かの席でニュージーランドへ行ったときに、ニュージーランドで品川区の教育はすごいねというようなことを向こうの関係者から言われたことを、もう１０年ぐらい前ですか、覚えているので、そういった息の長い、本当に大変な仕事ですけれども、緊張を緩めることなく頑張っていただきたいと思います。","respondent":"福田企画部長","answer":"その地域周辺の皆さんのご理解が十分に得られるかどうか。地域にどういうメリットがもたらされるのか。そのほか交通事情等、そうしたことにつきまして総合的に検討する必要がある。こういう具体的な検討が必要になってまいります。","voiceIndex":42,"id":"exchange-020"},{"speaker":"須藤委員","kind":"提案","question":"品川区がやはり国際的な品川だという一つの大きなキーポイントになるかと思って、ご提案をさせていただきました。そこを防災用地としてというような話が予算特別委員会でありましたけれども、専売公社というような時代から、その地の自治体に売却ということも優先的に考えられておりますけれども、このあたりについてはどのように感触をつかんでいるか、お聞かせ願いたいと思います。","respondent":"岩田まちづくり事業部長","answer":"しかし、その後、これを売却するか、あるいは自社活用するかについては、まだ社内として検討中であり、決定したことはないという今のところお話を伺っております。","voiceIndex":44,"id":"exchange-021"},{"speaker":"須藤委員","kind":"質問・要望","question":"次に過日、区民の方から品川区は頑張っているんですねというようなことを言われました。何ですかと言ったら、去年１２月に放送で、品川区が住みやすいまちの１番に２３区の中で選ばれましたというようなことを言われたので、私自身も大変うれしくなったんですけれども、私が放送を聞いていないので、その辺の内容についてご存じでしたら教えていただきたいと思います。","respondent":"濱野区長","answer":"その中でいろいろ私の考え方を述べさせていただきましたけれども、これは、その評価をいただいたこと、あるいはこのインタビューの中で私の話をさせていただいたことについて、大変にありがたかったというふうに思っております。","voiceIndex":46,"id":"exchange-022"},{"speaker":"須藤委員","kind":"質問・要望","question":"私も今２年連続品川区は２３区の中で一番住みやすいというふうに評価されたというのは、区長が急になられたから評価されたということだけでは決してない。そういった中にあって、区長が新しい予算をつくって、今お話ですけれども、その辺のあたり、決意のほどをもう一度述べていただきたいと思います。","respondent":"濱野区長","answer":"この番組でも感じましたし、それから今回３月３日からの予算特別委員会での審議の中でも非常に強く感じたんですが、ここに並んでおります行政に携わる者、この場にいる者を始めとして二千数百名の人間が行政に携わっているわけでありますけれども、その者たち。","voiceIndex":48,"id":"exchange-023"},{"speaker":"須藤委員","kind":"提案","question":"区長の決意を聞いて安心しました。我々自民党といたしましても、区民の皆さんがいろいろとご提案をしたり、また我々がヒアリングをさせていただいたりという中で、行政にぶつけてきております。予算の中でいろいろ質問させていただきましたけれども、どうか真剣に酌み取っていただきたい、こんなふうにお願いをいたしまして、私の総括質疑を終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":50,"id":"exchange-024"},{"speaker":"山元委員","kind":"質問・要望","question":"委員長の許可を得まして、後ほど資料の提示をしますので、どうぞよろしくお願いいたします。私からは、女性の視点に立った支援策の拡充についてお伺いをいたします。本区では、これまでさまざまな角度から女性に対する支援策を行ってこられたと思いますが、そこでこれまでどのような視点から、またどのような支援策が実施されてきたのか、代表的なもので結構ですので、お伺いさせていただきたいと思います。","respondent":"福田企画部長","answer":"経済支援といたしましては、母子福祉資金の貸付、さらに生活支援、こうした場面におきましては、ひまわり荘の設置など、これが代表的なものでございまして、今審査をお願いしております平成２０年度予算におきましては、こうした部門をさらに充実させたい、そう考えておりまして。","voiceIndex":52,"id":"exchange-025"},{"speaker":"山元委員","kind":"提案","question":"ところで、去る１月２３日に行われました参議院本会議の代表質問の中で、我が公明党の浜四津代表代行が、日本社会の再生と活性化のためには、女性に光を当てる社会づくりが大切との観点から、女性の一生をトータルにサポートするための、女性の一生サポートトータルプランを提案いたしました。福田総理からは、前向きなご答弁をいただきました。１点目は子宮がん検診についてお伺いいたします。","respondent":"宮本品川区保健センター所長","answer":"年代別の傾向では３０代、４０代の方の受診が高く、それに比べまして２０代は低くなっているところです。","voiceIndex":54,"id":"exchange-026"},{"speaker":"山元委員","kind":"質問・要望","question":"平成１７年度から対象年齢が２０代まで拡充をいたしまして、実施をされてきたですけれども、なかなかこの受診率が上がっていない現状がよくわかりましたが、その報道等によりますと、子宮がんは２０代の若い年代に急激に増えているということを伺いました。","respondent":"宮本品川区保健センター所長","answer":"対象者の方につきましては、それぞれ誕生月に個別に通知をしております。広報紙にも毎月検診のご案内を載せて周知をしています。引き続き受診率向上のために、さまざまな工夫をして周知徹底、受診勧奨に努めてまいりたいと思います。","voiceIndex":56,"id":"exchange-027"},{"speaker":"山元委員","kind":"質問","question":"実は私も若い何人かの女性に聞いたところ、検診があることを知らない方や、また女性特有ということもありまして、女性の医師に診察してもらいたいということで、逆にどこに行ったらいいのかというお声を伺いました。来年度実施予定とお聞きしておりますがん検診管理システムの取り組みの中で、対象者に積極的に受診を呼びかけてはいかがでしょうか。あわせてご所見をお伺いしたいと思います。","respondent":"宮本品川区保健センター所長","answer":"がん検診管理システムは新たに導入するものですが、それを活用いたしまして、未受診者に対しまして再度受診の通知をして受診勧奨に努めるということと、あとそのほかにも検診の重要性について十分啓発してまいりたいと思います。","voiceIndex":58,"id":"exchange-028"},{"speaker":"山元委員","kind":"質問・要望","question":"ともかくこの受診率アップのためにぜひご努力をしていただきたいと思います。多くの国でも審査中ということを聞いておりますけれども、このワクチンというのはどういうものなのか、また効果についてお教えいただけるでしょうか。","respondent":"宮本品川区保健センター所長","answer":"一応感染予防の効果としては、海外の報告などでも８０％はあるというふうな、そういう報告も出ておりますけれども、この予防効果がどのぐらい持続するのか、あるいはがん自体の予防効果がどのくらいかといった点につきましては、まだ確認されていないところです。","voiceIndex":60,"id":"exchange-029"},{"speaker":"山元委員","kind":"質問・要望","question":"実は我が党は昨年１０月の参議院予算委員会で、ご紹介いただいた感染予防ワクチンの早期承認を求めたのに対して、厚生労働大臣からは全力で取り組む旨の答弁をいただきました。あわせて、承認された際には積極的にワクチンの活用が図られますよう要望いたしますが、ご所見をお伺いいたします。","respondent":"宮本品川区保健センター所長","answer":"ワクチンの承認に関しましては、やはり有効性・安全性が十分確認された上で、政府に承認されるということを望んでいるものです。承認後の対応につきましては、今現在、国のほうで審査をしています。今後、国の動向を注視してまいりたいと考えております。","voiceIndex":62,"id":"exchange-030"},{"speaker":"山元委員","kind":"質問","question":"どうかよろしくお願いいたしたいと思います。次に、安心して出産できる環境づくりについてお伺いしたいと思います。そこで、本区の妊婦受け入れの実態について、どのように認識されていらっしゃるのか、お伺いしたいと思います。なぜこのようないわゆるたらい回しが起きてしまうのかもあわせてご所見をお伺いしたいと思います。","respondent":"宮本品川区保健センター所長","answer":"妊婦受け入れのいろいろ問題があるです。ちょっと詳細については把握をしておりませんが、区内では出産を３施設で取り扱っておりますので、今のところ幸いと申しますか、妊婦の受け入れ態勢について、大きな問題は生じていないというふうに認識をしています。","voiceIndex":64,"id":"exchange-031"},{"speaker":"山元委員","kind":"質問・要望","question":"本区では、来年度から我が党も推進してまいりました妊婦健診の１４回までの無料化が実現されることとなり、少なくとも経済的な理由で健診が受けられずに駆け込み出産によるたらい回しは起きてはならないと信じておりますけれども、万が一にも制度の拡充を知らずに健診を受けない方が出ないように、しっかりとした周知を要望いたします。その周知の方法として、ご所見をお伺いしたいと思います。","respondent":"宮本品川区保健センター所長","answer":"妊娠届の際にお見えになります。そのときに母子手帳をお渡ししておりますので、その際に十分に健診が拡充されたということを周知してまいりたいと思います。そのほか、さまざまな工夫をいたしまして、周知漏れのないように努力してまいります。","voiceIndex":66,"id":"exchange-032"},{"speaker":"山元委員","kind":"質問","question":"くれぐれもよろしくお願いをしたいと思います。ところで、この本区内には現在３つの病院で出産ができると伺っております。昨年度、本区の年間出生数は約２,８００人と聞いておりますが、こういう状況から見ると、近隣区の病院も合わせて現状のベッド数は足りているように思われますけれども、わかる範囲で結構ですので、本区のご見解をお伺いしたいと思います。","respondent":"宮本品川区保健センター所長","answer":"区民の方がどのように利用されているかというところまではちょっと把握しておりませんが、周辺区も合わせますと、おおむね充足されているというふうに認識を持っております。","voiceIndex":68,"id":"exchange-033"},{"speaker":"山元委員","kind":"質問・要望","question":"今注目されつつある助産師の活用について、厚生労働省の来年度予算で、院内助産所設置の国や都の助成制度も予定されているようですけれども、今後こうした院内助産所や助産師外来などの情報も区民に対して積極的に提供されますよう要望いたしますが、それぞれのご所見をお伺いしたいと思います。","respondent":"宮本品川区保健センター所長","answer":"そういうところでの連携等が図られるかと思っているところです。院内助産所、あとは助産師外来など、その情報については、ちょっと今後情報を把握いたしましたら、区民の方に情報を提供するように努めてまいります。","voiceIndex":70,"id":"exchange-034"},{"speaker":"山元委員","kind":"質問・要望","question":"最後に、生涯を通じた女性の健康パスポートの発行についてお伺いいたします。現在、我が国では妊娠期から出産を終え、子どもが小学校に入学する前まで、母子それぞれの健康状態が記録される、いわゆるこういう母子手帳が配付されておりますが、本区では、母子手帳以外に健康管理などのために何か配付されておりますでしょうか、お知らせしていただきたいと思います。","respondent":"宮本品川区保健センター所長","answer":"４０歳以上の方には配付しておりますが、健康手帳というものがあります。健診の結果を５年間記録できます。そのほかにも生活習慣病の予防についてとか、いろいろ健康づくりに活用できるような情報なども載せているものです。","voiceIndex":72,"id":"exchange-035"},{"speaker":"山元委員","kind":"提案","question":"実は先日、ヨーロッパ在住の日本人女性が初めて出産の際、医師から安全に出産するために、生まれてからこれまで予防接種や病歴、また治療歴の記録を見せるように求められたとの話を伺いました。今回、女性の視点から、改めて予防接種や病歴、また治療歴、出産、健康診断等の記録を記載し、生涯にわたる健康を守るための女性健康パスポートの発行を提案いたしますが、それぞれご所見をお伺いしたいと思います。","respondent":"宮本品川区保健センター所長","answer":"健康管理システムのあり方に関しての検討状況ですけれども、健診データをカード入力して活用するという点で検討してまいりましたが、やはり区単独での実施は難しいという認識に至っております。","voiceIndex":74,"id":"exchange-036"},{"speaker":"山元委員","kind":"提案","question":"これまで何点かにわたり、女性の視点からの支援策について伺ってまいりましたが、私も女性議員として、これまで何人かの女性から女性特有のご相談を受けてまいりました。あわせて最後になりますけれども、冒頭にも触れさせていただいたとおり、本区が実施するさまざまな女性に対する支援策が体系的にトータルサポートしていただけるような今後の取り組みを要望いたしますが、ご所見をお伺いしたいと思います。","respondent":"田中総務部長","answer":"こういうような総合的な案内の冊子が必要かどうか、委員の皆様と十分協議をして検討してまいりたいというふうに考えてあります。それから、女性に対する支援策が体系的にトータルにサポートしてという趣旨を伺っているところです。","voiceIndex":76,"id":"exchange-037"},{"speaker":"山元委員","kind":"質問","question":"ぜひ、今ご答弁をいただきまして、希望あふれるご答弁でしたので、楽しみにしていきたいと思います。以上、山元敬子の質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-038"},{"speaker":"若林委員","kind":"質問・要望","question":"公明党の若林です。地球温暖化対策です。そういう歴史も踏まえながら質問をさせていただきたいというふうに思っております。ここをしっかりとお互いに確認をさせていただきたいというふうに思っております。地球温暖化の原因や実態、またこのまま放置しておくと地球環境はどのようになっていくのかをお聞きいたしまして、品川区の地球温暖化に対する危機感をどのようにお持ちであるか、伺いたいと思います。","respondent":"岩崎環境清掃事業部長","answer":"品川区としては、そういう全世界のいろいろな動きといかに連携した政策を打っていけるかというようなことが今後課題であるというふうに考えております。","voiceIndex":80,"id":"exchange-039"},{"speaker":"若林委員","kind":"質問・要望","question":"いずれにいたしましても、このまま地球温暖化、一生懸命取り組んでいるところですけれども、具体的な活動としてＣＯ２の削減、これが最大の目標になってまいります。東京都のほうでもいろいろお話を伺っておりますけれども、国や都の計画に対して、この品川区がどのようにかかわっていくのか、ここら辺もお聞かせをいただきたい。この点についてのご見解をお聞かせいただきたいと思います。","respondent":"岩崎環境清掃事業部長","answer":"これの中で、試算ではマイナス６％は達成可能であろうというような報道がされております。具体的に、その内容で今後検討しなければならない課題というのを言っておりまして、一つは国内の排出量取引でありますとか、環境税をどうするか。","voiceIndex":82,"id":"exchange-040"},{"speaker":"若林委員","kind":"質問・要望","question":"次の質問がまさにそこのところです。先般の第１回定例会でも、公明党の武内議員より質問させていただきました。ご答弁も聞かせていただきました。もう一度この点につきまして、具体的なＣＯ２削減量、また現在の排出量の数値の出し方、これをご答弁をいただきたいというふうに思います。","respondent":"岩崎環境清掃事業部長","answer":"計算そのものはデータが不足しているところもありまして、完璧にはできないということはご答弁申し上げたところですが、これを何らかの代替的な措置によりまして計算そのものはできるだろうというふうに思っております。","voiceIndex":84,"id":"exchange-041"},{"speaker":"若林委員","kind":"提案","question":"一つが現状を知り、学んでいくこと、またもう一つはみずからの生き方を見直していくこと、そして三つ目には行動に踏み出すこと、こういうことを段階を踏んだ環境教育といいますか、環境学習、また意識啓発、こういうところにしっかり組み込んでいただきたいなというふうに、これはひとつ提案といいますか、後ほどご所見を伺いたいと思います。","respondent":"岩崎環境清掃事業部長","answer":"学校では家庭ＩＳＯということで、学校を通して家庭にさまざまな省エネ行動をやっていこうというような訴えかけをしています。このようなことをさらに強化していくというようなことが必要なのではないか、こういうふうに考えております。","voiceIndex":86,"id":"exchange-042"},{"speaker":"若林委員","kind":"提案","question":"地球憲章、これは別名、民衆憲章とも呼ばれているものです。次に、今、部長からもちょうどお話が出ました環境情報活動センターを含めました具体的な提案を３点をしまして、また質問に移らせていただきたいと思います。提案の一つ目が環境情報活動センターについて、これは品川区の中心的な拠点ですので、さらにシンボル的な存在としての再整備、これを行ってはいかがかなというふうに思っております。","respondent":"岩崎環境清掃事業部長、早津区民生活事業部次長","answer":"目標・現状に対するパネル等ですが、さらに工夫をしていきたいと考えております。今後の家庭ＩＳＯの話ですが、いままでは学校の宿題という形で実施してきていただいております。具体的な内容については、この里山づくりを通じる中で検討してまいりたいというふうに考えてあります。","voiceIndex":88,"id":"exchange-043"},{"speaker":"若林委員","kind":"質問・要望","question":"環境情報活動センター、スペースが大変に狭いですので、要するにオープンな構造にもう少しできないものか、なかなかドア一つ、やはりあれはヨイショとあけないと中に入れない、また知った人もいませんので、そこら辺のもうちょっとオープンな構造で、より多くの区民が気軽に足を運べる、せっかくいい教材があるわけですから、そういうことをお願いをしたいというふうに思います。","respondent":"岩崎環境清掃事業部長、岩田まちづくり事業部長","answer":"そういう意味で、カーボンオフセット商品がどうだとかいうようなことも含めまして、ＣＯ２の面からのさまざまなサービスや製品の評価ということを見きわめてまいりたいというふうに考えております。品川区でも、現在、新・水とみどりのネットワーク構想、これがほぼ骨格が定まりました。これから検討していただきます新長期基本構想の中で、実際に財源に裏づけされた緑化の計画的な推進の方策を定めてまいります。","voiceIndex":91,"id":"exchange-044"},{"speaker":"若林委員","kind":"質問","question":"区有施設のあり方について、これは東京都のほうでも「省エネ東京仕様２００７」、こういう独自の設定をするような考えが出てきております。例えば入札の際に、この環境、また地球温暖化に取り組む業者に対してポイントを付与する、このような制度を今ご検討中だと思いますけれども、お考えをお聞かせください。ここら辺の大きな課題につきまして、ご見解を伺いたいと思います。","respondent":"田中総務部長、岩田まちづくり事業部長","answer":"それからもう１点、環境配慮型企業への入札等のポイントの云々ですけれども、従来の一般競争入札、指名競争入札で、これはなかなか難しいところがありますが。環境配慮ガイドラインというのをつくりまして、それぞれが開発を計画する場合は、このガイドラインに基づいて地球環境対策をきちっと打ち出していく、こういうふうになっておりまして、品川区もその中で個々の開発について。","voiceIndex":94,"id":"exchange-045"},{"speaker":"若林委員","kind":"質問・要望","question":"最後になります。具体的な取り組みを伺ってまいりましたけれども、今後の、その仕組みづくりもしっかりと行っていただきたいなという思いです。このことについて、最後、ご見解を伺いたいと思います。","respondent":"福田企画部長","answer":"委員ご指摘のとおり、区民の意識は相当高まっているというふうに考えております。その意識をどういうふうに生かすか、これにつきまして積極的に検討する、これが長期基本計画の一つの課題であると認識しております。","voiceIndex":97,"id":"exchange-046"},{"speaker":"若林委員","kind":"質問","question":"最初に言いました災害時助け合いシステムと高齢者見守りネットワークにつきましては、また機会を改めましてお伺いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":99,"id":"exchange-047"},{"speaker":"安藤委員","kind":"質問","question":"日本共産党を代表して総括質問を行います。私のほうから質問いたします。このオアシスルームという制度はどのような事業なのでしょうか。区内の保育園で行っているということですが、一つの園につき、どれぐらいの人数を受け入れているのか、受け入れる側の職員の体制についても伺います。専用の担当職員が配置されていたり、専用の部屋が設けられていたりするのでしょうか。","respondent":"古川児童保健事業部長","answer":"基本保育を中心にしながら、非常勤、あるいは派遣、場合によっては委託、これは基本の保育園の事業の中で特に在宅の子育て支援ということで、新しい事業ですので、さまざまな変遷がまだこれからもあるだろう、このように考えてあります。","voiceIndex":102,"id":"exchange-048"},{"speaker":"安藤委員","kind":"質問","question":"これまでのこの事業の成果はどのように評価しておられますでしょうか。親のニーズとの関係ではどのように感じていますでしょうか。今後の事業展開についての考えをお伺いいたします。","respondent":"古川児童保健事業部長","answer":"まだ始めて３年ちょっとの事業でありますけれども、多くの在宅の子育ての方々には、時として子育てをしている中ではちょっとしたリフレッシュが必要だろう、こういうことでは大変喜ばれている事業でありますし、しかしながら。","voiceIndex":104,"id":"exchange-049"},{"speaker":"安藤委員","kind":"質問","question":"２点指摘したいと思います。これなんですけれども、２００４年６月にオアシスルームがスタートしてからいままでの、そして４月から来年度の予定も含めての実施状況です。開始３年で事業廃止になった園が４園、加えて来年度も１園あります。この中延、東中延、東品川、五反田、あと来年度の中原ですね、なぜ３年で事業が廃止になったのでしょうか。","respondent":"古川児童保健事業部長","answer":"廃止という言葉ですが、大変誤解を招きますけれども、私どもは事業を廃止してございませんで、実施場所は変わります。品川区には３７の保育園がありますけれども、各園長さまざまな事業に対して意欲的です。できれば私の園でやりたいという園長がたくさんおいでになっています。","voiceIndex":106,"id":"exchange-050"},{"speaker":"安藤委員","kind":"質問","question":"オアシスルームの需要はかなり高かったとも聞きました。その地域で需要があるにもかかわらず、突然オアシスルームが、この場合ですと２００７年５月末で終わっておりますけれども、突然なくなってしまったら、これは利用者は混乱するのではないでしょうか。","respondent":"古川児童保健事業部長","answer":"当初の予定通りです。３年で変更になりましたのは、平成１９年の９月から認定こども園を五反田で実施している。しかも夜間保育園でもありますので、さまざまな事業を３７園で実施したいというのが私どもの考え方です。","voiceIndex":108,"id":"exchange-051"},{"speaker":"安藤委員","kind":"質問","question":"保護者のほうにはきちんと、それまでオアシスルームに通わせていた親の方からすると今年もオアシスルームが行われるだろうということを前提にして、いろいろ生活環境を考えていると思うんですけれども、例えば先ほどの五反田ですけれども、突然なくなって混乱すると思うんですけれども、こういうのを、利用者に不便とかはなかったのでしょうか。","respondent":"古川児童保健事業部長","answer":"私どもの周知が不十分であったとすれば、これは反省しなければいけないと思ってありますけれども、五反田の周辺では大崎あるいは東五反田で新しくやっておりますし、東五反田での実施状況はご案内のとおり、保育園全体の需要が大きい中では。","voiceIndex":110,"id":"exchange-052"},{"speaker":"安藤委員","kind":"質問","question":"五反田は、東五反田などもあるということでしたけれども、きちんとそういったことは通知が行われたり、配慮とかはあったんでしょうか。","respondent":"古川児童保健事業部長","answer":"しっかりとご説明をしております。","voiceIndex":112,"id":"exchange-053"},{"speaker":"安藤委員","kind":"質問・要望","question":"なぜなのかというふうに思わざるを得ません。保育士の待遇についてお伺いしたいんですけれども、非常勤保育士の時給は幾らでしょうか。区が契約している派遣会社との１時間当たりの契約単価、これは幾らで、実際に派遣会社から労働者に支払われている時給は幾らなんでしょうか。その他交通費や社会保険など、非常勤保育士と派遣保育士は、正規の保育士と比べてどのような待遇の差があるのでしょうか。","respondent":"古川児童保健事業部長","answer":"派遣職員については、私どもが契約している中では幾つかのパターンがありますけれども、２,０００円前後、高いところでは２,６００円でありまして、それぞれの企業でいかほどの給与を支払っているかは私の承知しているところではございません。","voiceIndex":114,"id":"exchange-054"},{"speaker":"安藤委員","kind":"質問","question":"行政サービスに携わっている公務労働者がどんな労働環境で働いているということをつかまずして、品川の保育の質の確保に品川区が責任を持てるとは思えないんですけれども、いかがでしょうか。","respondent":"古川児童保健事業部長","answer":"答えは繰り返しでございまして、変わりません。それぞれの企業と、そして雇用されている方々の間で決めていくものだろう、こう考えてあります。","voiceIndex":116,"id":"exchange-055"},{"speaker":"安藤委員","kind":"意見","question":"品川区が派遣契約を結んでいるＡ社が実際に派遣保育士に支払っている時給ですけれども、最高で１,２３０円というのがありました。１日８時間労働の週５日勤務で月収は１９万６,８００円になり、ボーナスはもちろんありませんので、年収にすると２３６万円程度です。これを保育サービスを担う方々がこういう賃金体系でやっているんですけれども、これは多いと思いますか、少ないと思いますか。","respondent":"古川児童保健事業部長","answer":"それぞれの働く方の立場あるいは環境、考え方によってさまざまでしょうから、一概には言えるものではない、このように考えてあります。","voiceIndex":118,"id":"exchange-056"},{"speaker":"安藤委員","kind":"質問","question":"月１８万円、年収２０４万円で働いている派遣の方の、こういう収入で働いている派遣の方の、青年の言葉があるんですけれども、これは、この年収２０４万円で派遣でやっている方なので、保育士の方ではないんですけれども、同じ給料ですから、そういう同じ額の中でどう生活をするかという点では生活実態が同じだと思いますので、紹介いたします。このまま将来どうなってしまうんだろうかと不安を感じる。","respondent":"古川児童保健事業部長","answer":"派遣法というものについてどう認識されているのでしょうか。派遣法なるものがあって、その中で、私どもは法に従って職員の方々に仕事をしていただいているわけです。派遣法自体が悪いのであれば、これは別の論議をしていただきたいし、私どもは派遣法の中で活用する。","voiceIndex":120,"id":"exchange-057"},{"speaker":"安藤委員","kind":"質問","question":"去年の五反田保育園なんですけれども、４月から５月末まで２カ月間だけオアシスルームが行われまして、その後、東五反田もあるんだと案内も周知したんだという話がありましたけれども、展開したというふうにありますけれども、確かに近いんですよね、二つの保育園というのは場所が近いので、この移動に伴って、ここに来ていた派遣会社の変更というのはあったんでしょうか。","respondent":"古川児童保健事業部長","answer":"派遣会社の変更があったかないかについては、細かなことについては私は承知してございません。その前に、先ほどの質問の中で最少の経費を上げるためにこのような派遣社員を使っている、こういうお尋ねでございました。","voiceIndex":122,"id":"exchange-058"},{"speaker":"安藤委員","kind":"質問","question":"ですから、その現実を前提にするという、確かに立派な考えかもしれませんけれども、そういうちょっと冷たいなというふうに思っちゃうんです。なぜ３年で移ったのでしょうか。この東大井、旗の台の２園ですけれども、この４月からも、この水色ですから労働者派遣を使って４年目に入ります。この二つの園なんですけれども、４年目に入るこのケースだと、これは法に触れないんでしょうか。","respondent":"古川児童保健事業部長","answer":"２点ほどのご質問であると思うんですが、先ほどご答弁申し上げておりますとおり、五反田から東五反田へ移った、それは五反田での新たな認定こども園という事業展開に対する一定の考え方もありましたし、五反田から東五反田や大崎、地域の中でのエリア分担をしているです。","voiceIndex":124,"id":"exchange-059"},{"speaker":"安藤委員","kind":"意見","question":"款別の中でも区側のほうからの答弁でありましたけれども、クーリングという言葉が出ました。クーリングということは、適切に相談しながらやっているということでしたので、ちょっとご説明してください。","respondent":"古川児童保健事業部長","answer":"クーリング期間については、一定の期間、間をあけることによって派遣の社員を活用できる、こういう制度であろうと認識しています。","voiceIndex":128,"id":"exchange-060"},{"speaker":"安藤委員","kind":"質問","question":"先ほどの２園に関して、このクーリングの適用があったということでよろしいでしょうか。","respondent":"古川児童保健事業部長","answer":"クーリングの適用も含めて適正に執行しています。","voiceIndex":130,"id":"exchange-061"},{"speaker":"安藤委員","kind":"質問","question":"クーリングしているから問題ないという態度なんですけれども、なぜ、そこまでクーリングしなくてはいけないのか。お伺いしたいと思いますけれども、このクーリング期間、３カ月と１日以上あけるということですけれども、この間に保育士、派遣保育士が来なくなっちゃって、現場で困らないのでしょうか。","respondent":"古川児童保健事業部長","answer":"もっと言いますと、オアシスルームだけを単独でやることは不可能です。今１時間５００円で利用料をいただいていますけれども、もしこれを単独の事業として１日正規職員を２人をつけてやるということは、これは安藤委員にも無理だと思います。","voiceIndex":133,"id":"exchange-062"},{"speaker":"安藤委員","kind":"質問・要望","question":"私はぜひ安定した体制ということを冒頭から申し上げましたけれども、そういう点でも正規でやっていただきたい。クーリングを設けて派遣期間を３年以内にした。ぜひ、安定的な運営のためにも、子どものためにも正規でしっかりとオアシスルームの運営、あるいは保育の運営を貫いていただきたいと思いますが、いかがでしょうか。","respondent":"田中総務部長","answer":"すべてこれを正規職員でというふうになったら到底できない話、先ほど来から言っておりますが、利用料等にもはね返る話、そういう意味での区民サービスを、私どもとしては正規を中心にいろいろな形態を使ってやってきたわけです。","voiceIndex":135,"id":"exchange-063"},{"speaker":"安藤委員","kind":"質問","question":"コストを優先させる余り、法の趣旨も意に介さない、あと労働者の生活は知らない、こういう姿勢は本当に困るということを指摘して、私の質問を終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":137,"id":"exchange-064"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"引き続いて、日本共産党を代表して総括質問を行います。私は、介護施設で働く人の労働条件の改善と、一日も早い特別養護老人ホームの増設を求めて質問をしたいと思います。区内施設でも職員確保が大変だと聞きました。区内特別養護老人ホームの労働の実態、そして区のそれに対する認識を伺いたいと思います。そして、介護福祉士の専門学校の入学者の状況もあわせてお聞かせください。","respondent":"木下福祉高齢事業部長","answer":"区内特別養護老人ホームのいわゆる職員の状況ですけれども、まず、特養というふうにお話がございましたので、特養措置時代から基本的には実施しておりました、当時の職員の給料表というのは東京都社会福祉協議会が参考モデルをつくっておりましたが。","voiceIndex":139,"id":"exchange-065"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは社会問題になっている問題ですから、区内でも職員の確保が大変で、ベッドを維持できるんだろうか、こういうふうな大変深刻な話も聞きました。区としても独自策をぜひとっていただきたい。５割から６割に減らされた都や区の補助金、これをぜひ増額をしていただきたい。ぜひ学校の存続と、学生を定員まで増やす取り組みを行うよう求めたいと思いますが、いかがでしょうか。","respondent":"木下福祉高齢事業部長","answer":"多分ご指摘の点は、東京都が行っていた、現在も行っておりますけれども、経営支援費のことかと思いますけれども、これも本来ですと介護保険が始まって３年でなくなる予定のものだったのが、現時点でも維持されております。","voiceIndex":141,"id":"exchange-066"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"志を持って入った介護の現場で、介護に携わる方々がやりがいを感じられるように、また生活が成り立つための労働条件の改善、ここのところを国の対策待ちにしないで区が率先して取り組むよう、それをぜひ検討していただきたいというふうに強く要望して、次の質問に移りたいと思います。改めて品川区の特別養護老人ホームの整備に関しての考え方をお伺いしたいと思います。","respondent":"木下福祉高齢事業部長","answer":"そういう意味では、平成１２年以降進めてきたケアホームを基本にしながら、グループホームをあわせて整備するという部分についての考え方は、やはり今後とも必要だろうというふうに思っております。","voiceIndex":143,"id":"exchange-067"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区は今の入所調整会議の中で必要な人は入れていると、こういう答弁を繰り返していますけれども、今のこの待機者のために特別養護老人ホームの増設は必要ないと考えているという答弁を議会の中では繰り返しているわけですけれども、この入れていない８割、こちらに至っては９割を超える、こういう方々は入所が必要な人ではないと考えているんでしょうか。お聞かせいただきたいと思います。","respondent":"木下福祉高齢事業部長","answer":"先ほど申し上げたように、今後のことを踏まえますと、その部分についてはやはり検討をしていく必要があるというふうに考えているです。","voiceIndex":145,"id":"exchange-068"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私がお伺いしたのは、この入れていない８６％、こちらで言えば９０％を超える方、この方々は入る必要がない人だというふうに区としては考えているのかということなんです。ここが肝心なんですよ。ここの人たちは、必要な人が入れているので増設する必要がないというふうに区が答え続けているわけですから、この人たちは入る必要がないというふうに考えているのか、そこのところを改めてお聞かせください。","respondent":"木下福祉高齢事業部長","answer":"その中には、絵の水色のところには要介護１、２の方も当然入っているわけでありますから、そういう点で言うと、ご希望はあるかもしれませんけれども、より困難状況の高い方からまず入っていただくということで、ご理解をいただきたいというふうに思っております。","voiceIndex":147,"id":"exchange-069"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この水色の部分の方のために特別養護老人ホームを増設する必要はないというふうに考えているのでしょうか。","respondent":"木下福祉高齢事業部長","answer":"先ほども申し上げましたように、これからは、多様な選択肢を用意していこうということで、ケアホームのような施設、これができることによって当然特養の入所希望の中ではケアホームのほうがいいという選択をされる方もおられるわけでありますから。","voiceIndex":149,"id":"exchange-070"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"病院や老健施設に入っている方、これは在宅でもうぎりぎりで、見られないという方が老健や病院に入っているというふうな方なわけですから、私は一人一人の、この本人や家族、どんな思いでいるのか、このことにぜひ品川区は、部長は思いを寄せていただきたいというふうに思います。部長はこういう方の話を聞いて、胸は痛まないのでしょうか。こんな方がたくさんいらっしゃるのではないでしょうか。","respondent":"木下福祉高齢事業部長","answer":"やはり在宅で限界が来た方については見通しが立つということを今後とも進めていきたいということでありますので、私どもとしては、そのような考え方で今後とも進めていきたいと考えています。","voiceIndex":151,"id":"exchange-071"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私はだから特養ホームを、そういうことでつかんでいるというのであれば、ぜひつくっていただきたいというふうに思います。これは特別養護老人ホームの２３区比較です。品川区は２３区の中で整備率２０番目です。１８区が４１カ所、３,６９８ベッドつくってきました。他区ではこの国民年金の方までが入れる新型特養ホームをつくり続けているのに、なぜ品川区がつくらないのか、お聞かせください。","respondent":"木下福祉高齢事業部長","answer":"一つは平成１２年で一定の基盤整備を終えたということと、当時、やはり個室ニーズがあったという部分については、平成１２年当時は、それについての補助体制はありませんでした。","voiceIndex":153,"id":"exchange-072"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"特養ホームとケアホーム、何が違うか。この利用料が違うんです。こんな中でやはり利用料の減免制度があって、だれもが対象になる、そういう特別養護老人ホームこそつくるべきだというふうに思うんですけれども、いかがでしょうか。そして改めて、品川区が特別養護老人ホーム、それからケアホーム、この施設について、それぞれどういう施設だと考えているのか、改めてお聞かせいただきたいと思います。","respondent":"山田副区長","answer":"そのあとということで、これから１０年、２０年後の超高齢化の中で、当然発症率が高くなりますから、特別養護老人ホームの必要性も含めて、それぞれの施設の体系の中で検討を始めていきたい、そのように考えてあります。","voiceIndex":155,"id":"exchange-073"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"新型特養ホームとケアホームは、両方とも個室ユニットケアだということはおわかりですか。今は同じなんですよ。同じなんです。それで私たちが求めているのは新型特養ホーム。それで、職員体制というのも、このこちらも、ケアホームも特養ホームも３対１で基準は同じなんですよ。だから、だれもが入れる、国民年金の人でも入れる特養ホームをつくってほしいというふうに言っているんです。どうでしょうか。","respondent":"木下福祉高齢事業部長","answer":"やはり今の介護報酬体制の中で、多分２対１を維持していくのはなかなか大変な部分になっていようかと思います。そういうようないろいろな問題があるということを踏まえて、今後検討をしていきたいです。","voiceIndex":157,"id":"exchange-074"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"待っている方は４００人もいるわけですから、そのところにしっかりと心を寄せてもらいたい。１０年、２０年のスパンでは間に合わないんですよ。ぜひ特別養護老人ホームをつくっていただきたいというふうに思います。新型の特別養護老人ホームの人員配置が２対１でも厳しいということであるのであれば、そこのところの解決こそ必要なのではないですか。そこのところはいかがでしょうか。","respondent":"木下福祉高齢事業部長","answer":"職員の確保が難しいという部分についてもこれは連動する話であります。そういう点で言いますと、やはり国民的なコンセンサスが必要な、重要なテーマだというふうに思います。","voiceIndex":159,"id":"exchange-075"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"４００人も待っています。こんなやり方をとっているのは品川区だけですから。この特別養護老人ホームでも介護で差別をする、こういうふうなことはぜひ改めていただきたいというふうに思います。机上ではなくて、大変な思いをしている人の実態をつかんでいただいて、声を聞いていただいて、深刻な切実な実態に心を寄せていただいて、特別養護老人ホーム、一日も早い増設を求めて終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":161,"id":"exchange-076"},{"speaker":"本間委員","kind":"質問・要望","question":"それはＪＲ東日本大井町駅東口の夜間のシャッターのしめる時間が２１時となったとのことです。私たちのほうではＪＲ東日本東京支社等にも請願行動に行っておりますが、品川区でも区長始め、ＪＲ東日本株式会社に陳情行動を、今後ともどのようにして取り組みを進めていかれるのか、見通しについてお伺いしたいと思います。","respondent":"岩田まちづくり事業部長","answer":"しかし１０月１５日、その回答がございましたけれども、ＪＲの経営上の問題であるので、ぜひご理解を願いたいという回答がまいりました。","voiceIndex":163,"id":"exchange-077"},{"speaker":"本間委員","kind":"質問","question":"なぜこの件を追いかけて質問したかと言いますと、聞いた話ですが、他の区では、ＪＲの駅との話し合いによりまして、時間の変更を伴う改善があったということを聞いたからです。引き続きよろしくお願いします。次に、旧都南病院跡地総合福祉施設の周辺の道路整備についてお尋ねします。この歩行者のための安全対策、周辺道路の安全対策の面についての取り組みについてお伺いいたします。","respondent":"岩田まちづくり事業部長","answer":"すぐできることと、長期的に検討しなければいけない課題があるわけですけれども、当面、来年度、特に指摘の大きかったゼームス坂の歩道部分の改良にとりかかることとしております。信号やあるいは点字ブロック等の対策もあわせて来年度中に行う予定にしています。","voiceIndex":165,"id":"exchange-078"},{"speaker":"本間委員","kind":"質問・要望","question":"新・水とみどりのネットワーク構想における水辺空間の活用についてのお考えをお伺いいたします。天王洲、勝島、花街道などのつながりはどのようにとらえているのでしょうか。そして、さらにロードマップ作成などの、これまでしながわ観光協会が作成しております１０通りほどのものがありますが、それらに追加して、品川の散歩道としての今後お考えを取り入れることができるのかどうか、お尋ねします。","respondent":"岩田まちづくり事業部長","answer":"具体的な問題は、今後の長期基本計画の中で年次計画をつくりながら定めていくことになりますけれども、どちらにしましても、目黒川と立会川を結ぶ動線が新たに水辺の空間の中でつくり上げられていくことになりますので。","voiceIndex":167,"id":"exchange-079"},{"speaker":"本間委員","kind":"質問・要望","question":"これまで立会川、目黒川の浄化につきましては、本年度７億３,２００万円の予算がついております。次に行きます。資源回収事業の諸問題についてお伺いいたします。回収車を他の車と区別するために、品川区のシンボルカラーを明示するなり、あるいは小旗を掲げるなり、何らかの方法もとられてはよろしいのではないかというふうな部分も思いますので、この辺についてのご見解をお尋ねいたします。","respondent":"岩崎環境清掃事業部長","answer":"これは重要なことだろうと思っておりまして、その辺の相談を緻密に詰めておるところです。７月の開始までにその辺をはっきりさせて周知徹底を図っていきたい、こういうふうに考えております。","voiceIndex":169,"id":"exchange-080"},{"speaker":"本間委員","kind":"質問・要望","question":"このようなことで最近の状況を見ますと、この利用状況について、年々横ばいのようなふうに伺っておりますけれども、交流ですから、私たちが早川に行く、早川からこちらに来る。特に子どもにおかれましては、品川区のほうに、あるいは東京のほうに来る場合に、どのようなところにご案内をされているのでしょうか。都内での宿泊場所はどこなのでしょうかということについて、お尋ねしたいと思います。","respondent":"田中区民生活事業部長","answer":"戸越台の特養ホーム等、品川のスポット的ないいところということで、早川町の側で考えてきています。宿泊場所ですが、平成１５年までは大井荘に泊まっていましたが、平成１６年以降はゆうぽうとに泊まって、肌身で品川のまちの様子を感じるというところで交流をしています。","voiceIndex":171,"id":"exchange-081"},{"speaker":"本間委員","kind":"質問・要望","question":"次に行きます。保育園の待機児解消について、お伺いします。しかし最近の状況を見ますと、徐々に状況は変化してきておりますが、本年ほど保育園入園についての要望が殺到した時期はありません。私たちの周辺でも４月以降の件につきまして、子どもをどうするのか、あるいは自分の仕事が復帰できるのかどうなのかというふうな話をよく聞いております。","respondent":"古川児童保健事業部長","answer":"正直なところ、私どもも施設サービスをかなり、保育園の増設でありますとか、あるいは弾力化、さらには認証保育所の助成、認定こども園、幼稚園の預かり保育と、いろいろな策をとりながら、一人でも多くの方々の就労と子育ての両立を支援したいな。","voiceIndex":173,"id":"exchange-082"},{"speaker":"本間委員","kind":"提案","question":"その件につきましては、品川保育園の分園化についてとか、あるいは小学校の空き室の活用などについて等々も含めまして、当面を乗り切る受け皿としての方策、ここ緊急措置としての対策として、そのような、これまでできなかったこと、あるいはやったことのなかったことだと思いますけれども、そのようなことについてのお考えについてご意見を伺いたいと思います。いかがでございましょう。","respondent":"古川児童保健事業部長","answer":"今、委員のほうからご指摘がございましたように、まず私ども児童保健事業部が所管しております保育園、そして児童センター、幼稚園もその一つですし、場合によっては教育委員会へのさまざまなご協力依頼もあるかもしれませんが、いずれにいたしましても。","voiceIndex":175,"id":"exchange-083"},{"speaker":"本間委員","kind":"確認","question":"しかも、そのことによって、どうなのかなと私どもも思いましたが、近くの公園を予定をし、実はこの３月に晴れて東京都認証保育所としての申請が許可されたということをお聞きしたからです。次に行きます。二重チェック制の導入や着工前の審査建築確認申請などが厳格化され、手続が著しく滞っているためだというようなことでございました。そこでお尋ねします。この辺について、お尋ねをいたします。","respondent":"岩田まちづくり事業部長","answer":"昨年１２月に、この従来ワンルームの指導指針という形で建設業者の皆さんを指導させていただいておりましたけれども、改めて要綱という形で、形を変えて本年４月１日から施行する予定です。","voiceIndex":177,"id":"exchange-084"},{"speaker":"本間委員","kind":"質問・要望","question":"どうかこれからも、私どもはこの件について建物を建てさせないという点でのお話し合いではございませんで、いつも地域の人々と、業者側との間では必ずトラブルが起きるわけですけれども、ともすると、本来の趣旨とは違った形の、あるいは地域の人たち、住んでいる住民の人たちと、本心とは違った形のやりとりがなされる場合がありますので。","respondent":"田中区民生活事業部長","answer":"町会、自治会の加入率の低下、それから担い手の高齢化というところで、今事業目的の紹介がありましたが、具体的に町会の紹介のパンフレット等を各連合町会単位に作成していく予定です。","voiceIndex":179,"id":"exchange-085"},{"speaker":"本間委員","kind":"質問・要望","question":"実際にやめたところがあります。そして、まちの行事の中で、みんなで年に一遍あるいは２年に一遍の大きな神輿を出す行事なんかがありますが、毎回のごとく、やはり時間的にも大変、夜遅くなる時間帯ではありますけれども、警察のほうから苦情が来ます。そして、リーダー育成と組織育成について力を入れていただきたいと思いますが、この辺について、最後、短い時間ですが、ご見解をお伺いします。","respondent":"田中区民生活事業部長","answer":"そういう先進的な町会の例等を、来年度以降、研修会等の中で情報交換して、横に広げて、それぞれの町会、自治会が活発になって、さらに連携を深めていくよう努力していきたいというふうに考えております。","voiceIndex":181,"id":"exchange-086"},{"speaker":"本間委員","kind":"質問・要望","question":"最後になりました。人口が増えると新しいいろいろな考え方の人も入ってくる。その中で歴史的な経過が本来の軌道から外れないような形にしていただきたいというふうに思ったからです。そのような中で組織づくり、そして立派な人づくりについて、これまで、ともすると助成金を出していれば済むというようなことではなくして、人づくり、組織づくりのために力を尽くしていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":183,"id":"exchange-087"},{"speaker":"高橋委員","kind":"質問","question":"初めに、品川区立学校教員の独自採用についてお尋ねいたします。そこでお尋ねします。この教員独自採用に関して、国としての考え方、例えば中教審の考え方など、どのようなものでしょうか。お伺いいたします。それを受けて、平成２１年からの採用の予定を当初何人の採用をしていくのか、そして長期的な採用の人数的な見通しはどのようなものになるのでしょうか。お尋ねいたします。","respondent":"長田教育次長","answer":"人数ですけれども、人数につきましては、午前中の質問でもお答えをいたしましたけれども、平成２１年度から当面数名ずつ採用をしていくつもりです。","voiceIndex":186,"id":"exchange-088"},{"speaker":"高橋委員","kind":"質問","question":"ただいまありました、この教員の人数、最終的には状況に応じてということでありますが、行財政改革を進めている中で、その教員増加分の予算についての手当はどのようなふうに進めていかれるのでしょうか。","respondent":"長田教育次長","answer":"今回、この独自の採用という部分につきましては、それ以外ですので、これにつきましての必要経費につきましては区単、区の単独の負担、こういう形になってあります。","voiceIndex":188,"id":"exchange-089"},{"speaker":"高橋委員","kind":"質問","question":"平成２１年度導入ということですので、今年度は教員の採用試験が行われる予定だとお聞きしております。独自採用ということですので、採用試験は例えば東京都などとは別に実施されると思います。採用試験の実施の時期と、その時期に独自採用の試験を設定したお考え、それと試験の科目等、これはどのような人材を確保するかというお考えがあってのことだと思うんですが、そちらをお尋ねいたします。","respondent":"長田教育次長","answer":"ただ、品川区の今考えている部分につきましては、できるだけ現場で、今、学校現場で何らかの形で子どもの指導に当たられる人、即戦力としてそういう熱意のある、経験のある人を採用したいというようなことで思ってありますので、そういったことからすると。","voiceIndex":190,"id":"exchange-090"},{"speaker":"高橋委員","kind":"意見","question":"品川区がほかの自治体にないと、あるいは品川独自の育成プログラムでこの独自採用の教員を育てていこうというような研修や育成の仕組みについて、区のほうでどのようにお考えか、お答えください。","respondent":"長田教育次長","answer":"そういったことからすれば、当然ほかの教員と同様に、新規の採用者研修、こういったものも実施をいたしますし、それから、それぞれの必要に応じまして、１０年研修ですとか、そういった通常の教員もやっていく研修。","voiceIndex":192,"id":"exchange-091"},{"speaker":"高橋委員","kind":"質問","question":"次の質問に移らせていただきます。特別支援教育の充実についてお尋ねします。小学校、中学校における介助員の制度についてお尋ねします。特別支援教育に果たした役割というのはとても大きなものがあると思います。子どもたちや保護者の方々の信頼も大変厚かったと伺っております。これまでの介助員制度が特別支援教育に果たした役割、それに対する評価、これを区のほうはどうお考えか、お尋ねします。","respondent":"長田教育次長","answer":"特別支援教育における介助員の評価ですけれども、私どもは特別支援教育が始まる前から、普通教室の中でそれぞれの症状に応じた教育というものを実施をしてまいりました。","voiceIndex":194,"id":"exchange-092"},{"speaker":"高橋委員","kind":"質問・要望","question":"その介助員制度の成果を踏まえて、平成２０年度にはこの特別支援教育をさらに充実させる形で、制度の改正というか、新しい制度を導入されるということでありますけれども、その特別支援教育を充実させる新しい仕組みを導入するに至った背景、今の評価も踏まえて、ご説明いただきたいと思います。","respondent":"長田教育次長","answer":"こういうことがあります。こうしたことから、これからは、その介助員に加えて学習支援員、学習に対する指導もできる支援員の配置、こういうものを実施をしていきたいというようなことで予定をしているものです。","voiceIndex":196,"id":"exchange-093"},{"speaker":"高橋委員","kind":"質問・要望","question":"そうすると、その仕組みを進めていく中で、事業の委託の、これはまだ予定だと思いますが、その形態とその事業の運営方法で、いままでと違った形でどのような形になるかをご説明いただきたいと思います。","respondent":"長田教育次長","answer":"現在予定しているＮＰＯ法人ですけれども、障害者福祉の面でいままで区との協力関係もありますし、そういったノウハウを持っているというようなこと、それから、そこのＮＰＯ法人と今度一緒に協働するグループですけれども、このグループは学校内での介助や支援に関する実績。","voiceIndex":198,"id":"exchange-094"},{"speaker":"高橋委員","kind":"質問","question":"今、協働というお言葉が出てきたんですけれども、二つの意味でこの仕組みでは協働というキーワードがあると思います。そういう意味では、このＮＰＯなどの専門性を生かす、この複数の団体等が事業を協働していくという、その仕組みは今後のＮＰＯなどへの事業委託にお手本といいますか、いい例となるのではないでしょうか。その点について、お考えをお聞きします。","respondent":"長田教育次長","answer":"そうした意味では、あらゆる地域の人材等も活用しながら、教育のほうも進めていきたいというふうに思っているところです。","voiceIndex":200,"id":"exchange-095"},{"speaker":"高橋委員","kind":"質問・要望","question":"もう１点だけ、この件でお尋ねしたいと思います。先ほども研修の話を伺ったんですが、こちらの介助員、学習指導員に対する研修は、これまでの介助員制度とは異なり、研修制度が新たに幾つか導入されると伺っております。その点についてが一つ。その点についての仕組みも新たに幾つか始められるというふうに伺っておるのですが、その点についてご説明をいただきたいと思います。","respondent":"長田教育次長","answer":"そういった部分での研修、これは月１回カウンセラーによる研修等もありますので、こちらのほうは定期的な形で研修を実施をしていきたい。このように思っているところです。","voiceIndex":202,"id":"exchange-096"},{"speaker":"高橋委員","kind":"質問・要望","question":"それには、いわゆる行政の縦割りの弊害を廃し、そして大胆な策も求められていくと思います。そこで、お尋ねをいたします。この支援施策を療育全般としてコーディネートするために、現在の品川区の特別支援ネットワーク体制について現在どんなお考えで整備されているか、そして特に平成１９年度ではどのような点でそのネットワークづくりに関する事業が行われたか、お尋ねいたします。","respondent":"長田教育次長","answer":"他部局との連携ネットワークというようなお尋ねです。平成１６年につきましては、特別支援に関して言えば、特別支援教育検討委員会というものを設けてまいりました。この中で特別支援にかかわる進め方、それから連携のあり方、こういったものを探ってまいりました。","voiceIndex":204,"id":"exchange-097"},{"speaker":"高橋委員","kind":"意見","question":"平成２０年度においては、このネットワーク体制に関しては平成１９年度までの経緯を踏まえて、具体的にどのような療育事業の改善といいますか、発展といいますか、特に相談事業と療育事業をつなぐというところが大変必要なところではないかと考えています。その点について、平成２０年度からの事業の構築をご説明いただければと思います。","respondent":"木下福祉高齢事業部長","answer":"特に今お話がございました発達障害と思われる子どもの療育ということでは、相談と療育事業というのを一貫して行うほうが一元的な対応ができるだろうということで、新年度におきましては、昨年始めた、品川児童学園で療育指導を行っておりますけれども。","voiceIndex":206,"id":"exchange-098"},{"speaker":"高橋委員","kind":"質問・要望","question":"これらのさまざまなＮＰＯやボランティアが連携し、ネットワークを持つことで、地域のまちづくりはさらによりよくなっていくのではないでしょうか。ここでお尋ねします。品川区は、このネットワークづくりについて、平成２０年度ではどのように事業を展開していくのでしょうか。具体的には多機能な協働支援センター的に役割を果たす仕組みづくり、どのように取り組んでいかれるつもりなのでしょうか。","respondent":"福田企画部長","answer":"このことの把握に努めてまいりたいというふうに考えております。","voiceIndex":208,"id":"exchange-099"},{"speaker":"高橋委員","kind":"質問・要望","question":"では次に、そのＮＰＯの運営事業費についてお尋ねいたします。しかし、なかなかそれができない。そこで、ＮＰＯに対する委託費の前払いの可能性についてお尋ねします。現行の規程、規則を改正しなければ前払いはできないのでしょうか。今年度、ＮＰＯに事業委託する場合は、その団体の資金状況等を十分に聞き、最大限の配慮をしていただきたいと考えていますが、区の見解はいかがでしょうか。お願いします。","respondent":"西島会計管理者","answer":"ただ、ご質問にもありますように、経済的基盤の弱いＮＰＯの現状は十分理解できるところですし、またＮＰＯ支援という観点からも、今後所管と事業を実施する際には十分協議をしてまいりたい、かように考えているところです。","voiceIndex":210,"id":"exchange-100"},{"speaker":"西本委員","kind":"質問","question":"無所属の会を代表しまして総括質問をいたします。今回は、区民の健康づくりにおけるスポーツ振興について総括的に質問をいたします。その思いを含めて質問をいたします。それを見通して新たに制定された品川区基本構想はどういうものなのか、平成２０年度には長期計画が策定されると思いますが、どのような考えで長期計画、行動計画まで行うかをまず伺っておきたいと思います。よろしくお願いします。","respondent":"早津区民生活事業部次長、古川児童保健事業部長","answer":"具体的な仕組みはどうなっているかですが、巷間言われますように腹囲測定ですね、お腹の周りのセンチが男性８５とかという、そういうものを基軸にしまして、あと３項目、これは血糖と脂質と血圧、この３項目を組み合わせまして。新しい長期計画におきましては、みずからの健康は自分でつくる、こういう視点から健康づくりを総合的に推進するための施策を検討してまいりたい、このように考えております。","voiceIndex":213,"id":"exchange-101"},{"speaker":"西本委員","kind":"質問","question":"私は冒頭に申しました、健康づくりとそれからスポーツ振興というのが非常に密接している、疾病にならないような形で予防対策していかなければならないんだという視点に立ちますと、この基本構想の中で別々に提示されているということよりは、これを横断的な形で基本計画、行動計画までつくっていかなければならないのではないかなというふうに思いますが、その点の考え方をお願いしたいと思います。","respondent":"福田企画部長","answer":"したがいまして、それぞれ別個のものであるというふうには認識しておりません。しかし、それは理屈の話ですので、委員のご趣旨がよく反映できるように、これから長期基本計画の策定に取り組んでまいりたいというふうに考えております。","voiceIndex":216,"id":"exchange-102"},{"speaker":"西本委員","kind":"質問・要望","question":"それに合わせまして、具体的にお聞きをしていきます。年齢によって、健康づくりの考え方、とらえ方があるかと思います。そのお考えをお聞きいたします。さきに実施されました団塊世代のアンケート調査ではどのような傾向にあるのか、また健康づくりにおいて、どのような考えでいるのか、調査結果から考えられることをお聞きしたいと思います。","respondent":"古川児童保健事業部長、木下福祉高齢事業部長","answer":"今後長期基本計画を策定する中で、食からの健康づくりでありますとか、あるいは生涯を通したスポーツの振興のための、身近に運動できる場や機会の提供、こういったものを各事業部が連携をしながら。ただ、足立区でも類似の調査を行いましたけれども、そちらは２１％ですので、それよりはいいわけですが、これは団塊としてひとくくりにされることについての抵抗感があるのではないかなというふうに想像できまして。","voiceIndex":218,"id":"exchange-103"},{"speaker":"西本委員","kind":"質問","question":"ですから、そういうアンケートの結果の中でもいつまでも元気で働き現役でいきたいんだという思いがあらわれているのかなというふうに感じました。場所の供給ですね、需要と供給のバランスというのは現在どうなっているんでしょうか。それから、将来はどうなっていくと考えておられるのか、またその課題をどうとらえているのか、現状をお聞きしたいと思います。","respondent":"長田教育次長","answer":"それに伴いまして団体数も増えてきている。これが現状だというふうに認識をしています。それから、あともう一つは、一つの競技でも年代ごとにクラブができてきているというのも一つの傾向かというふうに思ってあります。","voiceIndex":221,"id":"exchange-104"},{"speaker":"西本委員","kind":"質問・要望","question":"この現状として、このスポレク委員会という形で調整をしておりますけれども、もしも新しいクラブができた場合、どういう形で申し込みをすれば使えるようになるのか、また、先ほどのご答弁にもありましたように、重なってしまった、そういう場合には調整方法はどのようにされているのか、そして調整、スポレク委員会のほかに体育指導委員という方たちもおられると思うんですが、この方たちは。","respondent":"長田教育次長","answer":"それぞれエリアを１７に分けまして、そのエリアの中での特に夜間開放、校庭の夜間開放と体育館の調整を主な目的に実施をしているわけですけれども、各地区ごとに利用される予定の前月の月初め、こちらでスポレク調整会議という会議を開催します。","voiceIndex":223,"id":"exchange-105"},{"speaker":"西本委員","kind":"質問・要望","question":"ただいまスポレク調整会議の流れ等々を教えていただきましたけれども、もう一度確認のためにお聞きしますが、新しくクラブに入ってきた場合、体育館があいていれば使えるというところでしょうが、あいていない場合には、次の月の初めでしょうか、調整会議の中で調整をしていく。そうすると、新しくクラブの方たちというのは、自動的にスポレク委員会という形の中に入っていくんでしょうか。","respondent":"長田教育次長","answer":"基本的にはそういうことです。それから、そのことをだれが説明するのかというようなことですけれども、まず、スポレクには、それぞれの地域から、チームから選出をされた代表者がおります。","voiceIndex":225,"id":"exchange-106"},{"speaker":"西本委員","kind":"質問","question":"そこの調整の仕方の中で、やはりそのだれが調整していくのかというところ、特にたぶんうまくやっているところは、きちっとした考え方の中で調整をされているんだと思います。ただ、多々もめているところもあるやに聞いておりますので、そのところの場合に、どのようにしたらうまくいくのかなというところをどのように区としては考えておられますでしょうか。","respondent":"長田教育次長","answer":"それからもう一つは、同じ競技、競技については場所はもう限られているわけですから、２チームが一緒に合同練習等ができないかという中で、実際に２チーム、３チームが合同して練習をしているというようなケースも数多く見られます。その中で、もめることも確かにあります。","voiceIndex":227,"id":"exchange-107"},{"speaker":"西本委員","kind":"質問・要望","question":"確かに自主的な調整をしていただきたい、これは本当に今品川区が目指している民主的な自主的な活動で、いろいろまちづくりをしましょうというところになると思いますが、ただ、そうなりますと、では区はどうなるのと、どういう関与の仕方があるんだろうか、先ほどからもめた場合のとりでとなるところがどこなんだろうか、スポレク委員会でもめてしまった、調整がつかない。","respondent":"長田教育次長","answer":"もめたときを想定をして、マニュアルあるいはＱ＆Ａをつくってはどうかというようなお話ですけれども、現在１７地区、ほとんどがうまくいってあります。","voiceIndex":229,"id":"exchange-108"},{"speaker":"西本委員","kind":"質問・要望","question":"マニュアル、かたく考える必要はなくて、やはり譲り合い精神というのを思い出させる、それからいろいろな方法があるんだよと、体育館を何も１団体の中で使うことではなくて、人数によっては２面とれる可能性もありますし、いろいろなそういう使い方があるわけですから、それを何かしらの形で周知徹底する、マニュアルをつくらなくても体育指導委員の方たちが調整役を。","respondent":"長田教育次長","answer":"マニュアルの作成につきましては、ご意見ということでお伺いをさせていただきまして、今後マニュアルの効果等々も含めまして、少し検討をしてまいりたいというふうに思ってあります。","voiceIndex":231,"id":"exchange-109"},{"speaker":"西本委員","kind":"質問","question":"ぜひスムーズにいくように調整をお願いしたいと思います。総合型地域スポーツクラブというのはそもそも何なのかのご説明、それから、なぜこのような考え方になってきているのか、その目的をお聞きします。その関係が現在どのようになっていて、今後総合型地域スポーツクラブになっていった場合に、どういうかかわりになってくるのかについて、お聞きしたいと思います。","respondent":"長田教育次長","answer":"これの特徴といたしましては三つの多様性ということで言っておりまして、一つは種目の多様性、それから年齢の多様性、技術レベルの多様性、こういったものを含めまして、一定の指導者のもとに活動拠点を持って自主運営をする、こういう基本の考え方のもとに。","voiceIndex":233,"id":"exchange-110"},{"speaker":"西本委員","kind":"質問","question":"国の考え方がわかりました。では、品川区としては今後これをどのように考えていくのかという品川区サイドの考え方、それから、先ほどちょっと質問いたしましたが、スポレク委員会と、それからスポーツ協会というのもあります。組織的な課題というのはないのかというところのご答弁をもう一度お願いします。","respondent":"長田教育次長","answer":"各種目の技術的な指導者、こういった部分ではスポーツ協会が果たす役割は大きいのかな、こういうふうに認識をしています。","voiceIndex":235,"id":"exchange-111"},{"speaker":"西本委員","kind":"質問","question":"現在のスポレク委員会というのは非常に大きいと思うんですね。一つの体育館を使うにしても３０団体、４０団体はいるかもしれません。その辺はどういう形で、かなりてこ入れをしていくのか、進め方としてどういう進め方になっていくのか、今後についてお聞きしたいと思います。","respondent":"長田教育次長","answer":"こちらにつきましても、やはり住民主体の組織ですから、行政については側面支援というような形で見守ってまいりたい、このように考えてあります。","voiceIndex":237,"id":"exchange-112"},{"speaker":"西本委員","kind":"質問・要望","question":"それをうまく融合していくということが、今後の地域の活力といいますか、地域力を強めるということにもなると思いますので、ぜひいろいろ検討していただきたいと考えています。その絡みを、どういうふうな形にしていくのかなというふうに、将来的にこの二つの動きがあるわけですから、その動きをどういうふうに区としては考えていこうとしているのか、お聞きいたします。","respondent":"長田教育次長","answer":"一つは八潮の問題です。委員ご指摘をいただきましたとおり、八潮のまち全体を考える中で、一つ、分科会の中で八潮地区のスポーツを通じたまちづくり、こういったようなことを検討しているというようなことについてはお聞きをしています。","voiceIndex":239,"id":"exchange-113"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、八潮地区の動きも私は歓迎しているところはありますが、ただ片や地域の総合型が入ってまいりますので、そこの連携をいろいろ考えていただきたいなと考えています。別々にこう、動くというよりは、やはり相互が協力しあって融合しながら、それぞれのいいところを進めていくというところがぜひ必要なので、よろしくお願いしたいと思います。","respondent":"福田企画部長","answer":"こうした条例の趣旨ですとか、それから基本構想の趣旨、これを生かせるような組織はどういうものか、こういう問題意識を持ちながら検討を進めてまいりたいというふうに思っております。","voiceIndex":241,"id":"exchange-114"},{"speaker":"井上委員","kind":"提案","question":"生活者ネットワークは市民が自治するまちづくりの提案を一貫して進めてきました。自治する市民とともに市民主体のまちづくりが実現していくことを求めて、品川区生活者ネットワークを代表して総括質疑を行います。そこで伺います。２００６年からボランティア、ＮＰＯとの連携、協力の仕組みづくりに取り組んでいますが、この仕組みづくりに着手した背景と到達点を、どこなのか伺います。","respondent":"福田企画部長","answer":"どういう具体的な支援策が有効なのか、このことの検討を区とともにしていただきたいというふうに思っておりまして、これは長期基本計画の策定と同時並行で進めてまいりたいと考えています。","voiceIndex":244,"id":"exchange-115"},{"speaker":"井上委員","kind":"質問・要望","question":"いままで庁内で検討の仕組みをされてきているので、そろそろ区民の参加でというところを期待をしていましたので、すぐにでも進めていただきたいと思うんですが、先ほど答弁された会議というのが、どういった団体代表と考えておられるのか、対象ですけれども、それと、団体数と平成２０年度すぐにということですが、いつごろその会議を発足されるのか、改めて教えてください。","respondent":"福田企画部長","answer":"その中で立ち上がる時期でありますが、これは４月になればすぐに、できるだけ早く立ち上げたいです。それから、活動の内容でありますが、先ほど申し上げたとおり、どういう支援のための施策が有効なのか等について意見交換をする、これが主な活動の要素です。","voiceIndex":246,"id":"exchange-116"},{"speaker":"井上委員","kind":"質問・要望","question":"私が読ませていただいた「協働コーディネーター」でもそういった活動をされている方がおりましたけれども、ぜひそういった方をアドバイザーとして求められて、区内の事例だけではない、紹介をしていただいて、本当に必要とする支援がどんなことなのかというところを幅広く検討していただきたいということを要望したいと思います。","respondent":"木下福祉高齢事業部長","answer":"具体的なところでは、いわゆる学習の機会を設けるとともに、実際、今ＮＰＯとかボランティアで活動している活動の紹介、それから具体的な自主性につなげる、場合によってはシニアネットの第二グループができ上がっても構わないと思いますし。","voiceIndex":248,"id":"exchange-117"},{"speaker":"井上委員","kind":"質問","question":"そしてボランティアやＮＰＯを上位に挙げた人は１割に満たない結果となっていました。区としても今後、担い手不足が懸念される地域福祉事業をつくり出していくことが必要ではないでしょうか。行政の役割として社会貢献意識を喚起し、協働の担い手を育成し、事業を生み出し、独立することを目的にした講座を行う地域大学を開校したらと思いますが、見解を伺います。","respondent":"福田企画部長","answer":"したがいまして、協働の施策はいろいろなものが考えられるかもしれませんが、やはり地域の皆さんの声をよく聞きながら、十分にそれを把握して、その仕組みあるいは施策はどうあるべきか、このことを検討するべきではないかというふうに思っております。","voiceIndex":250,"id":"exchange-118"},{"speaker":"井上委員","kind":"質問・要望","question":"高齢化社会においては、家族によるケアから社会的なケアへの転換がさらに求められています。高齢者の見守りネットワークや、悪質商法防止ネットワークなどが、既存の任意団体をよりどころに、安易に地域に依存するという流れになっていないでしょうか。そのようなために、区民の参加をぜひ呼びかけてほしいと思いますが、実際にこの高齢者の見守りネットワークはどのような取り組みをされていくのでしょうか。","respondent":"木下福祉高齢事業部長","answer":"地域福祉、今回やさしいまちづくり計画をやっておりますけれども、あそこで言っているお節介運動というのがありますけれども、精神は同じだと思うんです。そういうことを、この中で進めていきたいというふうに思っております。","voiceIndex":252,"id":"exchange-119"},{"speaker":"井上委員","kind":"質問","question":"費用は社会福祉協議会から助成され、参加者は４００円の参加費を払っています。他の自治体ですが、おおむね４時間の会食を交えた交流で「支えあいミニデイ」という事業があります。自宅を開放している方には１回１,０００円が助成される制度もあります。地域に集まりの場が、住民が一緒につくる環境を検討してほしいと思いますが、いかがでしょうか。","respondent":"木下福祉高齢事業部長","answer":"そういう点で、今後とも、今、企画のほうでボランティア、ＮＰＯとの連携の仕組みづくりというのがありますから、既に社会福祉協議会で持っている、これは福祉を中心にしておりますので、こういう仕組みをそれぞれうまく調整する形で発展できるような展開を。","voiceIndex":254,"id":"exchange-120"},{"speaker":"井上委員","kind":"提案","question":"この部分にいけば、参加者１５人以下が１回１,０００円、１５人以上が１,５００円の運営助成があります。ぜひ定期的にこのような機会を設けることを提案したいと思いますが、見解を伺います。次世代育成の視点でも基本構想にある「輝く笑顔住み続けたいまちしながわ」の実現にも子ども会議の開催をぜひ検討していただきたいと思いますが、いかがでしょうか。","respondent":"福田企画部長","answer":"それで、子ども会議にこれは限ることではないのですが、そのほか、子どもにふさわしいようなテーマがあれば、それはその都度子どもたちを協働の相手として呼びかけてまいりたい、このように考えてあります。","voiceIndex":256,"id":"exchange-121"},{"speaker":"井上委員","kind":"質問・要望","question":"子どもたちが小学校、中学校、そういった機会で、そこに在籍する間に一度でもそういった機会があれば、大変子どもたちにとってすばらしい経験になると思うんですが、一つだけ要望があります。課題は区が考える課題ではなく、子どもたち自身が考える課題として、ぜひ子ども会議を取り組んでいただきたいというふうに要望しておきます。お伺いいたします。","respondent":"福田企画部長","answer":"事業数でありますが、平成２０年度は大体４０事業ぐらい、いわゆる協働ということを視野に入れた委託関係が中心でありますが、を考えているところであります。","voiceIndex":258,"id":"exchange-122"},{"speaker":"井上委員","kind":"質問","question":"最初に安ければ安いほうがいいという結果ではないということをいただいたので、よしと思ったんですけれども、そのあとで、委託ということではそうですけれども、やはり基準は必要ではないかというふうに思います。委託のガイドラインとかＮＰＯとの事業協定があるのかどうか、ちょっと詳しく教えてください。","respondent":"福田企画部長","answer":"委託ですので、どういう事業をどのような方法によって行うか、そういうようなことについては個々の、協定という名前かどうか、それはいろいろありますけれども、いわゆる合意、こういうものをしながら事業を進めているところです。","voiceIndex":260,"id":"exchange-123"},{"speaker":"井上委員","kind":"提案","question":"これからの地域福祉の分野では、ＮＰＯや市民活動が果たす役割は大変大きくなってくると思います。行政内の協働の意識改革には、縦割り行政に横串を刺す役割の部署の設置をし、予算や人事を含む権限を持たせることではないでしょうか。そして、コーディネート機能を発揮するには、住民に一番近い区民生活事業部の地域活動課と同列で市民との協働を推進するところを設けるよう提案しますが、見解を伺います。","respondent":"福田企画部長","answer":"したがいまして、何らかのいわば専管組織のようなものが必要ではないかなというふうに思っておりますが、ただ、その組織を現在の分掌組織のどういうレベルに設置するのか、このことはむしろこれから検討するべきことだというふうに考えております。","voiceIndex":262,"id":"exchange-124"},{"speaker":"井上委員","kind":"質問・要望","question":"ぜひ前向きに検討していただきたいと思います。地域の課題解決のためには、人材育成と基盤整備が必要です。多様な住民ニーズに対応するには、行政には行政としての税の公平性という制約があり、苦渋の選択ということも理解できます。そこで、新しい公共は市民が柔軟に担うことが大切になります。市民や企業が協力できる品川区市民ファンドの創設についても見解を伺います。","respondent":"福田企画部長","answer":"先ほどもお答えしたんですが、それでは具体的にどういう仕組み、どういう支援策が現実のＮＰＯ、ボランティアの方たちにとって最も望まれているのか、最も効果があるのか、こういうことにつきまして、来月早々に会議を設定いたしまして。","voiceIndex":264,"id":"exchange-125"},{"speaker":"井上委員","kind":"質問・要望","question":"この仕組みをつくるために、今、検討を始めるということでしたけれども、市民活動を支援するという明確なメッセージを区民にぜひ発信していただきたいと思います。基本構想には品川区をつくる三つの理念をうたっています。自治の基本理念をメッセージとして発信していく予定について、お考えがあればお伺いしたいと思いますが、いかがでしょうか。","respondent":"福田企画部長","answer":"自治の基本メッセージといいますのは、行政が一人で机に向かって考えることではないというふうに思っておりまして、まさにその協働という生きた実践を通して、品川区における自治の基本は何なのか、このことを区民の皆さんと一緒に考えて、一定のレベルといいましょうか、時期。","voiceIndex":266,"id":"exchange-126"},{"speaker":"井上委員","kind":"質問","question":"最後です。基本構想策定委員会に出されました長期基本計画の策定スケジュールでは、８月下旬に長期計画素案について討議をし、９月中旬から１０月中旬までパブリックコメントを実施することになっています。８月下旬に素案がまとまった早い時期に内容を説明する機会をぜひ設けてほしいと思いますが、説明会の開催の予定などをお考えであるのかどうか、お伺いをいたします。","respondent":"福田企画部長","answer":"地域別の区政協力委員会、それからタウンミーティング、それから事業者を含む昼間人口世論調査、それから委員もおっしゃったパブリックコメント、こうしたことを通して広く意見を伺ってまいりたいと思いますし、それから、基本構想のパンフレットを作成いたしますので。","voiceIndex":268,"id":"exchange-127"},{"speaker":"井上委員","kind":"確認","question":"拡大とタウンミーティングということでしたけれども、議会は別としてということで、議員がそこに入るのは承知していますが、拡大の意味と、タウンミーティングというのはどういうことなのか、ちょっと確認させてください。","respondent":"福田企画部長","answer":"拡大の意味は、いままでの基本構想等策定委員会を、今度は長期計画策定委員会に名称変更いたしますが、それに伴ってＮＰＯとボランティアの代表者お一人ずつに、この策定委員会の中に参加をしていただいて議論の幅を広げる、そういう拡大です。","voiceIndex":270,"id":"exchange-128"},{"speaker":"井上委員","kind":"質問・要望","question":"できれば「輝く笑顔住み続けたいまちしながわ」というところでは、住み続ける人たちがこの基本計画を共有し、一緒にまちづくりを進めていくというところで進めていただきたいと思いますので、先ほどの答弁では、地域の説明会というところに私は地域センターごとの説明会をぜひとも要望したいと思ったんですけれども、そこのところがちょっとはっきりしなかったので、申しわけありません。","respondent":"福田企画部長","answer":"地域センターごとのという意味ではありませんけれども、タウンミーティング、これを通して一般の方の意見を区長が直接お聞きする、そういう機会については十分に設けてまいりたいというふうに考えております。","voiceIndex":272,"id":"exchange-129"},{"speaker":"井上委員","kind":"質問・要望","question":"ぜひこれから１０年の長期基本計画というところでは、自分たちのまちづくり、住み続けたいまちに向かっての基本的な施策を具体化していくという大変重要な計画ですので、市民とともに、この計画を実践をするためにはたくさんの意見を取り入れていただきたいということを要望いたしまして、私の総括質疑を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":274,"id":"exchange-130"},{"speaker":"石田（秀）委員","kind":"提案","question":"皆保険制度の維持を目的に、後期高齢者医療制度が始まります。さらに、本委員会で我が会派から１００項目以上にわたる質問で行った政策提案、提言の各項目を積極的に取り入れ、予算執行、区政運営に当たることを要望いたします。各会計予算は限られた財源を有効に活用されていると評価いたしますが、再度、組織を見つめ直し、体制強化を図ることを最後に要望し、意見表明とします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":278,"id":"exchange-131"},{"speaker":"堺委員","kind":"提案","question":"区議会公明党を代表して意見表明を行います。昨年の第３回定例会の一般質問において、認可保育園の入園を希望しつつ、認証保育所に入所している家庭の経済的負担を軽減するための助成制度を創設するよう提案いたしましたが、本年度より認証保育所保育料の助成制度を新設するほか、子どもたちによる基本構想策定記念公園づくりや、教員の独自採用と資質向上など、区民要望にこたえた予算を編成されております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":280,"id":"exchange-132"},{"speaker":"菊地委員","kind":"提案","question":"５点について指摘します。特別養護老人ホームは４５０名もの待機者、一日も早い増設を求める声には耳も貸さず、月額利用料が１６万円から２８万円という高額な有料老人ホームを建設、早急に特養ホームの増設を求めるものであります。地方自治体が果たすべき最大の役割である住民福祉の充実を求めるものです。小規模校を否定し、強引に統廃合を進めることをやめ、改めて３０人学級の実現を強く求めるものです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":282,"id":"exchange-133"},{"speaker":"土井委員","kind":"質問・要望","question":"２年目の濱野区長による本格予算の審査を終え、民主品川は、一般会計、国民健康保険事業会計、老人保健医療特別会計、後期高齢者医療特別会計、および介護保険特別会計の各会計予算案のすべてに賛成します。品川の未来を見据えた基本構想と長期基本計画の策定に当たっては、区民との協働、力を合わせて働く、を重視した取り組みを求めます。国などへの申し入れとともに、適切な対応を求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":284,"id":"exchange-134"},{"speaker":"須貝委員","kind":"質問・要望","question":"我が会派は、平成２０年度品川区一般会計、国民健康保険事業会計、老人保健医療特別会計、後期高齢者医療特別会計、介護保険特別会計の各歳入歳出予算の賛成を表明いたします。以下、意見と要望を述べします。このような状況下にありながら、日常品や食品などの生活必需品の急激な物価上昇は多くの品川区民の家計を苦しめていますので、所得格差の広がる中、生活弱者に対してはさらなる支援を要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":286,"id":"exchange-135"},{"speaker":"西本委員","kind":"提案","question":"無所属の会を代表して意見表明をいたします。平成２０年度品川区一般会計予算および各特別会計予算のすべてに賛成いたします。平成２０年度品川区一般会計予算は１,３７６億１,２０９万円で、対前年度比２.３％増のプラス予算となりました。最後に、我が会派委員の提案、要望した各項目について積極的に受けとめていただき、区政運営に生かされることをお願いし、無所属の会の意見表明といたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":288,"id":"exchange-136"},{"speaker":"市川委員","kind":"質問・要望","question":"品川・生活者ネットワークを代表して意見表明をいたします。今後の予算執行に当たって、以下、何点か意見、要望をいたします。長期基本計画策定に当たっては、世代を超えた市民が作成過程に参加し、つくり上げていくことを求めます。区の役割は後期高齢者医療制度の抱える課題をしっかり見きわめ、医療制度改革そのものの見直しを国に求めることです。今後は待機児ゼロへ向けて早急な手だてを求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":290,"id":"exchange-137"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=906#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":120704,"voices":295}},{"id":"h20-20080327-7","meetingId":"h20-cm03","date":"2008年3月27日","dateIso":"2008-03-27","committee":"厚生委員会","time":"午後２時４４分～午後３時０１分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を4件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"議案審査","agenda":"議案審査","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうことで、文言整理ということで、中身は変わらないということでいいのかということを、一つ確認させてください。こういうふうに、厚生労働省の告示が廃止になるということでの規定の整備ということであれば、これは一斉に他区のほうでも変わることになっていくのか、そのことについて、教えていただきたいと思います。","respondent":"太田健康課長","answer":"３点目ですけれども、他区の状況については、ご指摘のとおり、同様に改正をする予定と聞いております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この使用料、具体的には尿検査とか、血液学的検査、レントゲンということですが、具体的には、どういうところに何件ぐらいされているのかということだけ教えていただきたいと思います。","respondent":"太田健康課長","answer":"具体的に申し上げますと、実績ですけれども、例えばエックス線の撮影であれば、平成１８年度で約１,９００件、それからふん便であれば１万５,０００件、尿検査であれば１,８００件、それから、血液生化学であれば約２,０００件という数字になっているところです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"須藤委員","kind":"意見","question":"今、中身が変わらないということでしたが、そのとり方なんですけれども、私は大きく変わったと思うんです。こういうごとに、いちいち条例改正をしなくていいという文言に整理したんで、だから、中身は変わっていませんということではなくて、大きく変わったと思うんです。文言が、もちろん変わるんですけれども、その意義というのは何かというのを言っておいてください。","respondent":"太田健康課長","answer":"委員、ご指摘のとおり、私どもいろいろ、今回改正する中で検討をして、ものの考え方は変わらないということで、直接、法の引用をさせていただいた。結果として、今後、こういう改正は必要がなくなるです。","voiceIndex":9,"id":"exchange-003"},{"speaker":"堺委員","kind":"質問","question":"要するに、こういうのは、あらかじめ、ある一定のことが、いつごろ、どういうふうに変化して、要するに廃止になるとか、直すとか、俗な言葉で言うと、スケジュール統制じゃありませんが、何かそういうもっと現場が困らないような仕組み、スケジュールが組めたらいいなという思いもあるので、ちょっと、その辺どうなんでしょうか。","respondent":"太田健康課長","answer":"通常ですと、前年の１０月ぐらい、今回についても、昨年１０月２６日に調査実施小委員会という附属機関の中で審議をされて、１１月２８日の中央社会保険医療協議会の総会の中で、マイナス改定するのか、プラス改定するのか、しないのかという意見を伺うことになっています。","voiceIndex":11,"id":"exchange-004"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3198#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":5177,"voices":19}},{"id":"h20-20080415-6","meetingId":"h20-cm04","date":"2008年4月15日","dateIso":"2008-04-15","committee":"区民委員会","time":"午後１時０３分～午後３時５９分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を54件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"景気動向を踏まえて区のほうとして上乗せしてということで、利用者の負担のほうは下げたということで好ましいなと思うんですけれども、金融機関との協議があったということだったんですけれども、どのような協議で意見交換があったのかという中身をお聞きしたい。","respondent":"金子産業振興課長","answer":"金融機関との協議の内容というお尋ねなんですけれども、細かいところまでご説明申し上げますと、ちょっと各金融機関の経営の琴線に触れるところもありますので、概略だけお話し申し上げますと、やはり今回２.２％。","voiceIndex":17,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"今回、去年に比べて０.１％下がったということで、どのくらいの方に恩恵があるのかなというのをお伺いしたいと思いまして、そういったことを聞いているんですけれども、それだけお願いします。","respondent":"金子産業振興課長","answer":"しかしながら、事業所数で言いますと、この比率は非常に高くて、うろ覚えで恐縮ですけれども、９５％前後がこれに当てはまるというふうに記憶しています。","voiceIndex":19,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"都のほうは０.２％で変えているんだというご説明もありましたけれども、他区の動向というのは大体どのような感じなのか、つかめていればお伺いしたいと思います。","respondent":"金子産業振興課長","answer":"細かい資金によってかなり利率が違いますので、一概に言うことは難しいんですけれども、ほぼ昨年の１０月と同じ利率で対応されているというふうに聞いてあります。","voiceIndex":21,"id":"exchange-003"},{"speaker":"鈴木（真）委員","kind":"質問","question":"利用者側にとって負担が下がったということは大変好ましいと思います。２.２％が２.３％に増えただけで、もともと変わらない部分なので、利子補給で補うのに何でなのかなというのがちょっと１点疑問に思います。何かもったいないなという気がして。やらないほうがいいのかどうか、その辺の考え方を伺いたいと思います。","respondent":"金子産業振興課長","answer":"借り主の方自体が利率を併記することによって混乱がなければ、そういうようなこともしていきたいと考えていますので、来年度検討します。","voiceIndex":23,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"最後の企画、運営のことなんですけれども、環境活動推進会議委員というところなんですけれども、このような区民に今環境問題について感心が高まっていると思うんですけれども、かなりこういう企画であればいろいろなアイデアをお持ちの方ですとかが相当いると思うんですけれども、この推進会議というものの概要といいますか。","respondent":"工藤環境課長","answer":"先ほどご説明しました環境活動推進会議の委員の概要ですけれども、この会議は５年前に品川区の環境保全への取り組みを区民、事業者、区、社会を構成するすべての人々と協働して進めていくという目的で設置されたものです。","voiceIndex":29,"id":"exchange-005"},{"speaker":"山路委員","kind":"質問","question":"昨年は環境情報センターもされていましたよね、オープンして。いろいろ環境に対する指導を行って、今年はそれはどのような関係になるんですか。","respondent":"工藤環境課長","answer":"当然今年も昨年同様、環境情報センターをオープンさせまして、フェスティバルで来た方も情報センターのほうに寄っていただくという形でイベントをやっていきたいというふうに思っております。","voiceIndex":31,"id":"exchange-006"},{"speaker":"飯沼副委員長","kind":"質問","question":"ＥＣＯフェスティバルは今年何回目になるのか。先ほど目的のところで、交流のイベントであるというご説明があったんですけれども、参加予定団体がおおむね１００団体、この辺の方に呼びかけがいつぐらいから行われているのか、その辺を教えてください。","respondent":"工藤環境課長","answer":"ＥＣＯフェスティバルですけれども、今年度がちょうど４回目になります。","voiceIndex":35,"id":"exchange-007"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"企画・運営のところが環境活動推進会議委員を中心にということで実行委員会ということなんですけれども、この辺、回数がどのくらい行われているのかというところと、品川区の役割というか、品川区がその中でエコに対するアピールとか展示を具体的に何かしているのかどうか。その辺もお知らせいただきたい。","respondent":"工藤環境課長","answer":"最後に、あと１回やるということで１カ月に１回定例的に行っているです。品川区の役割ですけれども、やはり区民の方、事業者、さまざまな団体と協働して行うですので、品川区は実行委員会の事務局として、このＥＣＯフェスティバルを側面から支援する形でやっているところです。","voiceIndex":37,"id":"exchange-008"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"今、地球温暖化の防止の取り組みが本当に世界的にいろいろ広がっている中で、ぜひ区民の方のＣＯ２削減の意識啓発などにすごくいい場だと思うので、品川区がいろいろ取り組んでいることもアピールできるような場にさらになったらいいのではないかなと思いますので、この点は今年も来年の取り組みにもまたぜひ力を入れていただきたいと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-009"},{"speaker":"安藤委員","kind":"質問","question":"実行委員会のほうなんですけれども、環境推進会議の中からという部分ですけれども、大体何人ぐらいでいつもやっていらっしゃるんでしょう。それだけちょっとお聞きしたい。","respondent":"工藤環境課長","answer":"私ども品川区から品川区清掃事務所の職員、環境課以外の職員等が入ってございまして、実行委員会としましてはおおむね３０名ぐらいの中でやっているところです。","voiceIndex":40,"id":"exchange-010"},{"speaker":"山路委員","kind":"意見","question":"その会場の中に環境情報センターと防災センター３階、それもやっぱり入れるべきだと思っているんですけれども、外でやるほうが外のほうがお客さんは多く集まるんでしょうけれども、一応そこも使うということだったら会場の中に名前を入れてもらいたいと思います。","respondent":"工藤環境課長","answer":"今、委員提案の部分を含めまして、周知の仕方等は少し考えてみたいというふうに思っております。","voiceIndex":42,"id":"exchange-011"},{"speaker":"安藤委員","kind":"質問","question":"そこら辺の整合性がどうなのかなということで、ちょっと考え方をお伺いしたいと思います。","respondent":"工藤環境課長","answer":"私どもの第二次計画の実行計画書はそれよりか１年前からの期限ですけれども、必ずしも国のほうでも地域の率先計画と国の計画を一緒にしなければいけないという制約はございませんで、品川区としましては、逆に１年早く京都議定書の達成を行うということで。","voiceIndex":50,"id":"exchange-012"},{"speaker":"安藤委員","kind":"質問","question":"この基準年度は９０年度比ではなくということなんですけれども、これは品川区の関係施設からみると、結構減らしているんだと思うんですけれども、むしろ９０年度比と比べちゃうとかなり削減しているから、今回の９０年度を平成１８年度にしたというのは、むしろ積極的な目標なのかな、どうかなということがわからないんですけれども、そうなのかなということもあるんですが。","respondent":"工藤環境課長","answer":"それで、２点目ですけれども、率先計画でなくて地域全体の計画にということでのお尋ねですけれども、先ほど説明しましたように、品川区は区内の一事業者としてみずから率先して、区民の皆さんの先頭に立って温室効果ガスの削減に取り組むという部分で。","voiceIndex":52,"id":"exchange-013"},{"speaker":"安藤委員","kind":"質問・要望","question":"ＣＯ２を出しているのかということが示されないと、見た目で、ああ、きれいだなということでいいというふうにはもう済まないような世論というのは出ていると思うので、まずそういった地域に環境計画ということで検討していただきたい。それと比べて地球環境をとるのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-014"},{"speaker":"渡辺委員","kind":"質問・要望","question":"今、この資料を拝見した感想から述べさせていただきたいと思います。そこで１点目は、この冊子の部数と主な配布先をまず伺いたいこと。あるいは関心の高い区民の方が大量な部数ではないと思うんですが、求められた場合の対応を伺いたい点と。でも、これを見たら辞書を引くかのように簡単に覚えやすいなという点があったので、この資料のできと、これからの生かし方という点で考え方を伺えればと思います。","respondent":"工藤環境課長","answer":"その他さまざまな区の区民相談室等を考えておりますけれども、こちらのほう、一応６月にホームページに、まだ予定ですけれども、このような計画ができたということでＰＤＦファイルを使いましてアップする予定になってございまして。","voiceIndex":55,"id":"exchange-015"},{"speaker":"山路委員","kind":"質問・要望","question":"ああいうのも支援策とか、ホームページに載っけられたら１３地域センターの地区ごとにＣＯ２をどれぐらい削減したとか、そういう区民がどういう努力をしたらいいかというのを、次のテーマとしての明快な指針を出していただいたほうが、より具体的にＣＯ２は削減が進んでいくと思うんですけれども、何かお考えがあれば聞かせていただきたいと思います。","respondent":"工藤環境課長","answer":"例えば今、さまざまな家庭のコンセントに対してどれぐらいのＣＯ２が出ているのかとか、どれぐらい削減されたのかとか、そういったさまざまな便利なグッズといったものも出てきておりますので、今後そのような部分を検討しながら。","voiceIndex":57,"id":"exchange-016"},{"speaker":"山路委員","kind":"質問・要望","question":"それと室内をきれいにしたら減ったというんです。電気量、ガス量、水道量、こういうところも世界各国からいろいろ情報を取り入れられて、品川なりに区民に参考となるような、ホームページ上であればこういうことも提示してもいいのではないかと思うんですけれどもね、その辺も研究していただきたいと思いますが、どのようにお考えでしょうか。","respondent":"工藤環境課長","answer":"先ほど山路委員からお話がありましたように、２９ページに空調機器のフィルターの清掃等も電気量の削減になると、チェック項目のシートで記しておりますので、今の提案を受けとめまして。","voiceIndex":59,"id":"exchange-017"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"そこまで進まないうちにもっと簡単でわかりやすくして考えていただけないかな。あまり重くしちゃうとね、最初からいっぱいにしちゃうと大変かもしれないけど、少し楽に見られる部分をつくっていただきたいのが１点と。もう既にやっている部分のＩＳＯとしての取り組みをしているんですが、そこをもう一歩進めれば、わりあいと取り組みやすいんじゃないかなという気がして、その辺はどうでしょうか。","respondent":"工藤環境課長","answer":"計画の公表につきましては、冊子丸ごとでやると、なかなかボリュームが多くて見づらいということであれば、少しそういった見せ方という部分も検討してまいりたいというふうに思っています。","voiceIndex":61,"id":"exchange-018"},{"speaker":"渡部委員","kind":"質問・要望","question":"今、ほかの委員からもあったんですけど、学校ＩＳＯとかに関してたしかここまで突っ込んでいない。ルールが変わる。これをじゃあコンセントを外したらどれだけ減りますよみたいなシミュレーションがもし絵とか何かわかりやすく示せるのであれば、１０月ごろに一緒に配ってもらえると一番見てくれるのかなと思いまして、意見といいますか要望といいますか、ちょっとお話しさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":63,"id":"exchange-019"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"ページに沿って幾つかお伺いしたいんですが、１１ページのところに第二次計画はかなり対象施設が広がっています。それをお伺いしたいのと、あと言葉の問題、１９ページのところの地球温暖化係数というのが１となっているんですが、この係数についてちょっと教えていただきたいのと。２５ページのところなんですけれども、平成１８年度を基準年度にして１００をこの計画で９４と。","respondent":"工藤環境課長","answer":"これから第二次ですけれども、第一次と第二次の対象が全く変わり、施設対象がふえまして学校等も入りましたので、第一次と第二次の比較というものは状況的になかなか難しいんですけれども、第一次の始まりから第一次の結果に関しては２５％減った。","voiceIndex":64,"id":"exchange-020"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"そういった面で、第一次のところの２５％というのはすごい努力だなと思っているんですね。品川区のこの間の努力はわかったんですけれども、日本が求められている数字に対して自治体としての品川がどのぐらい頑張って、そこのところを足を引っ張らずに進めているのかどうかというあたりを客観的に知りたいなというところにおいて、２５％の第一次の５年間はわかるけど、その前段階もわからないわけですよね。","respondent":"久保田環境清掃事業部長","answer":"ただ、今後の大きな問題、地球温暖化というのは大きな問題ですので、何とかそういう形での計画あるいはそういうような部分についての検討も必要だろうというふうな認識は持ってあります。","voiceIndex":66,"id":"exchange-021"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"３２ページのところに検討課題等いろいろありますけれども、私なんかは一般質問のときにも自然エネルギー、再生可能なエネルギーをもっと取り入れてもらえないかという質問をしましたが、太陽光発電なんかも設置可能なところから拡大を進めていくというご答弁をいただいたわけなんですけれども、やはり削減をするだけではなくて。","respondent":"久保田環境清掃事業部長","answer":"確かにこの計画の中でいろいろな可能性も盛り込んだ形での検討課題という書き方にしています。","voiceIndex":68,"id":"exchange-022"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"その点が１つ。３２ページで忘れてしまったのが、活用の(1)のところなんですけれども、清掃工場のごみ燃焼による発電電力の購入、これというのは削減よりもＣＯ２に換算したらそれは増えますよね。これをここに載せてふさわしいのかなと疑問を持ってしまったんですけれども、この点はいかがでしょうか。","respondent":"久保田環境清掃事業部長","answer":"は原子力が４０％ぐらいを占めていますので、これは非常に難しい問題もありますけれども、そういう点ではやはりできるだけ効率的に燃やすなり何なりを使って、できるだけ効率的に電気を引き出すというのも１つの削減計画につながるものだというふうに思っております。","voiceIndex":70,"id":"exchange-023"},{"speaker":"飯沼副委員長","kind":"質問","question":"ということは、新たに廃プラスチックの電力化がありますよね。その辺で中身を研究しながら効率をよくしていく中身ですか。今、廃プラの熱を電力にかえる部分、すごく効率が悪いと言われている中身なんですけれども、その中身を改善しながらやっていくという、そういう意味なんでしょうか。","respondent":"秋山資源循環推進課長","answer":"こちらの清掃工場のごみ焼却による電力ということは、すなわち火力発電所等で発生した電力を購入しなくて済むということでのごみによる電力ということで、現在ごみ発電に関しましてはＣＯ２の換算はされておりませんので、その分。","voiceIndex":72,"id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"アセスの話なんですけど、杉並のほうで中間処理施設周辺でプラスチックごみを主とする不燃ごみの圧縮、減容する中間処理施設の周辺で起きた、いわゆる杉並病なんですけれども、まだなかなか原因が、中間処理施設による健康被害だということは認定されたんですけれども、その原因というのはなかなか解明されていないところがありまして、例えば排気の問題、圧縮した際に出た排気を外へ出すわけですけれども。","respondent":"秋山資源循環推進課長","answer":"したがいまして、アセスの項目ですけれども、今のところ、先ほどお話をさせていただきました４項目についてのアセスを実施しています。","voiceIndex":78,"id":"exchange-025"},{"speaker":"安藤委員","kind":"確認","question":"混在ごみの件ですと、ＪＲのほうでというのは結構３分別ということですけれども、わりと大ざっぱというのがすごく印象としてあるんですけれども、それを選別するということもありますけれども、その選別されて残ったごみというのは、どのような処理をされてほかの施設に行くのかということをちょっと具体的にお伺いしたいのと、あと、プラスチックが圧縮される過程で高圧になって、その後強くすり合わさって。","respondent":"秋山資源循環推進課長","answer":"アセスですけれども、こちらの施設は先ほどもお話をしましたように一般廃棄物の処理施設ということで、廃棄物の処理及び清掃に関する法律の一般廃棄物という形になりまして。","voiceIndex":80,"id":"exchange-026"},{"speaker":"安藤委員","kind":"質問","question":"やはり大田青果市場が近くにあるので、食品などを扱うところですので、やはり新たな処理施設ができるとなると、当然いろいろと心配が出てくるのは当たり前なんですけれども、その説明というのはどういうふうな理解というか、そういったことをちゃんとしなくてはいけないと思うんですが、その辺はどうなんでしょうか。","respondent":"秋山資源循環推進課長","answer":"説明についてですが、こちらの施設、開発指導要綱に基づきまして説明会を開く予定ですし、今回、建築基準法の第５１条ただし書ということで、こちらの許可の基準の中にも近隣１００ｍの住民に説明をということで基準を設けてありますので。","voiceIndex":82,"id":"exchange-027"},{"speaker":"安藤委員","kind":"質問","question":"１点だけ。そこに関してやはり第２、第３の杉並病の発生というのは絶対防がなくてはいけないと思いますので、全部そういった可能性も含めて、きちんと区の説明としてチェックをしていく必要があるのではないかというふうに思うんですけれども、いかがでしょうか。","respondent":"秋山資源循環推進課長","answer":"現在、列車ごみの処理については上野の地下で行っておりまして、そちらについてもそういうような問題は生じていないというふうに報告も受けておりますし、こちらの未分別品につきましての問題については、特に私どもとしても問題ないというふうに考えているところです。","voiceIndex":84,"id":"exchange-028"},{"speaker":"鈴木（真）委員","kind":"意見","question":"ちょっと頭がごちゃごちゃになったのでもう１回整理させてください。分別の施設ですよね。いろいろな車両から出たごみをここへ持ってきて、産業廃棄物と一般に分けてという中で、大もとがごちゃごちゃになっているんですけれども、事業者ＪＲが出してくるごみというのは産廃じゃなくて一般事業ごみなのかなという、そこら辺を１点まず聞かせてください。","respondent":"秋山資源循環推進課長","answer":"ただ、ペットボトルにつきましてはプラスチックということで、産業廃棄物には該当いたしますけれども、今回の破砕という処理はペットボトルについては行いませんので、産業廃棄物の処理施設の設置許可は必要ないです。","voiceIndex":86,"id":"exchange-029"},{"speaker":"鈴木（真）委員","kind":"意見","question":"最初がちょっとわからなかったんだけれども、一緒にして持ってくるときには、そのごみというのは産業廃棄物なのか一般廃棄物なのか、そこが自分の中でわかっていないので、そこをちょっと整理させてもらおうと思ったんです。","respondent":"秋山資源循環推進課長","answer":"現在の東京都の判断としては、こちらについてはまだ有価物を含んだＪＲの占有物という扱いでこちらまで運ぶということで、八潮で初めて分けて産廃と一般とに位置づけるというのが東京都の判断です。","voiceIndex":88,"id":"exchange-030"},{"speaker":"鈴木（真）委員","kind":"確認","question":"それを聞きたかったんですけど、一般廃棄物だから都市計画審議会にかかるという説明があった中で、何で区の都市計画審議会にかかってくるのか。なぜ、今のこの段階で、でき上がっていない施設の中にそこまで指定しちゃうのかなという、そんなやり方は今まで品川の中で、ほかのものではこういうことはあるのかという確認をしたい。","respondent":"秋山資源循環推進課長","answer":"家庭系の廃プラスチックのケースですけれども、現在民間の施設で処理を行っているところですけれども、民間施設が処理能力の制限というのがございまして、将来的に容器包装で処理量の増が考えられますので、それを見越して今回。","voiceIndex":90,"id":"exchange-031"},{"speaker":"鈴木（真）委員","kind":"質問","question":"大田では都計審で出なかったのが、すぐ隣地で品川に都計審で最初からオーケーが出るような話が出てってしまって、先々土地はこれ以上ないかもしれないけど、何かそういう考え方、品川ならいいんだよという考え方が表へ出てしまうような気もするんだけど、そこら辺、隣の大田区の話はどこまで答えられるかわからないんですけど、状況を知っている範囲で教えていただければと思います。","respondent":"秋山資源循環推進課長","answer":"大田区の都計審については、私どももちょっと情報のほうは持ち合わせていないので何ともここでご答弁は差し上げられないんですけれども、今回の趣旨につきましては、リサイクルを事業の自己処理責任の中で進めていくもので区としても。","voiceIndex":92,"id":"exchange-032"},{"speaker":"鈴木（真）委員","kind":"意見","question":"ここの処理施設の処理能力が１３ｔできると書いてある。７ｔぐらいになったとしたって、今、区は現在の処理方法をまず対応している部分で、その部分をやるには１３ｔも要請するというのは何でこんなに。１００％これやったって品川分が余ってしまう状況になると思うんだけれども、それは残る判断で１３ｔにしたのか。品川が要請したんで、そうした中で１３ｔまでもっていっちゃったのか。","respondent":"秋山資源循環推進課長","answer":"現在、こちらの表の搬入量というところで７ｔというのは、これは予想の検討というところの７ｔと数字を出していますので、処理能力については余裕を見て、ＪＲのほうでこういう数字を出してきているというふうに考えておりまして、特にほかの自治体ということでは。","voiceIndex":94,"id":"exchange-033"},{"speaker":"鈴木（真）委員","kind":"意見","question":"今、対応している区内の業者に、打ち合わせをしてやってもらって処理してもらっているわけですね。その仕事量が減ったものをどう調整するのかという、そういう話し合いがされている部分があったような気がするんですけど、そこら辺と抵触しないのかなというのが。僕の言っている意味は理解できないように思うけど、自分も理解できないので。","respondent":"秋山資源循環推進課長","answer":"ちょっとこれ、雇上業者の話ではないかと思うんですけど、その辺の業務についてはまだ検討は続けている状況ですので、まだ決着はついていない。決着がついていないというか、代替要因として資源化の部分については、まだ決着がついていないという状況だです。","voiceIndex":96,"id":"exchange-034"},{"speaker":"鈴木（真）委員","kind":"質問","question":"多分、東品川中継所がなくなると仕事量がなくなるので、その補てんというか、いろいろな別の仕事量に回っていくという中にあったような気がしていたので、そういうのは区長会か何かで決めた部分がありますよね。最終的に一般廃棄物でＪＲだけの分でおさまるのか。一般的な、例えば各区のごみが品川のここの施設に来ることが予想されるのか。そこら辺だけ再度お聞きします。","respondent":"秋山資源循環推進課長","answer":"ＪＲの事業活動に伴うもののリサイクル施設ということですので、ＪＲ以外のものが入ってくるということはないというふうに思います。","voiceIndex":98,"id":"exchange-035"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"一体この混在ごみには何が含まれているのかという一般廃棄物、産業廃棄物と分類はちょっと横に置いておいて、一体何がここに含まれるのかというところと、あとなぜここの施設で品川の家庭系の汚れていない廃プラもここで処理するのかというのがちょっと疑問なんですが、ここまでの話に至った経過というのをちょっと教えていただきたいんですね。","respondent":"秋山資源循環推進課長","answer":"廃プラスチックの処理をなぜですけれども、先ほどお話をしましたように、廃プラスチックの処理量、排出量が今後増加が見込まれるということで、現在の処理施設での処理が上限を超えてしまった場合に、今後処理をどうするかということの中で。","voiceIndex":102,"id":"exchange-036"},{"speaker":"飯沼副委員長","kind":"質問","question":"そういった面で、この健康被害が出ないようにしてほしいというのが切なる願いであって、そのための担保というか。廃プラが増加をしていくという対策だというご説明ですが、現在、今どういうふうになっているのかというところをもうちょっと具体的にもう１回教えてほしい。それがどういうふうに変わっていくのかというところを教えてください。","respondent":"秋山資源循環推進課長","answer":"廃プラの現在の状況ですけれども、今、４月の頭で約０.６ｔぐらいが出ておりまして、それを民間の処理施設のほうに持っていきまして中間処理をしているというのが状況ですので、３月までにつきましては前の委員会でご報告したとおり。","voiceIndex":104,"id":"exchange-037"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"民間の中間処理施設って、場所はどこなんだかちょっと教えていただきたいのと、Ａ棟のところの混在ごみなんですけれども、手作業で分けてコンテナに移す。ここの段階で圧縮とかそういうことはないのでしょうか。ちょっとそこの点と。ちょっとその辺を。","respondent":"秋山資源循環推進課長","answer":"コンテナに入れる際ですね。それから、現在の家庭系の容器包装プラスチックですけれども、これは資源化センターでも行っておりましたように、圧縮をして、ベールという形の１ｍ四方ぐらいのものにまとめて、巻きまして形にして圧縮をしているです。","voiceIndex":106,"id":"exchange-038"},{"speaker":"飯沼副委員長","kind":"質問","question":"圧縮に関しては、今まで、どこにもそういうことが起こっていないという理解でいいのでしょうか。火力発電所はあるし、清掃工場はあるし、東京湾岸にいろいろな処理場があって、これ以上本当に環境汚染はたまらないという声もあるわけですけれども、その辺についての歯どめというのはどうお考えなんでしょうか。ちょっとその辺をもうちょっと詳しくお聞きしたいんですけれども、いかがでしょうか。","respondent":"秋山資源循環推進課長","answer":"処理量の歯どめですけれども、こちらの施設は東京都の一般廃棄物処理施設の許可がありますので、当然東京都の立ち入り検査等がありますので、処理場の能力について単純に増やすというようなこともございませんし、建築基準法第５１条のただし書の許可基準として。","voiceIndex":108,"id":"exchange-039"},{"speaker":"飯沼副委員長","kind":"質問","question":"この資料１によると、搬出の台数、これは日量ですよね。かなりの台数が出入りをするわけですけれども、この辺のルートの検討とか交通量の検討とか、車の出入りの排ガスや何かによっても、この辺の地域の大気汚染はまた進むのではないかなと思うんですけれども、その辺の調査というのはどの程度行われているんでしょうか。","respondent":"秋山資源循環推進課長","answer":"車の搬出入の台数ですけれども、こちらにつきましても経路については今のところ、湾岸道路から大井埠頭のほうを回ってこの当該の計画地のほうに入るというのがほとんどだということで、資料３の写真のほうを見ていただくと。","voiceIndex":110,"id":"exchange-040"},{"speaker":"飯沼副委員長","kind":"質問","question":"車のこともアセスの中には入っているんですか。入っているということですか。日に８０台ぐらいでしたか、どの車が同じ道を通るかどうかはわからないんですけれども、日に６８台の車が通るわけで、その辺、アセスにかかわるってどういうふうにかかわるんですか、車の排気ガス。問題ないんですと一言で片づけても、よくわからないんですけれども。","respondent":"秋山資源循環推進課長","answer":"車の影響ですけれども、一般的には搬入の時間をずらすなり何なりして、１時間当たりの車の連なりを防ぐことによって影響を少なくするという形の対策をとるというふうに聞いております。","voiceIndex":112,"id":"exchange-041"},{"speaker":"飯沼副委員長","kind":"質問","question":"車がどこをどう通るのかよくわからなくて、家庭系の廃プラスチックは品川区内あちこちから来ますよね。ＪＲ関係のは、じゃあ外は通らなくて中だけで完結するということなんですか。だから、そういった面でどういう動きをしてここに最終的に来るのかなというのは、区民の関心事であると思うんですけれども、何かここに書いてあるだけで済まされない問題であると思うんですけれども、いかがですか。","respondent":"秋山資源循環推進課長","answer":"車のルートですけれども、湾岸道路から東側の大井埠頭のほうに出まして、東京電力の発電所の先から大井埠頭のほうに入りまして、そのまま南下をして現在の施設のほうに入るということを考えております。","voiceIndex":114,"id":"exchange-042"},{"speaker":"飯沼副委員長","kind":"質問","question":"横の道路から大田区なんですが、そういった面で先ほども大田市場がすぐそばにあるということで、いろいろな意味で環境が悪化したらよくないんじゃないかなと心配もしているんですが、大田区とは全く折衝がなくて進むのかどうかという点と、多分説明会云々は紛争予防条例のところの説明だけであると思うんですけれども、こういった今回のような全区的に影響を及ぼすようなところにおいては。","respondent":"秋山資源循環推進課長","answer":"ＪＲ側には、それ以外についての窓口を設けて、何か相談があった場合には対応するということを指導してまいりたいというふうに考えております。","voiceIndex":116,"id":"exchange-043"},{"speaker":"飯沼副委員長","kind":"質問","question":"ＪＲの説明はわかったんですが、こういう施設を受け入れる品川区としての説明責任というのはあるのでしょうか。ないのでしょうか。","respondent":"秋山資源循環推進課長","answer":"今回の施設につきましては、一般廃棄物の処理施設ということで第５１条のただし書というのを使って許可をするですので、その手続きにのっとって行っていくですし、また、今回、第５１条ただし書の中でＪＲに対して説明をさせるというようなことも盛り込んでおりますので。","voiceIndex":118,"id":"exchange-044"},{"speaker":"鈴木（真）委員","kind":"確認","question":"確認だけ１点。この資源循環センターの計画に関しては、最初、株式会社東日本環境アクセスから品川区に来た時点では、Ｃ棟、家庭系廃プラスチックの部分は当初時点では話があったんですか。なかったんですか。最初からＡ棟、Ｂ棟、Ｃ棟、家庭系廃プラスチックの施設まで話があったのかどうか。あったのかなかったのかということをお聞きします。","respondent":"秋山資源循環推進課長","answer":"結論から言いますとなかったです。","voiceIndex":120,"id":"exchange-045"},{"speaker":"山路委員","kind":"質問","question":"この件は将来にＪＲの線路をつくって、東八潮駅というのが設置されるということをどこかで聞いたことがあるんですが、ここの道路の上ぐらいですか。","respondent":"秋山資源循環推進課長","answer":"その計画については私のほうで全く聞いておりません。","voiceIndex":122,"id":"exchange-046"},{"speaker":"鈴木（真）委員","kind":"質問","question":"区長会で公平化のために大変ご苦労なさった結果がこれで出て、これはよかったなと思うんですけれども、２番の中で清掃工場のごみ処理量の平準化に向けて搬入調整をするというのは、まだ清掃工場をつくっている最中のがあるんでしたっけ。これから平準化というのはどういうことを考えての平準化なのかというのが１点。その辺が答えられるのなら、その３つを教えてください。","respondent":"秋山資源循環推進課長","answer":"もっと少なくなるかというようなことは今のところちょっと予想はつかないという部分ですので、１,７００万円、負担をしているが、現時点としてはこういう平成１８年度の実績で見れば品川区としては若干の負担をしているという結果というふうに理解しております。","voiceIndex":128,"id":"exchange-047"},{"speaker":"鈴木（真）委員","kind":"意見","question":"一番最初のプラント更新とか工場というのは、もう今ないなと思ったので、搬入調整によって平準化が図られている。１,７００万円というのは、品川はもっともらいたかったんじゃないかという意味の、もっともらえる分があると判断していたのか、それとももっと少ないと判断していたのかという意味で、そういう算出するうえで、どっちだったのという、そういう意味を聞きたかったんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":130,"id":"exchange-048"},{"speaker":"飯沼副委員長","kind":"質問","question":"先ほどのご説明で、他区も一定受け入れて、超えて焼却を受け入れたところがプラスになっていると思うんですけれども、品川区が実際どこから受け入れているのかというのがわかるのかどうかと。能力的に、焼却炉の能力として全体的なところでゆとりがあるのかどうか。品川区の清掃工場がその辺、ゆとりがあるのかどうなのかという点を教えてもらえれば。","respondent":"秋山資源循環推進課長","answer":"品川工場でどこから受け入れるかですけれども、いろいろな工場のオーバーホール等が随時予定されておりますので、近くの港工場がオーバーホールしている場合にはその分を受け入れるとか。","voiceIndex":131,"id":"exchange-049"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"決して私はどんどん燃やしてほしいと思っているわけではなくて、ごみ減量の立場からすると、やはりごみを減らしていくという方向で、だからむやみに受け入れているとは言いませんけれども、やはりごみを燃やしていく量を減らしていく方向で全体的にも、２３区のところでもそうですけれども、取り組んでいただきたいという思いでの質問なんで、その点をお願いします。","respondent":"秋山資源循環推進課長","answer":"もちろんごみ減量への努力というのはまず最初にあるわけでありまして、それをごみ減量の努力をしていくと、この負担アンバランスというのも解消していくというのが前提ですので、ごみ全体の量が減れば、焼却炉のアンバランスというのが解消できるだろうという中で、ただ。","voiceIndex":133,"id":"exchange-050"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ことに２番の「わが家の防災ハンドブック」、区民の方は配布されてわかりやすいということを聞いています。ですから、ぜひうまく活用していただいて、これからの地域ごとに避難訓練等がありますね。そういうときにうまくその辺の話をしていただければ、せっかくいいものができたのでぜひ活用していただきたいなと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":139,"id":"exchange-051"},{"speaker":"飯沼副委員長","kind":"質問","question":"私も今のところなんですが、全戸配布ありがとうあります。新しく転入された方にどういうふうにして渡るのかというのが１点と。１のほうの分厚いのなんですけれども、まだ中身を読ませていただいておりませんけれども、今回の中身の改訂に結構、事業所関係が含まれていますよね。帰宅困難者の問題とかいろいろかかわってくると思うので、その辺どう考えていらっしゃるのか、ちょっとお聞きしたい。","respondent":"中山防災課長","answer":"事業所との三者懇談会で帰宅困難者の歩行帰宅訓練等ももう既に日程が決まってありますけれども、５月１４日と２１日に実施をしていくところです。そういった中で、改訂されました地域防災計画等については、順次ご説明等もしてまいりたいと考えています。","voiceIndex":140,"id":"exchange-052"},{"speaker":"飯沼副委員長","kind":"意見","question":"地域センターに置いてあるというのは、行って意識的な人にしか渡らないということですよね。転入者なんですけれども、転入者の中でも届を出したときに、はいと渡されるわけではないということですよね。","respondent":"中山防災課長","answer":"希望者のみに渡すということです。","voiceIndex":142,"id":"exchange-053"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"わかりました。できるだけ多くの方に渡していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":144,"id":"exchange-054"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2512#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":45728,"voices":148}},{"id":"h20-20080415-7","meetingId":"h20-cm04","date":"2008年4月15日","dateIso":"2008-04-15","committee":"厚生委員会","time":"午後１時０３分～午後 ４時２４分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を43件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今、説明をしていただいたのでちょっとわからないところがあったので、教えていただきたいんですが、品川区の独自の取組みということで、ホームレス等の訪問相談事業ということで、民間に夜とか土日にしていただいているということなんですけれども、これはどれぐらいの期間でどういうところがどんな形でやっているのかということを、もうちょっと詳しく教えていただきたいのと。","respondent":"志村生活福祉課長","answer":"ですので、この辺につきましては、なるべく早くに対応がとれるようにということで、私どもでも当然のことながら、職員がまず行きますけれども、それでできないときには、まず一番には、２３区共同でやっております巡回相談センターに頼みますけれども。","voiceIndex":22,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その目視というのは、夜にやっているのかどうかというのを１つ教えていただきたいのと、それから、私もこの２３区でこういう取組みが行われて、それが効果を生んで減ってきているというのは確かにあるんだと思いますし、私たちが相談を受けたときも、そういう施策があって、そこにつなげられるというところでは、本当によかったと思っているわけなんですけれども、そうはいっても、今回。","respondent":"志村生活福祉課長","answer":"次のご質問のいわゆる健康管理といいますか、寒いなどのときの対策ですけれども、実はこの緊急一時保護事業の中に、年末年始とか、それから、ゴールデンウィークのときには特別の体制をとってございまして、そのときには別枠で入所ができるような対応をとってあります。","voiceIndex":24,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それともう１つは、このホームレスの問題では、私も改めてインターネットでいろいろと調べてみましたら、東京都でもすごく詳しく実態調査をしたりとか、それに対しての分析というのがたくさん載っていたので、改めて見させていただいて、すごく詳しく出されていたんですけれども、その中でも緊急一時保護センターについて知らないという方が２４％あって、知っているけれども利用しない。","respondent":"志村生活福祉課長","answer":"ですので、やはり実際にお会いして、個別にどのようなことで自立をしていくべきなのか、いったほうがいいのか、あるいはどのようなことがあるのかということで、当然のことながら、その中に生活保護も入ってまいりますけれども、ご本人のそういった自立といいますか。","voiceIndex":26,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"医療へのアクセスのサポートもできる。そういう相談センターの機能を持つという、そこに行けば相談ができて助かるという、そういうところが必要なのではないかというところが提案もされていたんですけれども、本当にそうなのではないかなと思うんですけれども、そこのところはどうかということと、２つお聞かせいただきたいと思います。","respondent":"志村生活福祉課長","answer":"１点目のパンフレットの件ですけれども、これは事業を委託をしているときに、事業のこういうことを説明してくださいというのを相談する方にはお示ししております。もう１つお渡ししているので、品川区福祉事務所までの地図といいますか、この区役所の３階にありますよと。","voiceIndex":28,"id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"センターでそこの相談機能を持つというのは、もちろん私も福祉事務所を通してそこに行くということはわかっているわけですけれども、もっと気軽に相談できる、敷居を低くするというところがつながっていくところになるのではないかと思いますので、そこのところもぜひご検討いただきたいということで、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-005"},{"speaker":"山元委員","kind":"質問","question":"４番目のところの自立支援センターの設置なんですけれども、２月２７日に大井第一町会連合会会長に説明をしたと書いてあるんですけれども、これは会長お１人にご説明なさったんでしょうか。","respondent":"志村生活福祉課長","answer":"ここに書いてあります２月２７日、大井第一町会連合会会長にご説明をいたしまして、そのときに依頼を受けまして、地元の勝島町会長にもご説明しておいてくださいということで、その日の夕方に出かけてまいりました。","voiceIndex":31,"id":"exchange-006"},{"speaker":"山元委員","kind":"質問","question":"その反応というか、地元からの何かお話というか、具体的に住民の方からの何かお話というのは出たんでしょうか。その後からでも何かそういうお話が出てきたんでしょうか。","respondent":"志村生活福祉課長","answer":"ただし、施設がどれくらいのものが建ってどういうふうになるのか、これから図面を引いていきますので、そのときにまたいろいろご相談をしていこうと、かように今、考えているところです。","voiceIndex":33,"id":"exchange-007"},{"speaker":"堺委員","kind":"質問・要望","question":"何点か確認させていただきたいんですが、4)の巡回相談センター事業の中で、本区の実績、これは毎月月初めに５日間、延べ６０日間で、稼働内容が全部で２１８件、３月末現在と、こうありますけれども、これは平成１９年度１年間の稼働内容というとらえ方でいいんでしょうか、それが１点です。それから、声かけと相談とどう違うのか。とりあえずそこまでちょっと教えていただけますか。","respondent":"志村生活福祉課長","answer":"ですので、何回かお話をして、何十回と同じような話を繰り返しながら、実はこういう制度があって、こういうふうにやって、こうなって自立していくのがあるんですよということを何回もやれないと、その次の同行して緊急一時保護センターに行くというのは大変難しいと考えています。","voiceIndex":35,"id":"exchange-008"},{"speaker":"堺委員","kind":"質問","question":"ここで言う平成２０年３月末の２７人、これは今年に入ってからの数ですか。今、課長のお話を伺うと、大変失礼かもしれませんが、こういう方々を自立させるためには、相当なご苦労があるんだなと。さっき申し上げた２７人というのは、これは今年３カ月間の人数なのかどうか、これだけちょっと教えていただけますか。","respondent":"志村生活福祉課長","answer":"この２７人というのは、平成１９年度の実績です。２７人の方に何回かアプローチをかけましたと、こういう数字です。","voiceIndex":37,"id":"exchange-009"},{"speaker":"須藤委員","kind":"質問・要望","question":"路上生活者対策、いろいろ行政側でやって、担当の生活福祉課、それから、まちづくり事業部のほうにも管理ということでお願いをして、今、こういった数字も出されていましたので、本当に一生懸命対処していただいていることに感謝申し上げます。今日はいろいろあるので、そろそろ結論を出していただきたいという意味で手を挙げました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-010"},{"speaker":"須藤委員","kind":"意見","question":"ただ内容的にストレートにというよりは、説明いただいたように、東京都全体で考えて、品川区独自で云々というのは、失礼な言い方だけど、うちの施設だけということではなくて、ほかのところへ移動していってしまったり、うちの近くでも公園のところに寝出してしまったというのがあって、ここはだめだよというお話をしたら、どこか隣のほうで寝ていたということがあったので、そういう仕組みを。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":41,"id":"exchange-011"},{"speaker":"堺委員","kind":"質問","question":"本日、結論を出すということで、今、須藤委員からもお話がありましたので、こちらのほうからもあわせて意見を申し上げたいんですが、須藤委員からもお話がございましたように、今日いただいた書面にも、この件について、当該施設の工事は東京都が行い、経費については都区で折半し、区費については２３区均等負担するということで、この陳情者が書かれておられるような。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"私も今日結論を出すということでお願いしたいと思います。このホームレスの問題は、報告にあったように、人数は減っているということなんですけれども、東京都の分析でも、年齢は高くなって路上生活期間が長期化しているということも書かれていました。ということで、趣旨採択ということでお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":43,"id":"exchange-013"},{"speaker":"本間委員","kind":"質問・要望","question":"引き続きこれからも取組みを進めていただきたいというのと、この中には施設建設ということがございましたが、この施設建設につきましては、既に仮称自立支援センター品川寮設置準備等々のお話も先ほど来、お聞きしておりますので、ここ１年ぐらいの間に、その種の問題もクリアしていくのではないかという報告を受けておりますので、この陳情者の意見をくみながら、趣旨採択という形でと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-014"},{"speaker":"高橋委員","kind":"質問・要望","question":"今日結論を出すということでお願いしたいと思います。２３区全体で行っていくことが大事だと思いますので、今までの政策をこのまま続けていっていただきたいということと、その政策の中で命を尊重していくという見地で行われていると思いますので、今回のこの陳情の中にもありますけれども、その命をというところに沿って、今、行われていますので、趣旨として採択したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-015"},{"speaker":"須藤委員","kind":"質問","question":"やはり駐車、交通安全という考え方から、いろいろとこういう整備をされてきたと思うんだけれども、そのあたりが数としてどういうふうに変化するのかという思いがあるので、おわかりになったら教えてください。","respondent":"高橋障害者福祉課長","answer":"一応大阪府と兵庫県の状況を調べましたら、従前の改正前の、下肢機能障害については１級から４級が対象になっているという状況です。","voiceIndex":53,"id":"exchange-016"},{"speaker":"須藤委員","kind":"質問","question":"このことについて行政側からは何か警察のほうへアクションを起こしたとか、そういうことは全然、そういう通達があったよというだけで終わっているわけですか。初めて今、議会にこういうのが上がってきたんだけれども、そのあたりはいかがですか。","respondent":"高橋障害者福祉課長","answer":"東京都のほうとか国の段階でも、各障害者団体については団体のほうに連絡をして、そこからご意見をちょうだいしているとのことですが、今のところ、具体的な、改正の変更を求めるという内容はないと聞いております。","voiceIndex":55,"id":"exchange-017"},{"speaker":"須藤委員","kind":"質問","question":"区内の７団体とお話をして、そこでは、やはり区内でも、この問題についておかしいよとかという話は特になかったわけですか。","respondent":"高橋障害者福祉課長","answer":"説明した段階では、一応わかりましたという内容で、特に変更ということのご意見はちょうだいしておりません。","voiceIndex":57,"id":"exchange-018"},{"speaker":"宮崎副委員長","kind":"質問","question":"ちょっと何点か伺いたいんですけれども、まず、今のところで障害者７団体懇談会で説明されたということなんですけれども、７団体には下肢の欠損といいますか、こういう状態の方々の団体も入っておられるんでしょうか。","respondent":"高橋障害者福祉課長","answer":"身体障害者友和会というのがその団体の中に入っております。","voiceIndex":59,"id":"exchange-019"},{"speaker":"宮崎副委員長","kind":"質問","question":"私はちょっとお話を伺ってきたんですけれども、建築の設計の仕事をされている方で、車で移動というのが非常に多くて、こういう方は駐車禁止の除外の指定がなくなると、非常に仕事のほうも差し支えてしまうという話だったんですけれども、今のお話ですと、どうもそういう状況が伝わっているのかなというのが、正直言って感じるんですけれども、区のほうはその７団体の懇談会で意見がなければ。","respondent":"高橋障害者福祉課長","answer":"これは全国で警察庁が通知を出したものに対して、各都道府県がアクションを起こすという内容で、どこの都道府県に行っても交通ルールが同じような状況になった方が、交通の安全上、いいのではないかという判断で通知を出したものだと考えております。","voiceIndex":61,"id":"exchange-020"},{"speaker":"宮崎副委員長","kind":"質問","question":"先ほど、３級の方が４３０人で、そのうち３級の１から３級の３は不明ということなんですけれども、公安委員会のほうでは、実際にこの除外指定車証の発行枚数というのはつかんでおられるんでしょうか。４３０人が全部受けているものではないと思うんですけれども、区内では何人の方が駐車禁止等除外標章を受けているんでしょうか。","respondent":"高橋障害者福祉課長","answer":"あくまでも警察署にご本人が必要であるかということで、障害者手帳とともにいろいろな書類を添えて申請するものなので、私どもでは何人が受けているものかというのは承知しておりません。","voiceIndex":63,"id":"exchange-021"},{"speaker":"宮崎副委員長","kind":"質問","question":"これから歩行困難者のカードに切り替わるということなんですけれども、そういう配慮をしてもらわないと、仕事にも差し支えるんだとおっしゃっているんですけれども、区のほうは、今の課長のお話ですと、あれは警察のほうなんだという感じで、非常に縦割りという感じもするんですけれども、もうちょっと状況を把握したらどうかなと思うんですけれども、そこら辺のところはどうなんでしょうか。","respondent":"高橋障害者福祉課長","answer":"状況ですが、基本的には長時間、本人が乗っていない場合については、先ほども申し上げた運転者の連絡先等要件、標章を見やすい場所にということで、具体的に放置自動車によっての違法駐車をなくして、交通の流れをよくするというところの立場もありますので。","voiceIndex":65,"id":"exchange-022"},{"speaker":"宮崎副委員長","kind":"質問","question":"障害者福祉課長なので、交通渋滞の解消とか、そういう角度もあるんだけれども、これは障害者の方の社会参加ということですから、そのための手段なので、交通渋滞の解消は解消だと。こっちのほうばかり強調されると、社会参加のほうは否定されていくように私は思えてしようがないんですよ。その困るのを実際に区としてつかんでいらっしゃるんですかということを聞いているんです。","respondent":"木下福祉高齢事業部長","answer":"そういう点で、ご指摘の今回の陳情の部分については、もう少し議論をすべき性格を内包していると感じているところです。","voiceIndex":67,"id":"exchange-023"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"今の部長の説明で行政側の考え方はわかったんですけれども、そうであれば、先ほどのホームレスのところでも質問がありましたけれども、福祉関係の部長会とか、そういうのもあるのであれば、ぜひそういうところも話題にしていただいて、東京全体でもどうなのかという議論をぜひそういうところでやっていただきたいと思うんです。そこのところはぜひお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-024"},{"speaker":"須藤委員","kind":"質問","question":"というふうに私自身思っているんだけれども、そのあたりはいかがですかと理事者に聞きたいのは、ただ下肢不自由者のところだけで判断すべきものかどうかということと、また仕事で車を使うという人というのは、高齢者でも使って、停めておけたら一番楽だよというのが一般の人なので、それが停められなくなったという人たちから見たらどうだろうというものもあると思うので、そのあたりはいかがでしょうか。","respondent":"木下福祉高齢事業部長","answer":"通常は介護者が運転して、駐車禁止除外指定をもらうわけであります。というように、今回の考え方の整理には、介護者が同乗しているということを１つ念頭に置いているようであります。","voiceIndex":70,"id":"exchange-025"},{"speaker":"堺委員","kind":"質問・要望","question":"さっきから見ていると、一律にここで見直しをして、今申し上げたようなそういう人たちがそこから締め出されるということになってしまいますと、やはり障害者の社会参加を規制するということになりかねませんので、これは平成２２年７月３１日からそういうふうになるということなので、あと若干の猶予期間がありますから、その間で、もう少しそういう方々にも配慮した形での見直しができるように。","respondent":"高橋障害者福祉課長","answer":"部長が申し上げたとおり、交通ルールと障害者の社会参加のバランスの問題につきましては大きな問題ですので、課長会も含めまして、その辺について意見を述べていきたいと考えております。","voiceIndex":72,"id":"exchange-026"},{"speaker":"須藤委員","kind":"意見","question":"陳情というとまた答えをもらってこなければ云々という話になるので、だからこの扱いは内容的にはよくわかるんだけれども、その辺は今、堺委員からお願いをしたように、行政側にはみんなで努力してもらうことになるけれども、議会としてのありようというのは、その辺は、委員長、どういうふうにこれは、陳情というのは今まで議会としてやったことがあるのか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":74,"id":"exchange-027"},{"speaker":"須藤委員","kind":"意見","question":"意見書なら意見書でね。そういうことでなら持っていけると思うんだけれども、そのあたりを委員の皆さんから、決をとる前にその整理をしていけるかどうか、委員長、ご配慮をお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":76,"id":"exchange-028"},{"speaker":"須藤委員","kind":"質問","question":"その辺を整理しないと、最後にしますといったって、このままでは議会として、今まで難しいよという、今度議会運営委員会にかけてどうだとか、またいろいろな手順を踏まなければいけないので、私は厚生委員会の委員の皆さんが、そういう方向でいいのではないでしょうかという大方のご意見ならば、今、ここで結論を出しましょう、次のステップへ行けるなと思っているので、このとおりやれというなら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-029"},{"speaker":"須藤委員","kind":"質問","question":"ですから、そこは僕らは議長から来たことを厚生委員会として真剣に議論していく話であって、その出方がどうだこうだというのは、議長の裁量権にまで入っていってしまうので、そこは我々が云々する話ではないので、もし議長から委員長に相談があったら、それは委員長としてきちんと相談していくべきで、この中で皆さんどうですかといったって、議長から来たのが付託となっているのに、それを僕らがここで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":80,"id":"exchange-030"},{"speaker":"堺委員","kind":"確認","question":"私はですね、この件については、委員長がおっしゃっておられましたように、この方が文章的には最後に、品川区議会から警視庁へ陳情していただきたくということですから、ただ、今まで議会として、あるいは委員会として、それぞれこういう請願とか陳情を出していただいた中で、しかるべきところへ陳情してくださいという趣旨のものはなかったように思うんですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-031"},{"speaker":"宮崎副委員長","kind":"意見","question":"あくまでも議長のほうから厚生委員会に付託ということでありますので、ここはそれまでの議長の判断のところまで云々というのは、ちょっとまた問題が違うかなと思いますので、まずそういうことが１つと、あとは陳情と書いてありますけれども、私はこの方は議会の仕組みだとかというのがよくわからないでこう表現されたのではないかと思うので、それは私も意見書を議会として出していくということができれば。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":86,"id":"exchange-032"},{"speaker":"本間委員","kind":"意見","question":"この陳情をどのようにして今日結論を出すか、それが先だと思います。それから、次に、どのような部分かについて、過去の経験に照らし合わせて、本人の意見を尊重しながらどうやっていくのかというのを、この場面である程度知恵を出していいのではないかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":87,"id":"exchange-033"},{"speaker":"高橋委員","kind":"意見","question":"この陳情をどう扱うかということに関しては、委員長と副委員長に流れをお任せするとして、ただ私がわからないのは、陳情と書いてあるのを意見書として判断をしていいのかどうか、私はあれですけれども、それだけなんですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":88,"id":"exchange-034"},{"speaker":"須藤委員","kind":"意見","question":"委員長がそういう陳情という言葉を大事にしなければと言われてしまうと、委員会としては、私がさっき言ったように、この陳情者の考え方で東京都側に議会として意見を持っていけばいいのではないかと思ったんだけれども、その言葉を大切にしなければというと、このままストレートで陳情するというのはなかなか難しいですよという話になってこようかと思うので、そこまでいくんだったら。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":91,"id":"exchange-035"},{"speaker":"堺委員","kind":"質問","question":"これは経済的負担の軽減という視点と、それからもう１つ、この陳情者がおっしゃっていることは、障害者の社会参加という視点からという意味合いからいきますと、やはり早く結論を出してあげたほうがいいということと、それからもう１つは、要するに我々もう間もなく任期切れというんですか、もう一回あるようですけれども、継続という考え方もあるかもしれませんが、やはり今、申し上げたように。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":92,"id":"exchange-036"},{"speaker":"宮崎副委員長","kind":"質問","question":"ですから、私はそういう意味ではこの方にとっても非常にこれからの生活、仕事ができるかどうかという瀬戸際に立たされているなと、非常にそういう感じも受けましたので、できたら皆さんにもこれを、厚生委員会としては、陳情者は陳情と言っているけれども、陳情はできないけれども、意見書でやろうということにしたらどうかなと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":93,"id":"exchange-037"},{"speaker":"本間委員","kind":"質問・要望","question":"今日結論を出すようにしていただきたいと思います。それと、今までのお話をいろいろお聞きしまして、私どもの周辺では、この件についてのご意見という部分についての把握はしてはいませんが、十分趣旨を理解しております。そのような動き、流れにつきまして、平成２２年７月３１日からの部分ですから、それまでの期間、またいろいろな新しい動きが出てくるかもわかりません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":94,"id":"exchange-038"},{"speaker":"高橋委員","kind":"意見","question":"この陳情された方の趣旨は理解できるということはあるんですが、先ほど部長からもお話がありましたが、いろいろとまだまだ議論したり、詳しく知る必要もあるということなので、趣旨は理解して認めたいというのはあるんですが、委員の皆さんの意見にもよると思うんですが、継続していく方法もあるのかなということで、ちょっと趣旨を理解するというほうが強いです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":95,"id":"exchange-039"}]},{"id":"topic-02","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私はこういうまちづくり推進計画ができて、本当にこれが具体化していったらいいなと思っていますけれども、このパブリックコメントが１１人からということなんですけれども、その中でも私はこのパブリックコメントのところに意見を出された方からお聞きしたところ、すごい細かいところがたくさん意見があって、そういう障害者の方々の意見をぜひこの中に具体的に取り入れていってほしい。","respondent":"冨岡高齢福祉課長","answer":"これは今後、推進計画ですので、１０年の期間の中でやさしいまちづくりを推進していくといった中で、例えばまち歩きとか、そういうものを含めて、今後も障害者の方のご意見をまだいただける期間があるのかなと。","voiceIndex":106,"id":"exchange-040"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だから、そういうところでは、障害者の方々が実際により使いやすいまちづくりというところでは、障害者の方々の意見がもっと反映させられるような、仕組みそのものをぜひご検討いただきたいということで、時間もないので、この程度で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-041"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"保育園の入園状況なんですけれども、申込の申請の方は１,５００名を超えているということなんですけれども、１３％増ということで、申し込まれて認可保育園に入れなかった方の数というのも教えていただきたいのと、それからあと、平塚中学校のところの小中一貫校で、認可保育園がだめになってしまいましたけれども、今回、本当に認可保育園の増設というのがすごく待たれていますけれども。","respondent":"永尾高齢事業課長、小林保育課長","answer":"説明会の参加の人数ですけれども、２１５人です。平塚の幼保一体施設の取り扱いについてですけれども、地域の需要に応じまして、今後対応してまいりたいと考えておりますが、現段階で具体的にこういうふうな施設展開をするというのは決定しておりません。","voiceIndex":114,"id":"exchange-042"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"保育園では私も入れなかったんだけど、という相談を次々受けたんですけれども、０歳で、フルタイムで働き続けてきた方が産休中で入れないとか、本当に厳しい、こんな方まで入れなかったのかという状況があると思うんですけれども、改めて認可保育園の平塚中学校の跡のだめになったところの計画は、１日も早くしていただきたいということをお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":117,"id":"exchange-043"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3200#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":38665,"voices":119}},{"id":"h20-20080415-8","meetingId":"h20-cm04","date":"2008年4月15日","dateIso":"2008-04-15","committee":"建設委員会","time":"午後１時０２分～午後５時２５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を74件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の平成２０年度水防演習の実施","agenda":"の平成２０年度水防演習の実施","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"日頃から水防演習の真剣な姿を拝見していますけれども、演習想定ですけれども、どのように設定されているのか伺いたいと思います。近年の被害状況とか品川区の水防の弱点とか、そのようなものに基づいて行って充実していただきたいと思っているんですけれども、演習想定や演習内容をどのように想定しているのか説明していただきたいと思います。","respondent":"家壽田下水道河川課長","answer":"例年と同じですけれども、台風の接近に伴いまして、早朝に水防一時警戒態勢が発令されたということを想定しておりまして、被害が出たところに対して応急措置を、先ほど説明しました項目について実施するものです。","voiceIndex":19,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"最近の傾向とか原因に基づいて、水防演習に結びつけて充実させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-002"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これをやることは非常にいいことなんだけれども、議員紹介はそろそろやめたら、考えてみたらどうかと思います。それから、ぞろぞろ歩く歩き方も少し考えて、やっている途中でもずれるわけですし、非常に危険度があるわけではないので、全部整備されてからぞろぞろ歩くということがいいことなのかどうか。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-003"}]},{"id":"topic-02","title":"の羽田空港跡地利用基本計画","agenda":"の羽田空港跡地利用基本計画","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"羽田空港跡地利用基本計画を歓迎する形になるのかと思うんですけれども、この計画の品川区の影響といいますか、まちづくりの影響をどのように考えているのか、その考え方を聞かせていただきたいと思います。この計画によっての品川区の影響というか、変化というか、今、考えていることがありましたらお聞きしたいと思います。","respondent":"梶都市計画課長","answer":"具体的な手法につきましては、今後詰めていくわけですけれども、ただ三者協につきましては今後も継続していくという話ですので、こちらのほうで品川区に関連する話題等が出てまいりましたら、まちの方の意向に沿うような形で進めていきたいと思います。","voiceIndex":28,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問","question":"例えば、空港を活かす、空港と連携する、周辺と調和するという、三つの基本的な視点がありますけれども、品川区の産業といいますか、街並みというか、住環境というか、それとの関係で品川区が思い描いているものがあるのかと思って伺いましたので、もう少しご説明をいただけたらと思います。","respondent":"梶都市計画課長、岩田まちづくり事業部長","answer":"もっと細かい説明という話ですが、実は羽田空港跡地利用基本計画につきまして、三者協が設置されましたのが昭和５２年です。当時から基本計画につきまして検討していたわけですが、具体的な内容が決まらないうちから入ってきたわけです。我々国民も非常に高いものを買わなければいけないということで、長期的には成田・羽田空港は果たしてこれで足りるのか、あるいは横田基地の問題をどうするのかという、首都圏としての空港をどうしていくかという長期的な展望というのは。","voiceIndex":30,"id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"「神奈川口構想で検討されている連絡道路」ということが書いてありますが、これがどういう形で検討されているのか、まず教えていただきたいと思います。","respondent":"梶都市計画課長","answer":"川崎市が隣接しております神奈川口構想で検討されている連絡道路という形でございまして、こちらは神奈川口構想というのは羽田空港が再拡張されれば、当然川崎方面からのアクセスをどうするのかということが問題になってきますので、神奈川県あるいは横浜市、川崎市のほうで。","voiceIndex":33,"id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問","question":"そうすると、この計画が考えられるということになると、三者協ではない川崎市が直接言っているのは三者協ではなく国に言っているということですね。もしかするとほかも出てくるというような話を聞いたんだけれども、それはうその話なのか、本当の話なのかわからないけれども、その辺のことがわかっていれば教えてください。","respondent":"梶都市計画課長","answer":"話題にも上っていないという話です。ただ、羽田空港の将来的な方向もありますが、今後はそれにプラスして何かあるかどうかということは、それが終わってからになろうかと考えています。","voiceIndex":35,"id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"代表質問でもやったから、あまり触れないですけれども、ぜひこういう離れたところで、こういうことがあっても、自分の土地ではないということではなくて、自分のところと関連して何か手を打てば、逆に品川区にとってプラスになるという面も、お金を投資しても構わなかったのではないかと思っていまして、そういうところをぜひ宣伝していってもらえればと思っています。要望にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-008"},{"speaker":"三上委員","kind":"質問","question":"今の話に絡んでくるんだけれども、私も以前からそういうものについてはもう少し積極的になってほしいという思いがあったんです。やはり昭和５０年代からこのような流れがあるとなれば、騒音問題さえ解決すればいいということではなくて、それなりのものを主張すべきことについて消極的ではないかと思っていたんですけれども、その辺はどうでしょうか。","respondent":"梶都市計画課長","answer":"ちなみに三者協で話題になってあります跡地に関して、これからも存続して具体的に検討を続けてまいりますので、品川区として何かできるのか、何か意見ができるのかということも含めまして、今後検討をさせていただきたいと思います。","voiceIndex":38,"id":"exchange-009"},{"speaker":"三上委員","kind":"意見","question":"要するに、課長クラスでこういうことを考えるということではなくて、これはトップの意識だと思うんです。それには首脳部会議があるのかどうか、そういう言い方をしているかどうかわからないけれども、そのあたりがどのように取り組むかということを明確に考えたもので、その方向性に向かっていこうというものがあってもいいと思うんです。庁舎内でも。","respondent":"岩田まちづくり事業部長","answer":"品川区がこの土地の一部に何かをするというのは、今のところは特に何か考えられることはありませんけれども、協議会の枠を広げた中で、東京都港湾局や知事部局の方とも品川区のトップがお話しするときには、ここではあまり直接的に品川区の利害関係はないけれども。","voiceIndex":40,"id":"exchange-010"},{"speaker":"阿部委員","kind":"意見","question":"あまり言うと債務超過の形になってしまうかもしれませんけれども、それは依然として大きな課題でもあると思いますし、ただこの時期にどうするとかということだけではなくて、新しくなった羽田をどう活かしていくかという、活力を取り込むような策をぜひ考えていくべきだと思うし、それをきちんと考える場もつくっていくべきであるかと思います。","respondent":"岩田まちづくり事業部長","answer":"非常に難しいご指摘ですけれども。話は少し変わりますけれども、例えば東海道新幹線ひかりができて、のぞみを入れて、飛躍的な乗降客数の増がついこの間まで見込まれていました。","voiceIndex":42,"id":"exchange-011"}]},{"id":"topic-03","title":"の滝王子通りの避難道路機能強化","agenda":"の滝王子通りの避難道路機能強化","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"基本的なことを伺いたいと思います。今のご説明にありましたけれども、防災上必要な幅員１０ｍとした理由を詳しく教えていただきたいと思います。それから、最低限高度地区を７ｍと定めていますけれども、先ほど国の条件を満たすというご説明でしたけれども、なぜ７ｍという根拠になるのか、同じように不燃化の幅が３０ｍですけれども、根拠を教えてください。","respondent":"吉川住環境整備担当課長","answer":"その計算で行いますと、１７ｍの幅員が必要だということになりますが、これに対してハード・ソフト対策ということで、先ほどご説明しましたように沿道建物の不燃化促進をするということで、まず火災等の被害を最小限にする。","voiceIndex":48,"id":"exchange-012"},{"speaker":"中塚委員","kind":"質問","question":"高さ７ｍ、幅３０ｍ、国の実験で不燃化率７０％ですと火災延焼が防げるという、その範囲を教えてください。３０ｍの範囲が現状はどのぐらいなのか教えてください。先ほどの説明の中で、私の見方が間違っていたら指摘してください。１７ｍであると避難のところが１m2１人ということだったのか、逆にそれが１０ｍになるとどういう想定になるのか教えてください。","respondent":"吉川住環境整備担当課長","answer":"現状の不燃化率ですけれども、２９％です。それから、１０ｍにした場合でも１m2あたり１人が歩くという前提を変えておりません。","voiceIndex":50,"id":"exchange-013"},{"speaker":"中塚委員","kind":"質問","question":"その被害想定はいつの時点なのか教えてください。それから、セットバックした際に、建物の敷地は狭くなってしまって、技術上は建てられるのかもしれないけれども、生活上、建てられない大きさになってしまう家屋も想定されると思うんですけれども、どのようなものを想定しているのか、対応策も含めて教えていただけますか。","respondent":"吉川住環境整備担当課長","answer":"生活が難しくなる方はどうするのかというご質問ですが、やはり生活再建を最優先に、ご本人と相談しながら支援策を検討してまいりたいと考えております。","voiceIndex":52,"id":"exchange-014"},{"speaker":"中塚委員","kind":"質問","question":"そうすると、この計画の想定自体が変わってくるのではないかと思ったので、そこはどのように整合性を持っているのか伺いたいと思います。滝王子通りはバス通りですから、否応なしにバスが通っていますし、脇に寄せる場所もないですから、そういうようなことはどのように想定しているのか教えていただけますか。","respondent":"吉川住環境整備担当課長、岩田まちづくり事業部長","answer":"もう１点のバスのお話ですけれども、ソフト対策の一つとして、運行するバス会社にも災害時にとめる場合には、可能な限り端に寄せてとまっていただくように話し合いを行っていくことを考えております。これはフソトも完全に動いてという前提です。沿線住民の方たちの土地の買収を最小限にするためにいろいろ検討してきた結果、このように１０ｍまでにしようと。","voiceIndex":54,"id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"例えば、先ほどのバスの話で、可能な限り脇に寄せると言いましても、バスは２.３ｍぐらいですか、脇に寄せたところで、ソフト面の中身を具体的に今の時点で見えないので、心配するわけです。先ほど伺ったのは、一方で市街地大火を起こさないために８年間で耐震化率９割を目指してやるという答弁が繰り返されていますけれども、それが達成すると当然出火とか延焼速度が変わってくると思うんです。","respondent":"片田建築課長、吉川住環境整備担当課長","answer":"耐震化の話は、特にマンションとか用途別の施策の中で検討してきていることはご承知のとおりです。特に耐震化率は９０％、今回の建物の不燃化で一番望ましいのは同時進行です。ソフト対策の方法というご質問があったかと思いますが、一つの手法といたしまして、今後滝王子通り沿道では防災まちづくり検討会などの設置も今後検討して。","voiceIndex":57,"id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"防災まちづくり検討会というお話がありましたけれども、どのような検討会を想定しているのか教えていただきたいと思います。今日の説明を聞いていても、ソフト対策の強化の中身、また８年間でどこまで現在計画が進むかということを含めて、慎重な調査検討が求められると思うんです。","respondent":"岩田まちづくり事業部長、吉川住環境整備担当課長","answer":"それだけではなくて、その区域を含んだ地域の皆様方にも、当然計画そのものが十分な幅員ではありませんから、いざというときのさまざまな防災上の活動も加味しながらやっていかなければいけませんので。防災まちづくり検討会は、平成２１年１０月頃に避難道路機能強化事業の開始を見込んでおりますので、その前後に防災まちづくり検討会の設置を考えているところです。","voiceIndex":60,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問","question":"今の説明ですとイメージが持てないです。どういう検討会なのか、もちろん協議の中で伝えるという説明はありましたけれども、どのような形を描いているのか、中身を教えていただけますか。","respondent":"吉川住環境整備担当課長","answer":"基本的には沿道周辺の３町会を考えております。それから、検討する中身ですが、一つはまちづくりルール、それから先ほど申し上げましたソフト対策等の意識啓発等も兼ねるような話し合いの場を持っていきたいと考えております。","voiceIndex":63,"id":"exchange-018"},{"speaker":"井上委員","kind":"質問","question":"品川区でこの計画を検討して、平成１９年７月に住民説明会を行って初めて詳しく説明をされたと思うんですけれども、人数が少ないのではないかと思ったんです。先ほど権利者の方には密に説明するということでしたので、３回同じ地域に同じ説明をしたのか、最低どのぐらいに人に呼びかけて、どういうふうに説明したのかという、３回の内容を教えてください。","respondent":"吉川住環境整備担当課長","answer":"開催の趣旨ですが、１回目は道路の拡幅についての説明です。２回目は道路を拡幅することと、都市防災不燃化促進事業の建築助成制度について周知を図りました。","voiceIndex":65,"id":"exchange-019"},{"speaker":"井上委員","kind":"質問","question":"それについて早々の対策がこれから必要だと思うんですけれども、具体的にどういうふうにしていくかということをお伺いしたいと思います。それから、まちづくり勉強会を開催したということですが、具体的にはどういう方々が参加して、どういう学習会をされたのかお聞かせください。","respondent":"吉川住環境整備担当課長","answer":"今後ということですが、先ほどご説明しましたように、平成２０年度のスケジュールの中で、６月以降アンケート調査を実施する予定ですが、アンケート調査は郵送の案内だけではなくて、戸別訪問をいたしまして渡したいということも考えているところでございまして。","voiceIndex":67,"id":"exchange-020"},{"speaker":"井上委員","kind":"質問","question":"すごくこれから難しいなと思ったんですけれども。その中で、まちづくりの道路計画の説明会に出たときに、随分経ってから戻ったような議論があるんです。そこで、これ以外に一方通行にするとか、いろいろな検討かあったと思うんですけれども、区民の方たちにどういう説明をされて、参加された方たちが納得する説明会になっているのかどうか、区民の方たちの様子はどうですか。","respondent":"岩田まちづくり事業部長、吉川住環境整備担当課長","answer":"区民の方の感触は、後ほど課長がお答えするとして、住民説明会の出席者が多いか少ないかというのは、見方で分かれます。一般的に説明会を行政でやる場合、反対の方は必ずいらっしゃる。賛成の方はまず来ないです。これが一般的です。この質問に対しては、「反対者が多い場合は区で押し切ることはできませんので、今後事業の必要性を全体に説明していくようにしていきます」というお答えをしています。","voiceIndex":69,"id":"exchange-021"},{"speaker":"井上委員","kind":"質問","question":"南品川は建替え時において地区計画に沿ってということですが、今回の場合は、３枚目のところで部分的な閉塞が想定されるということは、セットバックできない住宅があったとしても、それは置いておいて拡幅していくということなのか。先ほど、１３５棟で可能という意味がわからないんですけれども、その辺はどういう意味なんでしょうか。","respondent":"岩田まちづくり事業部長","answer":"これも建替えのときに耐火構造にしてください。１０年間は補助を出しますという計画で、今、ご説明をしております。場合によっては、地域の人たちは、そんな生ぬるいことではだめだと。","voiceIndex":72,"id":"exchange-022"},{"speaker":"井上委員","kind":"質問","question":"道路計画とは違って、遅々として進まずということがあったとしても、助成を使わないという人たちがいて進まなければ、それはそれで仕方ないということで理解していいのでしょうか。","respondent":"岩田まちづくり事業部長","answer":"今の時点で、いつから切り替えて強制的にやるかとか、そういうことを考える段階ではないと考えております。","voiceIndex":74,"id":"exchange-023"},{"speaker":"阿部委員","kind":"質問・要望","question":"建替え助成については１０年間ということですが、拡幅の終了というのはいつ頃を目処と考えていらっしゃるのか。それから、この地域は電線地中化の要望が非常に強い地域だと思うんですけれども、完全に拡幅の用地取得ができた後でないと電線地中化はしないということなのか、その辺を確認させてください。","respondent":"吉川住環境整備担当課長、松代管理工事課長","answer":"事業の期間ですけれども、先ほど部長から申し上げましたけれども、１０年間というのは建替え助成の１０年間ということで、拡幅のこれまでの例でとらえると、都市計画道路の例でいくと５０年ほどかかっておりますので。今後の進捗状況を十分見させていただいて、計画等を進めて、その時点でまた皆さんにご説明をしたいと思います。","voiceIndex":76,"id":"exchange-024"},{"speaker":"阿部委員","kind":"質問","question":"部分的に着手するということだと思うんです。その前の５０年近くかかるという、この辺は何かご答弁の補足はないですか。","respondent":"谷田部まちづくり事業部次長","answer":"私も何回か説明会に出ていますので、私からご答弁申し上げます。先ほど部長が申し上げましたとおり、都市計画道路ではない任意で進めなければならない拡幅事業ですから、当然法的拘束力があるわけではございません。","voiceIndex":79,"id":"exchange-025"},{"speaker":"井上委員","kind":"意見","question":"１３５棟に最近建てられた建物も含まれているという理解でいいのかということと、先ほど行政として１０年間の助成をつけたときに、大体説明会の感触とかいろいろなもので、かたい建物は別としても建替え可能な住宅などを含めて、どのぐらいで品川区が目指す１０ｍ道路ができると予測されているのかわかりますか。","respondent":"谷田部まちづくり事業部次長","answer":"その方々がご自宅なりご自分で所有する建物の建替えるがいつ頃になるかというタイミングになりますので、外見でこれは相当老朽化が進んでいるからそろそろだなということは推測できますけれども、実際に建替えに着手されるかどうか、所有されている方々が。","voiceIndex":83,"id":"exchange-026"}]},{"id":"topic-04","title":"の東京都市計画防災街区整備方針の変更","agenda":"の東京都市計画防災街区整備方針の変更","exchanges":[{"speaker":"阿部委員","kind":"質問","question":"幾つか基本的なことを教えてください。整備方針というのは、定期的に改定されるものなのでしょうか。それから、各自治体に意見照会ということなのか。それから、品川区としては、どう回答をしたとか、するのかということがどこかに書いてあるのか。それから、それぞれの自治体の回答が戻ってきて、東京都が受け取ってというのは、手続的なことととらえてよろしいのでしょうか、教えてください。","respondent":"吉川住環境整備担当課長","answer":"品川区の回答といたしましては、４月１８日に行われます都市計画審議会でご審議いただいて、それに基づいて回答をするという予定です。","voiceIndex":89,"id":"exchange-027"},{"speaker":"阿部委員","kind":"質問","question":"５ページの地図を見ると品川区ばかり広くするなというのが、少し悲しい気分になるんですけれども、これに指定される地区というのは、基準は一律のものなのでしょうか。客観的な基準で指定になったり、ならなかったりということではなくて、政策的な要素が入って、品川区がこれだけ広いということなのでしょうか。","respondent":"吉川住環境整備担当課長","answer":"指定の考え方ですけれども、東京都市計画防災街区整備方針の２ページ、策定の考え方の２番に防災再開発促進地区の指定の考え方がございまして、(1)に防災都市づくり推進計画の重点整備地域または整備地域に指定されている地区ということが一つの基準になっているわけですが。","voiceIndex":91,"id":"exchange-028"},{"speaker":"阿部委員","kind":"質問","question":"そうすると、今回新たに指定されたところは、要は指定されることにより補助金がおりるようになるとか、効果を教えてください。","respondent":"吉川住環境整備担当課長","answer":"先ほどの説明の中で申し上げましたが、まず一つといたしましては、３ページの５番のところに記載されております事業・制度などが活用しやすくなるということがあります。","voiceIndex":93,"id":"exchange-029"},{"speaker":"阿部委員","kind":"意見","question":"防災街区整備事業というのは活用しやすくなるというのは、重点整備地域だけではだめで、今回の防災街区整備方針の中に入っていると、より活用しやすくなるという理解でいいのかということ。つまり、これだけ広い面積が指定されているということは、少々不名誉ではあるけれども、事業としては展開しやすくなるという理解でいいのか。","respondent":"吉川住環境整備担当課長","answer":"防災都市づくり計画の重点整備地域も、品川区は他区より広いという状況がありますが、確かに不名誉なことかもしれませんけれども、今回防災再開発促進地区に広く指定されることによって、制度が活用しやすくなるというのは利点としてとらえております。","voiceIndex":95,"id":"exchange-030"},{"speaker":"中塚委員","kind":"質問","question":"今回の変更ですけれども、現状から伺いたいと思います。今回の変更では大体ヘクタール当たり５倍ぐらいになり、現状の計画の中で何がどれぐらい進められたのか、計画の実績というんですか、ここを説明していただけますか。この拡大によって、その方向でということなのかどうか、あわせて教えていただけますか。","respondent":"吉川住環境整備担当課長、岩田まちづくり事業部長","answer":"そのほか都市防災不燃化促進事業等を実施しているところもあります。それから、現在再開発促進地区の中で荏原二丁目は密集事業を完了しています。最近では西大井地区、豊町地区、二葉地区とどんどん拡大してきたんですけれども、都市計画では何年に１回しか変更しませんので、今回の都市計画の変更に合わせて、今までずれていたエリアを整合性を図りましょうということです。","voiceIndex":97,"id":"exchange-031"},{"speaker":"中塚委員","kind":"質問","question":"要は、区から働きかけたのか、国や都からなのか、それとも双方の思いが一致したのか、どういう経過があったのか伺いたいのと、いろいろな事業がありますけれども、どういうところにねらいと目的を持っているのか、重なる説明になるかもしれませんけれども、あわせてお願いします。","respondent":"岩田まちづくり事業部長","answer":"５ページを見ていただければわかるんですけれども、千代田区を中心にしてドーナツ状に木密地域が存在しているわけで。ここ十数年、各区とも木密地区の対策を苦労しながら、徐々ですけれどもやってきたわけです。","voiceIndex":100,"id":"exchange-032"},{"speaker":"中塚委員","kind":"質問","question":"策定の効果、やりやすさのもとになるのかもしれませんけれども、１ページに策定の効果が(1)から(6)までありますけれども、非常に簡単に書かれているのでよくわからない。例えば、(2)の延焼防止上支障のある建築物への除却勧告が可能になるという、強いことばに聞こえるんです。今までと違って、どういう強制力が含まれるのか、何が変わるのか、そこを教えていただけますか。","respondent":"吉川住環境整備担当課長、片田建築課長","answer":"再開発促進地区に指定されると、除却の勧告が可能になるです。強制力というお話がございましたが、除却の勧告に従わなかった場合の罰則、強制執行等の強制力というものは法律上定められておりません。ただ、今回整合性を図って、ほぼ重点整備地域と同等のエリアを指定する方向での方針を整備し直すことによって、より区としての整備事業がやりやすくなるというような考え方に基づくものです。","voiceIndex":102,"id":"exchange-033"},{"speaker":"中塚委員","kind":"質問","question":"除却の勧告が可能な今とどのように違うのかということで、建築課長の説明ですと、条例化することによって指導が強くなるという意味なのか、この変更でその辺がどのように変わるのか、もう少しわかるように説明ください。それから、(6)の防災公共施設である道路、公園等について体系的・効果的な整備が図られるということで、体系的・効果的というのは何を指しているのか、あわせてお願いします。","respondent":"片田建築課長","answer":"条例として定めがないと、方針だけですと理念というような形で終わってしまって、なかなか実効性まで伴わない。条例化によって、強制的な指導ができるということで、ご理解をいただければと考えています。","voiceIndex":105,"id":"exchange-034"},{"speaker":"中塚委員","kind":"質問","question":"一番心配しているのは、今のお話の中でも実効性が伴うというお話でしたけれども、整備する防災公共施設２０施設のうち、大ざっぱに言うと１８施設が道路整備です。半分が都市計画道路で、その中には住民から強い反対のある補助２９号線も含まれているわけです。付け加えで言うと、補助２９号線は進めるべきではないと私は思います。","respondent":"岩田まちづくり事業部長","answer":"あわせながら、建物の新防火あるいは建替えを促進することによって、地震に強いまちづくりを進めていくという、面整備での街整備の考え方で来ているわけです。","voiceIndex":107,"id":"exchange-035"},{"speaker":"中塚委員","kind":"質問","question":"この計画を見てみますと、防災公共施設が何なのかとページをめくっていたら、２施設は公園ですけれども、１８施設は道路の話なんです。現在計画の９割が道路を目指しているわけだけれども、それ自体によっては、当然被害想定も抑えられるわけです。そうすると、延焼遮断帯の議論も、市街地大火災が起きる条件も変わってくるはずです。名を借りたと思えるんですけれども、いかがでしょうか。","respondent":"岩田まちづくり事業部長","answer":"今、中塚委員のおっしゃっているのは、補助２９号線を頭に入れてのご質問だと思うんですけれども、一つには、今防災のお話をしていますので、当然２０ｍクラスの都市計画道路は延焼遮断帯としての機能が当然あるわけです。","voiceIndex":109,"id":"exchange-036"},{"speaker":"中塚委員","kind":"質問","question":"道路をきちんと抑えるというお話だと思うんですけれども、市街地大火災の危険度というのですか、延焼率とか出火率は変わってくるはずで、それを目指しているわけですね。逆に伺えば、９割達成しても、市街地火災の危険度は変わらないと思っているのか、変わってきますよね。市街地火災の危険度が変わらないということなのか、そこを教えていただけますか。","respondent":"岩田まちづくり事業部長","answer":"火災危険度と延焼危険度、つい最近までは避難危険度という項目がありますけれども、それらをトータルした総合危険度で、５００ｍメッシュでどのぐらいの地区が総体的に危険かというものを出しているわけです。","voiceIndex":111,"id":"exchange-037"},{"speaker":"三上委員","kind":"質問","question":"荏原地区でこれだけ地域が拡大されたことと、先日の予算特別委員会の中で私がお尋ねした武蔵小山駅周辺地区という位置づけで５６haの整合性というのはかみ合っているのでしょうか。どちらかというと、補助２６号線の小山四丁目とか荏原四丁目の境目に線引きがあるけれども、この地域との整合性は合っていると受けとめていいのでしょうか。","respondent":"青木都市開発課長","answer":"今、防災街区でご説明しておりますのは、どちらかというと拠点ではなくて面的に広がる市街地について、修復型のまちづくりをどのように進めていこうかという点で前提となる都市計画というように、ご理解をいただきたいと思います。","voiceIndex":113,"id":"exchange-038"},{"speaker":"三上委員","kind":"質問","question":"小山四丁目、荏原四丁目、どちらにしても道路的には確かに区画的な道路みたいになっていても、まだ木造住宅が多い地域ということになれば、そういう地域をわざわざ、これは補助２６号線通りに面した部分だけは含んでいるけれども、それよりもう少し外側というか、地域的にいえば内側に何十メートルか入った部分から以降は外してしまうということではなくて。","respondent":"青木都市開発課長","answer":"武蔵小山周辺の検討において、三上委員ご指摘の小山四丁目まで検討エリアを拡大しているというのは事実です。これはまちの中心となっていますパルム商店街が小山四丁目に広がっているというところから、そういったエリアでの検討をしていこうという設定をしたものです。","voiceIndex":115,"id":"exchange-039"},{"speaker":"三上委員","kind":"質問","question":"そういう流れの中にあって、商店街を中心とする話の中からどうするかという話になったときに、再開発的な部分で補助２６号線の直線ではなくて、もっとそこに行き止まって地域として計画されているところがあるではないですか。そこが外れているということ。学校の敷地の一部分だけ入るかわからないけれども、もう少し広げた部分で小学校の地域を入れてもおかしくないと思うけれども、どうですか。","respondent":"青木都市開発課長、片田建築課長","answer":"いろいろなお話があればお聞かせいただいて、行政なりの考え方をご理解いただきながら、合意点を見つけてまちづくりを進めていこうと考えています。今回２月に危険度調査の平成１９年度バージョンが出てきましたし、また東京都としても、今後も含めた検討もなされると思ってありますので、そういう状況を見極めながら、区としても検討を進めていきたいと考えております。","voiceIndex":117,"id":"exchange-040"},{"speaker":"三上委員","kind":"質問","question":"制度方針の変更が、都市計画決定がされた段階で、初めて区民にお知らせするという形にならざるを得ないことになります。よく聞く話ですが、変更になった段階で初めて知ったとか、全然知らなかったという声が多く出てきてしまうんです。変更になることについて、どのようにお知らせしていくかという、その辺はどうなんでしょうか。","respondent":"吉川住環境整備担当課長","answer":"住民の皆さんへの周知というご質問かと思いますけれども、都市計画法第１６条に基づく広聴会の開催に係わる縦覧は、昨年９月３日から１８日まで東京都で行われました。それに合わせまして、品川区といたしましても、広報しながわに掲載してお知らせしております。","voiceIndex":120,"id":"exchange-041"},{"speaker":"三上委員","kind":"質問","question":"まちづくり事業部のホームページにこのようなことは載せるのですか。","respondent":"青木都市開発課長","answer":"これは都市計画法第１６条に基づくもので、都市計画施設あるいは大まかな都市計画の方針については、必ずしも説明をしなければいけないということではなくて、公告・縦覧をした中で公聴会を開いてほしいという意見等があれば。","voiceIndex":122,"id":"exchange-042"},{"speaker":"石田（秀）委員","kind":"質問","question":"変な方向から話を聞きたいと思っているんですが、木造住宅の耐震化が確か５３％で、あと４７％が耐震化できていない。変更後の防災開発促進地区に４７％の９割がここに含まれているとか、概算でいいけれども教えてもらえればということが一つ。","respondent":"片田建築課長","answer":"ただ、この地域に中に昭和５６年以前の区内全域の木造住宅の約７割ほどが、この方針の地域ではございませんで、整備地域と言われるエリアは約７７０haほどありますけれども、その中に集積されてきているような状況です。","voiceIndex":124,"id":"exchange-043"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"この地域はいろいろなことを考えて、例えば共同化でも条例化でもいろいろなことをしながら、例えば防災街区の整備をしていこうということで、それはそれでしっかりやっていただきたい。協力してくれた１軒も接道の幅員が少なくて、思ったような建物が建たないとか、法律上、無理だということが必ず起きてきて、必ず立ちどまってしまう。それをどこまで考えていただけるのかという、お考えだけ聞いておきます。","respondent":"片田建築課長","answer":"ただ、難しいのは地権者の借地とかいろいろ要件がありますので、そういうものをまとめ上げて、それを一定の方向性まで導けるような何らかの体制なりシステム、あるいはそういう支援が別途必要なのかなというようなことは既にしています。","voiceIndex":126,"id":"exchange-044"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"なぜかというと、接道している人は自分の後ろの人たちのために、あなたは関係ない、うちはうちでやれるという感覚があるから。ところが、接道していない路地の中にずっと入っていくような人は、どうしてもある程度の道路に接道しなければ無理なんです。その辺はぜひ何か一緒にやるときに平米数、これだけの人がやるのならやるとか、そういうことはぜひ考えていただきたいと思います。要望にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":128,"id":"exchange-045"}]},{"id":"topic-05","title":"の小山台一丁目地区防災街区整備地区計画の変更","agenda":"の小山台一丁目地区防災街区整備地区計画の変更","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"一つだけお伺いします。これはこれで非常にいいことだと思いますが、物事の考え方を教えていただきたいと思います。例えば池田山とか島津山のような街並みであれば、それなりの評価も上がるし、後からいろいろな方が来ても、それを求めてくる方が来る。こういう場合ですと、ここは沿道もあるし、周りもあるけれども、そこを求めて来る方が後からでもいるような地域にしなければいけないわけです。","respondent":"吉川住環境整備担当課長","answer":"やはり、品川区として、既に平成１８年時点で方針等が決まっておりますので、これに沿った街並みをつくっていきたいというものがあります。そうしたことのバランスを十分に踏まえて、コンサルタントに十分意見調整をする必要が、時には指導する必要があると考えております。","voiceIndex":134,"id":"exchange-046"},{"speaker":"石田（秀）委員","kind":"提案","question":"品川区の中で、例えばその地域で６０m2という考え方がポピュラーなのかという判断はどこでしたのですか。同じようなことばかりになっているのかなと思ったので、このまちの独創的なものがこの中に何かあったというのなら、逆に教えていただきたいと思います。","respondent":"吉川住環境整備担当課長、岩田まちづくり事業部長","answer":"敷地が６０m2以上という制限につきましては、まず品川区として住民の方々に説明をしたときに、やはりあまり土地を細切れにして、密集地域を新たにつくるようなことはないようにというお話から。ただ、品川区の地区計画の原案をつくるにあたって、地域の地権者の方と十分な話し合いをしてきたというプロセスを課長が説明させていただいただけでございまして。","voiceIndex":136,"id":"exchange-047"},{"speaker":"石田（秀）委員","kind":"意見","question":"あまりこだわるつもりはないけれども、品川区は開発で例えば狭少宅地で、建売でも何でも５０m2以上にしようと言っていると思うんです。業者が買い付けする場合は、そこが一つの目安なんです。開発業者も、品川区の中に売る土地があれば、そういう部分で割ってやっていくのは５０m2だと思うんです。私が違っていたらごめんなさい。","respondent":"齋藤住宅課長","answer":"５０m2です。","voiceIndex":139,"id":"exchange-048"},{"speaker":"石田（秀）委員","kind":"意見","question":"売るほうも、これでうまく二つに割れてというのがあったり、三つに割れてというものがあったのが、これはちょっととなるというのが、その辺は、指導が５０m2がいいところなのかなと思ったんだけれども、それはいいです。お願いにしてください。その辺の差異があると、買うほうも、もちろん地主さんもいらっしゃるわけですし、周りに合わせたほうがいいのではないかと思っているということだけです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":141,"id":"exchange-049"},{"speaker":"中塚委員","kind":"質問","question":"経緯の説明の中でアンケート調査実施のお話がありましたけれども、Ａ地区で２１軒、Ｃ地区で１４軒ということですけれども、対象者がそれぞれ何軒なのかお聞きしたいと思います。主な意見という形で説明がありますけれども、さまざまな意見が当然出るわけですから、そのものを提出していただけたら地域の様子がわかると思うんですけれども、その点はいかがでしょうか。","respondent":"吉川住環境整備担当課長","answer":"アンケートの対象人数ですけれども、Ａ地区では３２５軒、Ｂ地区が６５４軒、Ｃ地区が４５５軒です。アンケート結果を資料にというお話ですけれども、今後考えていきたいと思います。","voiceIndex":142,"id":"exchange-050"},{"speaker":"中塚委員","kind":"質問・要望","question":"例えば、Ａ地区であれば３２５軒中２１軒の回答があって、２５％の回答率という区の評価としてあったとしても、その説明ですとまちの全体像がつかめないんです。今、お話がありましたけれども、アンケート調査を実施した結果がまとまるわけですから、資料としてご提示いただきたいと、改めて要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":144,"id":"exchange-051"},{"speaker":"三上委員","kind":"質問・要望","question":"先にＣ地区の富士見通りですけれども、幅員６.５ｍにするという計画があって、昨年末の富士見通り商店街が解散しました。こういうことが整合性ととらわれないうちに、こういう要望を聞いてポールを立てていこうということでいいのかどうかということだけれども、その辺はどういうふうに考えていらっしゃるのか。","respondent":"吉川住環境整備担当課長、岩田まちづくり事業部長","answer":"前回、平成１８年に都市計画決定をした際に、地元から道路の安全性を高めてほしいという要望がございまして、今回のポール設置も地域の方の要望によるものです。申し訳ございません。詳細について把握できていないようですので、後ほどお答えしたいと思います。","voiceIndex":145,"id":"exchange-052"},{"speaker":"三上委員","kind":"意見","question":"去年の年末に職員が街路灯を撤去してしまったわけです。車が目黒不動尊のほうから坂道を上がってくると、上がり切ったところにポールが立っているということが、補助４６号の交差点のところまでの距離にしても、その間だけでもどういう道路整備を考えるのか。それに伴っての道路整備ということについて、基本的な考え方をどういうふうに指導していくのか、ということを聞きたいわけです。","respondent":"松代管理工事課長","answer":"そこに立てたものについては、その方とも十分今後の計画をご説明して、今の位置づけが将来別な側での安全対策、道路の中でもそこだけが特別ではなくて、その路線全体の安全対策というような位置づけというものを、きちんと考えてお示ししていきたいと考えているところです。","voiceIndex":148,"id":"exchange-053"},{"speaker":"三上委員","kind":"質問・要望","question":"今日、明日がどうのこうのということはできないと思いますけれども、こういう建物に対する指導をこれからしていくということであるならば、道路のつくり方もみんなの意見を聞いて、こういう道路にしましょうというものがあって然るべきだと思うんです。だから、通りに面した人の意見と一歩何軒か裏側に入った人の意見と違うわけです。そういった視点からも取り組みをしていただきたいとお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":150,"id":"exchange-054"},{"speaker":"井上委員","kind":"質問","question":"この地区計画検討会は、住民の方たちがいろいろ協議をしながらつくり上げていったものなのかと読み取れます。先ほど、行政計画であるということだったんですけれども、こういうまちづくりを進めていくべきだという思いがあるんですが、地区計画検討会が固定された会議であったのか、それとも地域の方たちが入りやすくなってきた会なのかということを教えてください。","respondent":"吉川住環境整備担当課長","answer":"Ａ地区の地区計画検討会についてのご質問かと思いますが、メンバーは町会の推薦者と公募を募りまして２０名、常時１０名程度は参加していただいている検討会です。今回の整備計画をもって、一たん地区計画検討会は終了しております。","voiceIndex":151,"id":"exchange-055"},{"speaker":"井上委員","kind":"質問・要望","question":"今年の予算で総合型のまちづくりの推進という部分があって、具体的には見えていなかったんですけれども、まちづくり事業部がかかわっている内容は、区民が行うまちづくりのコンサルタントの派遣ということではなく、まちづくり事業部としては何か発表するものがあるのか、関連してお聞かせいただきたいと思います。","respondent":"藤田道路公園課長","answer":"そういった中で、地域における総合的なまちづくりのあり方がどういうふうに進めればいいのか、その辺についても十分議論をする中でその方法論を見つけ出して、それからその事業に取り組んでいこうというような形で考えているものでございまして。","voiceIndex":153,"id":"exchange-056"},{"speaker":"須貝委員","kind":"質問・要望","question":"確認だけなんですが、今回小山台一丁目地区で実際に幅員が取れているところもあるかと思うんですが、影響が出ると予想される建物自体は何棟ぐらいあるのか、わかる範囲で教えていただきたいと思います。","respondent":"吉川住環境整備担当課長","answer":"富士見通りの拡幅につきましては、平成元年から任意事業で実施しておりまして、現在７３棟中１４棟を壁面後退により整備しております。達成率が３７％、残り５９棟です。","voiceIndex":155,"id":"exchange-057"},{"speaker":"須貝委員","kind":"意見","question":"今回、壁面後退区域における工作物の設置の制限等、いろいろ出てきているわけですが、当たり前のことだと思うんですけれども、住民の方にとっては不利益になるような条件が変わってくるということは、１軒１軒の方に完全に周知されていると考えていいんですね。","respondent":"吉川住環境整備担当課長","answer":"平成元年から実施している事業ですので、十分浸透していると考えております。","voiceIndex":157,"id":"exchange-058"},{"speaker":"須貝委員","kind":"質問・要望","question":"住民の皆さんの協力を得て整備地区計画を、さらにいい方向で進めていただきたいと思います。今回、整備計画が追加されるということですが、実際に道路が完成されていないのに、さらに整備計画を出しづらいと思うんですが、道路がどんどんつくられていく時点では、こういう計画がなかったのですか。逆に、もっと早くわかれば、住民の皆さんにお示ししながら、補助４６号線の協力もできたのではないか。","respondent":"吉川住環境整備担当課長","answer":"Ａ地区におきましては、平成１５年から不燃化促進事業を実施しておりまして、平成１５年以降の新しい建物については不燃化されていると考えております。","voiceIndex":159,"id":"exchange-059"},{"speaker":"須貝委員","kind":"確認","question":"補助４６号線がぽんとできて、住民の皆さんに協力していただいて、新たに立派な道路ができるというパターンも少ないかと思うんですが、できるだけ早くお示ししていただければ、皆さんが家を建てる、で、そこにきちんとした家を一生に一度家を建てるわけですから、新たに追加の整備計画がくると困る方も出るのではないかという気がしますので、よろしくお願いいたします。","respondent":"片田建築課長","answer":"その法律の以前に確認を処理しているもので、工事が着手していればよかったのですけれども、着手していないものについては、６月以降着手するという部分であれば、一部計画変更というような一定の法律の手続を取っていただいて。","voiceIndex":161,"id":"exchange-060"},{"speaker":"須貝委員","kind":"確認","question":"目黒区は建築確認を出したら、適用は従前のでという話を聞いたんですけれども、そういうことはないですか。","respondent":"片田建築課長","answer":"全国一律ですから、その考え方は基本的には違うのかなと考えています。","voiceIndex":163,"id":"exchange-061"},{"speaker":"須貝委員","kind":"質問","question":"これで駆け込みとか起きる場合があるのではないか。今の状況ではどうなるかわからないんですが、その前に実際は法律で動くから難しいと思うんですが、駆け込みを防止するような方法が取れれば、せっかく住民の皆さんが決めているわけですから、何かいい方法があったらいいなと思います。","respondent":"片田建築課長","answer":"なおかつ、地元の方にも整備計画をまとめる上で、いろいろご説明をした中でご理解をいただいているという前提の中で進めてきてありますので、そのようなことにはならないのかなと考えています。","voiceIndex":165,"id":"exchange-062"}]},{"id":"topic-06","title":"の建築基準法第５１条ただし書の適用について（（仮称）ＪＲ東日本東京資源循環センター基本計画）","agenda":"の建築基準法第５１条ただし書の適用について（（仮称）ＪＲ東日本東京資源循環センター基本計画）","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"説明の中で、ＪＲと区との協議が終わったとありましたけれども、この間の区との協議がいつぐらいから始まっているのか、経過の中身を教えてください。それから、一般廃棄物処理施設の設置に都市計画の位置づけが必要だというご説明でしたけれども、その理由を教えていただけますか。","respondent":"片田建築課長","answer":"協議を進めていく中で、昨年の８月か９月ぐらいに、区としても今後家庭系廃プラスチックを処理していくにあたって、現在品川清掃工場の中にある資源化センターで対応をしてきてございましたけれども、それを今後、今年の１０月ぐらいになりましょうが。","voiceIndex":171,"id":"exchange-063"},{"speaker":"中塚委員","kind":"質問・要望","question":"環境負荷の高いものは都市計画による位置づけが必要だと。今回の中間処理施設は焼却しないものだけれども、同等と見なすという話ですけれども、なぜ同等とみなすのか教えていただきたいと思います。環境負荷が高いものはというところですけれども、どういう調査をやったのか、全然手元に資料がないので、その辺がよくわからない。ぜひ資料を出していただければと思うんですけれども、どうでしょうか。","respondent":"片田建築課長","answer":"ただ、委員会の報告等については、まだ正式に９月の許可申請を受理しているわけではございませんし、説明会を行っているわけでもございませんので、現時点ではあらあらの内容を口頭で報告をさせていただいたです。","voiceIndex":173,"id":"exchange-064"},{"speaker":"中塚委員","kind":"質問","question":"環境への影響が大きいのか小さいのかは別にしても、何らかの影響があるからこういう手続の流れになるという説明でいいのか。要は、選別、圧縮、梱包の処理に伴って化学物質の排出とか、車が増えるわけですから車両台数とか、調査の中で大気とか騒音、振動、悪臭があるわけですから、近隣への影響があるわけです。今回の焼却炉はないということでいいのか。","respondent":"齋藤住宅課長","answer":"一般廃棄物の処理施設をつくるときは、手続が難しいものです。今、建築課長が説明したのは都市計画法上の問題です。都市計画法上は屠蓄場や清掃工場あるいは火葬場のようなものをつくるときは、東京都の都市計画審議会を経て、都市計画地図に位置をつくらなければいけない。","voiceIndex":175,"id":"exchange-065"},{"speaker":"中塚委員","kind":"意見","question":"要は、これが一度設置されると、施設の内容が変更する場合とか、処理能力が増える場合とか、そういう場合も設置の手続が必要なのか、それとも悪く言えば自動的に可能になってしまうのか、その先の手続はどうなのか。","respondent":"片田建築課長","answer":"例えば処理能力が５ｔ以上超えて廃プラスチックを処理する場合であるとか、破砕するような場合ですと、産業廃棄物という扱いがなされるという場合あるわけですけれども、そういうものをきちんと審査した中で、その能力の最大限、上限値を見て許可するという状況ですから。","voiceIndex":177,"id":"exchange-066"},{"speaker":"中塚委員","kind":"質問","question":"雑駁に処理能力を全部足したんですけれども、６４.５ｔです。その処理能力を超える場合は、今回と同じような手続の流れになるということでいいですか。","respondent":"片田建築課長、齋藤住宅課長","answer":"誤解されるといけないので、５１条ただし書の敷地の場所の許可という話が一つ。ただ、一般廃棄物の処理施設としての許可は東京都ですし、産業廃棄物の処理の許可も東京都です。量だけではなくて、ごみについては衛生上問題がありますので、目的を変えたりするときは、必ず変更届許可をしなければいけません。","voiceIndex":179,"id":"exchange-067"},{"speaker":"中塚委員","kind":"質問・要望","question":"量にしても内容にしても変更するには許可が必要だということです。何を心配しているかというと、知らず知らずに中身が変わっていくというと困ってしまうわけで、そういうときはしっかり報告していただきたいということです。要は、住民説明会というのは考えていらっしゃることはないのか。そういう意味でも、住民説明会はやるべきではないかと思うんですけれども、その辺のお考えをお聞かせください。","respondent":"齋藤住宅課長、片田建築課長","answer":"ただ、ここはＪＲの車両のほうには時刻表の看板とか、あのようなところを処理するものでありまして、現に上野駅や尾久駅や田町駅で普通にやっているところで。条例上の説明会は、確かに中塚委員がおっしゃるように、２Ｈということでおおむね高さ１５ｍぐらいになるかなと思うんですけれども、３０ｍという話もありますが、ただ、実際に区としても許可する上で。","voiceIndex":182,"id":"exchange-068"},{"speaker":"井上委員","kind":"質問・要望","question":"紛争予防条例に基づく説明会の期間ですけれども、１８日の都市計画審議会に報告をされて、大体予測はついていると思うんですけれども、どのぐらいの時期に予定されているかということと、Ｃ棟の品川区内の家庭から排出されるプラスチック製容器包装の部分は、将来的は品川区だけではなくて、業者が受ければいろいろな区から車の搬入が来てというところは。","respondent":"片田建築課長","answer":"現時点で、私のほうから答えられる部分としてお話ですけれども、説明会等々の予定については、紛争予防条例の関係を含めて調整を事業者と行ってありますので、おおむね５月の連休明け以降の流れになろうかということを考えてあります。","voiceIndex":185,"id":"exchange-069"},{"speaker":"井上委員","kind":"質問","question":"搬入台数の問題で、これだの車が処理施設に来るということで、区民に対する影響はどのように想定しているのかという、予想される部分というのはどことどこなのかと思いますけれども、１日の処理量ということでしたので、これだけの車がどんどん来ると思うんですが、そのことについてはどのように把握されているのでしょうか。","respondent":"片田建築課長、岩田まちづくり事業部長","answer":"ただ、現時点で車のルート等を調整した中の考え方として、支障ないという判断が出てありますので、詳細については現在調整中ですので、正式な手続を踏まえた中でご提示していきたいと考えております。今、資料に出ている数を全部合計しても１００台いかないんです。","voiceIndex":187,"id":"exchange-070"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"一つ聞きます。品川区内から排出される家庭系廃プラスチックの中間処理を、先ほど話し合いの中で頼んだと言ったけれども、行政側の中のだれが頼んだのか、それだけ教えていただきたいと思います。それから、先ほども言った区の建築主事の許可で建築確認はオーケーなのか教えてください。","respondent":"片田建築課長","answer":"ＪＲとのやり取りについては、環境課サイドのほうへ調整してきたというところがあります。もう一つ、許可については建築主事ではなくて品川区長になります。","voiceIndex":190,"id":"exchange-071"},{"speaker":"石田（秀）委員","kind":"質問","question":"これからでも間に合うなら、ぜひやってほしい。１４ｍぐらいの高さなら、その上に地盤をつくって野球場とか多目的広場をつくってしまえばいいではないですか。その使用料ぐらいはＪＲに出せ、ぐらいの発想を持ったのか持たないのか。そうではなくて、１５ｍぐらいの上に地盤をつくって、下水処理場の上はいろいろなものがある。そういう発想は持ったのか持たないのか、そこだけ教えてください。","respondent":"岩田まちづくり事業部長","answer":"現在、東品川二丁目の天王洲の中間処理施設でやっているわけですけれども、基本的には縮小廃止するという方向になりましたので、こういう方向で区として調整を進めたわけです。","voiceIndex":192,"id":"exchange-072"},{"speaker":"石田（秀）委員","kind":"意見","question":"それは研究したのかしないのか、私が見る限りでは、この手前は建物を動かしてもらえば１００ｍぐらいの区画なんかはつくれます。航空写真で見ると、航空写真の手前でしょう、後で調べるけれども、そういうものができそうだなと思うような雰囲気はあるんだけれども、そういうことを考えたのか考えないのかということです、大切なのは。","respondent":"片田建築課長","answer":"基本的には、この施設そのものが相談の段階で、ＪＲの土地ということもありまして、区のお願いができないかというようなことについては、土地自体はＪＲ、Ａ棟、Ｂ棟についてはＪＲの費用負担でつくると。","voiceIndex":194,"id":"exchange-073"}]},{"id":"topic-07","title":"の平成２０年５月都営住宅（世帯向・単車者向住宅等）の募集","agenda":"の平成２０年５月都営住宅（世帯向・単車者向住宅等）の募集","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"明確に答えてほしいのは、失効期間があって、この間に減ってしまった分というのは戻ってこないのはわかっているわけでしょう。それが５月になるか６月になるかわからないけれども、必ず失効期間が出てしまっているわけですから、その概算というのは幾らですか。それが９億３,０００万円なんですか。","respondent":"岩田まちづくり事業部長","answer":"少なくとも先ほど説明しましたように、最短５月末で再内示があったとしても、数億円規模の歳入減、歳入欠損が出そうだというふうに見ております。","voiceIndex":204,"id":"exchange-074"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3906#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":61627,"voices":206}},{"id":"h20-20080415-9","meetingId":"h20-cm04","date":"2008年4月15日","dateIso":"2008-04-15","committee":"文教委員会","time":"午後１時０２分～午後２時３２分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"最初に、(1)平成２０年度学級編制","agenda":"最初に、(1)平成２０年度学級編制","exchanges":[{"speaker":"市川委員","kind":"質問","question":"１年生から２年生に上がるときと５年生から６年生で、３年から４年でもクラス替えがあるけれども、そこは制度として対象になっていないんだということと、それからあと、この制度は申請をすれば必ず学級維持制度が適用になるのかということについて伺います。","respondent":"富田学務課長","answer":"ご質問のとおり、３年から４年に上がるときについてはそういった適用はないです。この学級維持制度は、申請すれば必ずということではありませんが、一応東京都のほうに協議をして同意を得て、こういった学級編制として決定をしたというものであります。","voiceIndex":24,"id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"そうすると、４０人を超えるクラスが１クラス出ているのかなというふうに思うんですけど、この辺は学校の先生方の検討の結果の数字なんだろうというふうに思うんですけど、その辺というのはどういうふうに教育委員会としては見ているのか、ちょっとここについて教えていただきたいということと、学級維持制度については今改めて確認ができたんですけれども、クラス数はこのままだと。","respondent":"河野指導課長","answer":"御殿山小学校につきましては、これは４４名で学級維持制度を適用なのかですが、これは最終的に児童数が確定する前の段階では、４０名になるか４１名以上維持できるかという、そういうぎりぎりの中で児童数が確定する前の段階で最悪の場合を想定して学級維持制度を申請したと。","voiceIndex":26,"id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"各学年４クラス、今度２年生は３クラスですけど、大半が４クラスということで、品川の全体の学校の状況から見ても、学級数の多い学校だということが選択されているところの数字として出ているなというふうに思うんですけれども、施設的にもいっぱいいっぱいの状況だということは漏れ聞いているんですけれども、そういうことも含めての判断なのか、あるいはまた、地域の中で聞こえる声は。","respondent":"富田学務課長","answer":"他の学校につきまして、人数的なことについてお答えをしますが、第三日野小学校は昨年８４名の入学で３学級でありました。次に学校番号１８番、伊藤小学校も昨年度８２名ということで、昨年３学級でありました。","voiceIndex":28,"id":"exchange-003"},{"speaker":"南委員","kind":"質問","question":"子どもの状況を見たときにかえないと、そこのところはわからなくないんですけれども、なかなかそういう施設的なことも背景にはあるのかなということをちょっと思ったので、その辺のことをちょっと伺いたいなというふうに思ったんですけど、大井第一小学校の施設的なそういう余裕の部分のところは、今どういうふうになっているのかをあわせてお尋ねして、あれするつもりはないんですけれども。","respondent":"市川教育次長","answer":"先ほど指導課長が申し上げましたけれども、あくまで学級経営、子どもたちの教育環境の面からこの学級維持制度を適用したということでございまして、大井第一小学校、これはほかの小学校もそうですけれども、施設事情が要するに普通教室のほかに多目的教室。","voiceIndex":30,"id":"exchange-004"},{"speaker":"南委員","kind":"質問","question":"ですから、優秀な先生がいらっしゃるというところでは、私どもがそれほど心配することはないのかなというふうには思っておりますけれども、しかしながら、そういう条件、教育条件のところを見たときに、やっぱりもう少し配慮されてもいいんじゃないかなというふうに思っていますので、区民の方々の選択との関係があるので難しいところはあるんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-005"},{"speaker":"西本委員","kind":"質問・要望","question":"それをどういう見方をされているのか、選択制の関係もありますので、どういう見方を教育委員会として見ているのか。もう一つは、さいかち学級というのが清水台小学校のほうにあると思いますが、この地区には今年はゼロという形になるんですが、これはどういう形で運営をされているのか、配置等々どういうふうな形になっているのか教えていただきたいと思います。","respondent":"富田学務課長、河野指導課長","answer":"学級編制の数を見たときに、大きく変化をしたところというご質問かと思いますけれども、昨年度までの学級数と比べて今年度増えたところといいますと、小学校では６番の城南第二小学校。昨年度重点支援した学校は主に新校の校長先生方、それから八潮の一貫校のように５校統合して新しい教育課程をつくるであるとか、そういう意味で大きな課題を抱えている学校。","voiceIndex":33,"id":"exchange-006"},{"speaker":"西本委員","kind":"質問","question":"児童数の変化ですが、要は選択制なものですから、選択制の中での影響といいますか、というのは、例えば中学校で言うと日野学園ですね、７年生が１４３人で、８年生以降が３３５人と非常に評価が高いというところだと思うんですが、これだけ数の変化が出てきている。相変わらず大井第一小学校であるとかというのは非常に人数も増えてきているという状況、伊藤学園はまあまあそこそこ。","respondent":"富田学務課長","answer":"小中一貫校への期待度等についての保護者の認識はいかがかといったようなご質問ですが、実はこの児童数、また生徒数というのは、学校選択によって、学校によっては抽選を行った結果ということがあります。","voiceIndex":36,"id":"exchange-007"}]},{"id":"topic-02","title":"平成２０年度品川区立幼・小・中学校（園）長、副校（園）長異動者名簿","agenda":"平成２０年度品川区立幼・小・中学校（園）長、副校（園）長異動者名簿","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"全くできない状況なのか、それともある程度品川区の教育を理解した上で来ていただきたいという方の要望というのはどれだけ取り入れられているものなんでしょうか。","respondent":"河野指導課長","answer":"なかなか答えにくい質問ですが、要望は出せないということはございません。ただ、要望に１００％こたえてもらえるという実態もございません。","voiceIndex":43,"id":"exchange-008"},{"speaker":"西本委員","kind":"質問","question":"そうすると、例えば区外に行かれる方がいらっしゃるわけですよね。それから、来たいよと、品川区でぜひ校長をやってみたいというような、そういう期待を持った方というのは結構いらっしゃるんでしょうか。どういうふうになっているんでしょうか。","respondent":"河野指導課長","answer":"ぜひ区内でというこちらで思いを抱いている人材も正直のところあります。そういう人材については、ぜひ区内でということで内申は出しておりますが、ただ、いろいろそれぞれの地区での事情等もありますので、なかなか要望どおりにならないケースも多いというのが実態です。","voiceIndex":45,"id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"決められる、内定する前に、教育委員会に面談とか、そういうのはあるんでしょうか。外から見るのと中に入るのとは全然違うと思うので、そこの折り合いというんですか、こういう方法でと納得した上でなのか、もしも納得いかなかった場合は、ご勘弁願うのか、お話できる程度で結構ですのでよろしくお願いします。","respondent":"河野指導課長","answer":"事前に品川区に対してどうなのかと、あるいは品川区の教育はこうですよという説明の機会があるのかですが、これは異動が内定した後の話でございまして。","voiceIndex":47,"id":"exchange-010"},{"speaker":"西本委員","kind":"質問・要望","question":"やはり、公務員ですから、東京都でいろんなところに辞令が出ればそこに行って、そこの場所のルールに従ってやっていくというのが当然だと思いますけれども、やっぱり意欲のある先生方、そういう意味では、独自採用という形になっていくんでしょうけれども、まだまだそういう形になりにくいところがあるので、できるならば、教育委員会等々、個人のところまで通用するかどうかわからないんですけれども。","respondent":"若月教育長","answer":"しかし、そういった努力を続けない限り、人事権の移譲だの地方分権だの、最近ははやり言葉のようにあたかもそれが実施されているかのごとき感じでちまたで言い流されていますけれども、決して実態はそんなもんじゃないということであります。","voiceIndex":49,"id":"exchange-011"},{"speaker":"南委員","kind":"質問","question":"施設一体型の学校で副校長職が三つどこもあるんですけれども、それぞれ事務と言ってはおかしいんですけど、そういう約束というかしら、分担されていないとなんか混乱しちゃうんじゃないかなという気が素人的に思うんですけど、その辺の状況というのはどういうふうになっているんでしょうか。","respondent":"河野指導課長","answer":"いわゆる事務分担といいますか、それぞれの副校長が担当する職務については、全部こちらのほうで一律にこういう形で分担を分けなさいという指示はしておりません。それぞれ校長の指揮のもと、各学校で分担を決めて、それぞれの職務に当たっているというのが現状です。","voiceIndex":51,"id":"exchange-012"},{"speaker":"南委員","kind":"確認","question":"そうすると、私たち地域の住民が学校の施設を例えば借りたいときに、副校長先生に今までは連絡して、そしてあいている日時等々の確認も含めて、副校長先生とお話しすることがあったんですけど、そういうのは当然そういうことで学校に連絡すれば、必然的にこの副校長にというふうに回っていくんだろうと思うんですけど、なかなかその辺がどなたというのがわからないし。","respondent":"河野指導課長","answer":"それは最終的に集約して割り振りを決めるとか、そういう部分についてはそれぞれの分担に基づいてやりますが、どの副校長に話をしても、結果的には話が通るということは絶対に保証できると思います。","voiceIndex":53,"id":"exchange-013"},{"speaker":"南委員","kind":"確認","question":"差し出がましくあれするつもりは全くないんですけど、学校の中のことですから、私どもがどうこう言える筋合いのものでもないというふうに思うのであれなんですけども、それぞれの学校の職務、事務分担のところで、先ほど申し上げたように分担されているということなんですけど、この３人の副校長の配置というのは、三つのポストを置いておくというのは。","respondent":"河野指導課長","answer":"一貫校につきましては、校長１名、原則副校長３名という体制で当面はやっていく予定です。","voiceIndex":55,"id":"exchange-014"},{"speaker":"南委員","kind":"質問","question":"最後なんですけど、副校長先生の仕事、職務の仕事、事務の内容、どういうものなのか、ちょっとその辺、３人の方々が配置されているというところで、ほかの学校との関係でも仕事量が多くなるのは当然それはわかりますけれども、じゃあどういうふうに違うのかというのはちょっと知りたいところなので教えていただけないでしょうか。","respondent":"河野指導課長","answer":"副校長のとる職務ということですか。","voiceIndex":57,"id":"exchange-015"},{"speaker":"南委員","kind":"質問・要望","question":"それが二つになったから副校長先生としては二つのポストがあっても自然かなというふうに思っているんですけど、あえて３人にしているという、そのところが一貫校教育をぐんと整備して、そしてきちんとした体系に組み込んでいく、そういう過渡期なので、３人の副校長の配置ポストが必要なのかなというふうに思って見ていたわけですけども、場合によっては４人になるかもしれないという話なので。","respondent":"和氣小中一貫教育担当課長、市川教育次長","answer":"校長先生も制度的には中学校校長会、小学校校長会もありますし、両方かかわらなきゃいけないという問題もございまして、非常に補佐する部分がほかの学校に比べて多いというところで。今の３人の数が妥当か妥当でないか、これはしばらくまだ検証の余地があるかと思います。","voiceIndex":61,"id":"exchange-016"},{"speaker":"市川委員","kind":"質問","question":"幼稚園のことでちょっと聞きたいんですけど、先ほどの説明の中で副園長が自園昇任ということで１名という説明があったんですが、この自園昇任というのは何なのかということと、それから副園長がいない園という園があるんですけれども、この辺はどうしてこういうふうになるのかお伺いします。","respondent":"河野指導課長","answer":"ただ、今後教員の中で副園長として合格した者が出てくれば、現在あいている副園長を幼稚園のほうにも逐次副園長を配置していくという予定はあります。","voiceIndex":64,"id":"exchange-017"}]},{"id":"topic-03","title":"品川区立学校の管理運営に関する規則の一部改正","agenda":"品川区立学校の管理運営に関する規則の一部改正","exchanges":[{"speaker":"山内委員","kind":"質問・要望","question":"それからあと三つ目なんですけれども、(3)の1)の学校評価、これは先ほど課長からもご説明がありましたが、外部評価という形で評価をしていただいたものを参考にしていくということなんですけれども、外部評価のことに関してになってしまうんですが、基本的にこの外部評価委員というのは、地元の方が中心になって外部評価をしているということなんですけれども、そうすると。","respondent":"河野指導課長","answer":"ですから、学校によってこういうものが評価されて、同じものがほかの学校では評価されないというケースも当然出てくることは予想されますが、それにあえてプラスするものということで、平成１８年度から専門外部評価を入れて。","voiceIndex":71,"id":"exchange-018"},{"speaker":"西本委員","kind":"質問","question":"あえて品川区でとっている副校長、教頭を置かないと、それから仮に副校長と教頭を設置した場合に、ここの説明の中で、どこがどういうふうに違うのかなというところがよくわからないので、仕事の権限の差があるのであれば、現在品川区は副校長が教頭という立場にもなっているという認識でよいのかというところをお伺いします。","respondent":"河野指導課長","answer":"要するに副校長の権限で職務をすることができる部分が新たに設けられたということです。簡単に言えばそういうことです。","voiceIndex":73,"id":"exchange-019"},{"speaker":"西本委員","kind":"意見","question":"教頭と副校長との職務、要は副校長というのは、教頭の上にある権限を持たせた職務ができましたということですよね。じゃあ、今まで教頭先生が持っていた職務なんですけど、それは全部それもひっくるめて副校長という言い方をするのか、それとも主幹教諭のほうに移動するものなのか。","respondent":"河野指導課長","answer":"東京都の考え方というのは、現在従来の教頭が行っていた校務を整理するという部分をすべてではないんですが、副校長の職務の中に一応含まれるという解釈をしています。それから、一部は主幹教諭のほうにおろす。","voiceIndex":75,"id":"exchange-020"},{"speaker":"西本委員","kind":"質問","question":"品川区の考え方としては、教頭を置かないというのはどういう考えで教頭を置かない状況にしているのか教えてください。","respondent":"河野指導課長","answer":"品川区の考えで教頭を置かないのではなくて、品川区の考えで教頭も置ける余地を残しておきたいので、管理運営規則の中に副校長という職務を加え、教頭という項目を残したです。","voiceIndex":77,"id":"exchange-021"},{"speaker":"西本委員","kind":"意見","question":"整理すると、東京都の考え方としては、副校長というところであって、教頭の籍は要らないよという考えで、ただ品川区においては、この規則を残しておいたというのは、いずれはそこのところにも必要に応じてという柔軟性を持たせた上で、今の状況は区費なんでしょうけれども、区費を出せれば教頭の設置もあるという考えですね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":79,"id":"exchange-022"},{"speaker":"南委員","kind":"質問・要望","question":"ちょっと１年もたって、何で今さらこういうことになっているのかなと、ちょっとその手続、そのあたりをちょっとわからないので教えていただきたいのと、あともう一つ、今の委員の関連なんですけど、品川区としては区費だから、それだけの費用を出してまでというところで職は置いているけれども、教頭職は置かないということなんですけど、法律が変わって国が副校長を置くことができるというふうになった。","respondent":"河野指導課長","answer":"副校長ならば、もうちょっと高い給与が支払われるべきなのに、教頭のままだとその給与はもらえないという、そういう不合理が出てまいりますので、そのあたりの整合性をきちんととって。","voiceIndex":80,"id":"exchange-023"},{"speaker":"南委員","kind":"質問・要望","question":"違わないんですか。私は今の説明を聞いて違うというふうに思ったんですけど、その辺のことをもう一回じゃあ説明していただきたいのと、それから、違うのであれば、一定程度品川区の教育委員会としてはこれをどういうふうに整理をしていくのかというのがちょっとわからないんですけど。","respondent":"河野指導課長","answer":"認められたわけですから、今までかぶさっていたものが取り払うことができたという意味では、今までの副校長と今回の副校長というのは違います。ただ、じゃあどこが違うのかというと、本当にそこの部分だけで、やっていた中身については全く変わらないというのが実情です。","voiceIndex":82,"id":"exchange-024"},{"speaker":"南委員","kind":"確認","question":"確認なんですけども、法律的に法改正がされることによってはっきりしてきた副校長の位置、仕事の中身、それは品川区の教育委員会としてはこの法改正によってそういうふうになったと、法律的にもはっきりしたと、こういうことになるということなんですか。","respondent":"河野指導課長","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-025"},{"speaker":"南委員","kind":"質問","question":"じゃあ、ちょっと評価については今ここでどうこうと私も持ち合わせる材料がないのであれですけど、なかなかちょっと相当うちの会派としてはこれについてはもう少し勉強もし、関係者の声も聞き、整理をしていかなくちゃいけないなということと、国のやろうとしている中身そのものが今度具体的に品川区の教育行政の中に見えてきたということなわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-026"},{"speaker":"金野委員","kind":"質問","question":"１点だけ、すみません教えてください。今教頭という考え方が東京都では考えないということで、だけど品川区としては残して置くということ。したがって、では、この先、この小学校、中学校の中で、教頭という位置を将来的には考えていこうというところは中にあるんでしょうか。","respondent":"河野指導課長","answer":"今すぐにということではございませんが、可能性としては十分あるというふうに認識しております。","voiceIndex":87,"id":"exchange-027"},{"speaker":"南委員","kind":"質問","question":"今の副校長先生の法改正によってはっきりしてきたそこの内容というのは、当然現場の校長会を通じてとか、あるいは副校長会とか何とかあるのかあれですけど、そういう組織を通じて伝達をし、整備をしていくということは当然やられるわけですよね。これから４月なり５月の早々の時期にやっていくということでいいんですか。","respondent":"河野指導課長","answer":"そのとおりです。","voiceIndex":89,"id":"exchange-028"},{"speaker":"西本委員","kind":"確認","question":"答えがあったのかもしれないんですが、確認で給与のほうは上がるという形なんですか。給与の体系というのか、今までそういう法的なところで、それがはっきりしたことによって、副校長としての報酬というのは上がるという形で理解していいんでしょうか。","respondent":"河野指導課長","answer":"東京都のほうについては、新たな給与表を検討するというふうに聞いております。","voiceIndex":91,"id":"exchange-029"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"西本委員","kind":"質問","question":"このクリアファイルですが、どのくらいつくられて、これはもちろん無料配布になると思うんですけど、小学生にはそのまま配るという形になるんでしょうが、地域センター等々に何個か置いて、自由に持っていってもらうという形なんでしょうか。","respondent":"堀越生涯学習課長","answer":"そのほか、配布をしてお持ちいただくということも考えておりますし、地域センターの場合には大人の方を中心に、どうぞ子どもを守ってくださいというような意味を込めて、また、まもるっち等とあわせてＰＲという形で。","voiceIndex":97,"id":"exchange-030"},{"speaker":"南委員","kind":"質問・要望","question":"それと３点目は、品川区にはたぶんないんだろうと思うんですけども、よく全国の学力調査をした部分では、いわゆる業者が新しい教材の勧誘をしたとかということもあって、名簿が流れているんじゃないか。当然採点するわけですから、そこではわかってくるんですけども、そういうことも問題視を最近はされてきていますけども、その辺についてはどうなのか、この三つだけ伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":100,"id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4630#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":26475,"voices":104}},{"id":"h20-20080416-5","meetingId":"h20-cm04","date":"2008年4月16日","dateIso":"2008-04-16","committee":"総務委員会","time":"午後１時０３分～午後３時００分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を42件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"武内副委員長","kind":"質問・要望","question":"本日は、お手元に配付の予定表のとおり、幹部職員の異動について、および報告事項等を予定しております。林委員長より、本日欠席との連絡をいただいておりますので、ご了承を願います。なお、お手元に平成２０年陳情第１号の写しを配付しております。これは議長より参考送付を受けたものですので、後ほど各自ごらんいただきたいと思います。なお、本日、１名の傍聴申請がありますので、ご案内をいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":1,"id":"exchange-001"},{"speaker":"武内副委員長","kind":"意見","question":"２の報告事項に移らせていただきます。予定表の２の報告事項を聴取いたします。本件について、理事者の説明をお願いいたします。","respondent":"福島長期計画担当課長","answer":"後ほど報告します。今後のスケジュールですが、４月から９月までに素案について検討を重ねまして、パブリックコメントを実施した後、今年中には素案をいただきたいというふうに考えております。資料ですが、おつけしました資料1)をまずごらんいただければと思います。","voiceIndex":18,"id":"exchange-002"},{"speaker":"菊地委員","kind":"意見","question":"タウンミーティングのところをお聞かせ願いたいんですけれども、これを見ますと、７月に２回ということで、どのような規模で考えておられるのかということと、それから、この３回という設定は一体どこから出てきたものなのか、そこの考え方をお聞かせいただければ。","respondent":"中川原広報広聴課長","answer":"昨年度は各地域に出て意見を収集しましたので、今回は基本計画のまちづくりをメインにということで、きゅりあん、荏原文化センター、南大井文化センターのイベントホールを会場としまして、６月２８日、５月１１日号の広報で周知しますけれども、７月２日。","voiceIndex":21,"id":"exchange-003"},{"speaker":"菊地委員","kind":"質問","question":"それぞれきゅりあんや荏原文化センター、通常、タウンミーティングだと、考え方として小規模であったりとかありますけれども、使う会場がちょっとよくわからなかったんですけれども、人数的にはどの程度をお考えですか。","respondent":"中川原広報広聴課長","answer":"タウンミーティングは小規模、中規模あると思うんですが、やはりやりとり、区長と皆さんのやりとりを中心としたものをタウンミーティングというんですが、今回、テーマが基本構想とか、これからのまちづくりということで、ちょっと趣向を工夫しておりまして。","voiceIndex":23,"id":"exchange-004"},{"speaker":"菊地委員","kind":"質問","question":"広報関係までご説明いただいて、正確に募集人員までは現状では決めていないということなんでしょうか。それとあわせてなんですけれども、パブリックコメント、これも従来型の１カ月間の広報で知らせてという形になるのかと思いますけれども、前回、基本構想のときに１００件ちょっとぐらいあったというお話なんですけれども、これはさらに高めるような工夫というのは何かあるんですか。この辺もあわせて。","respondent":"中川原広報広聴課長、福島長期計画担当課長","answer":"タウンミーティングですが、会場の許容量もあるのですが、先ほど言った意見交換に適当といいますか、どういった人数がいいかというのは、今後、検討して考えていきたいと思っています。ただ、広報等については、何かほかに方法があれば検討していきたいとは思いますけれども、今、想定していますのは、前回同様で考えております。","voiceIndex":25,"id":"exchange-005"},{"speaker":"菊地委員","kind":"意見","question":"３回と限定して最大規模５００人までなんていうお話も今ありましたけれども、やっぱりその辺の基本的な考え方を設定した上で、今回、タウンミーティング、３回だったら３回という決め方で考えるべきものではないのかなというふうに思うんですけれども、もう１つその辺をお聞かせ願いたいと思います。","respondent":"中川原広報広聴課長","answer":"小規模だからいい意見交換かできるということにはならないということで、時期とか、テーマとか、そういったものをよく考えまして、今回はこれでやってみようということで予定しているものです。","voiceIndex":28,"id":"exchange-006"},{"speaker":"伊藤委員","kind":"質問","question":"今のことに関連するんですけれども、タウンミーティングのことはわかりました。つまり、その日に行って冊子を見て意見を言うことももちろんできるけれども、やっぱりこういう構想があるのでということをまとめたものをつくる、それをタウンミーティングに結びつけて、より具体的な意見としてどうですかということが１つ。","respondent":"福島長期計画担当課長","answer":"そこでまたホームページ等でも基本構想を手に入れるようにしていますし、基本構想パンフレットを１万５,０００部、本体を３,０００部お配りしますので、そういう形で施設等で事前に手にとっていただけるのではないかというふうに考えておりますので。","voiceIndex":30,"id":"exchange-007"},{"speaker":"伊藤委員","kind":"質問・要望","question":"それからあともう１つ、私の質問の仕方が悪かったので、昼間区民の世論調査の中身ではなくて、ここで出た結果をどういうふうに策定委員会につなげていくんですか、そちらが非常に重要だと思うんです。ですから、策定委員会のスケジュールが４月から９月までの間になっていますよね。基本構想について検討。","respondent":"福島長期計画担当課長","answer":"続きまして、結果を反映ですが、当然ながら策定委員会にその結果が反映されて、策定委員会のほうで十分議論いただく、そのための調査でもありますので、５月、６月に実施し、そこをまとめたものを策定委員会のほうにお出しし、そこで十分議論いただく予定です。","voiceIndex":32,"id":"exchange-008"},{"speaker":"土井委員","kind":"質問・要望","question":"今のタウンミーティングが６月と７月に行われます。パンフレット、だから、そこには、もしご興味があったらパンフレットがありますよと、こういうところにありますよというのがぜひ書いてあって、そこに取りに行けるようにしていただきたいと思いますので、そこら辺の発行されるタイミングがどうなっていくのかということ。今、その冊子、パンフレット、広報等について、日程的なものを含めてもう一度。","respondent":"福島長期計画担当課長","answer":"５月になりましてからタウンミーティングの参加者募集の広報記事を載せる予定です。そこでも、今、基本構想ができたので、施設に置いてありますので、皆さん、お手にとってお読みくださいというような形でご案内する予定です。","voiceIndex":34,"id":"exchange-009"},{"speaker":"土井委員","kind":"質問","question":"まさしくどこまで基本構想についてやっているかさえ周知がどこまで行っているかなかなかわからないわけですから、そこから区民の皆様には入っていく可能性もあるわけです。そういう意味も含めて、このパンフレット等が十分に活用されることを期待をしておりますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-010"},{"speaker":"武内副委員長","kind":"質問","question":"ほかにご質疑ありますでしょうか。よろしいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-011"},{"speaker":"菊地委員","kind":"意見","question":"それともう１つ、個別の問題でちょっとわかるのかどうかわからないんでけれども、介護保険の担当課長を今度組織改正でなくすという状況なんですね。要は、介護保険は常に中身が動いていきますから、これをなくしてしまうというのはどういう考え方に基づくのか、これはちょっと個別の問題なので、わかればお願いしたいと思います。","respondent":"久保田行財政改革担当課長","answer":"１点目の各委員会への報告ということで、昨年、こちら総務委員会のほうでそういうご意見をいただきまして、その際に担当の課長のほうからご説明させていただいたんですが、総務委員会では総合的な組織改正のご説明をさせていただきまして、６月の事務事業の概要説明の際に。","voiceIndex":42,"id":"exchange-012"},{"speaker":"菊地委員","kind":"意見","question":"介護保険制度については次の見直しがまたありますよね。そのときには、引き続き高齢福祉課長がこれをすべて担当しますよという、そういう流れで考えていいのか、それともまた新たに介護保険の担当課長なり何なりをつくっていくことになるのか、ちょっとその辺をもうひとつ。","respondent":"久保田行財政改革担当課長","answer":"将来にわたって介護保険担当課長をどうするかというご質問なんですけれども、そのときの介護保険を取り巻く状況に応じて個別的に検討していきたいということで、今は介護保険担当課長の組織の簡素化を図ったという判断をさせていただきまして。","voiceIndex":46,"id":"exchange-013"},{"speaker":"原委員","kind":"質問・要望","question":"それからあと、その下の用地担当課長職というのが新しくなっているんですけれども、これは以前から聞いていた専門的な形でという、それの内容だと思うのですけれども、その辺で、総務委員会なので詳しく掘り下げてお聞きする気はありませんけれども、土地開発公社との関連なんかがちょっと出てくるのか来ないのか、その辺の３点をお聞かせいただければと思います。","respondent":"久保田行財政改革担当課長","answer":"１点目の境界確定係についてですが、こちらのほうの中身につきましては、今回特に改正はしていませんので、名称の変更だけというふうになっております。","voiceIndex":48,"id":"exchange-014"},{"speaker":"原委員","kind":"質問","question":"そうすると、地域支援担当、町場だけではなくて、今度は都のほうとか、それの関係の調整も入ってくるという解釈でよろしいのでしょうか。調整役というのは。地域支援担当。","respondent":"久保田行財政改革担当課長","answer":"ちょっと具体的なところ、都とどうかということまでは聞いていませんけれども、区の中でのいろいろな課、複数の課にまたがるときに、どこが責任をもって円滑に進めていくかという意味で、役割を担っているです。","voiceIndex":50,"id":"exchange-015"},{"speaker":"浅野委員","kind":"質問","question":"例えば、仕事のローテーションですとか、人材登用ですとか、将来の区の構想とか、いろいろなことを考えられながらこちらも組織編制、また人事異動も考えられたと思うんですけれども、ニワトリが先か、卵が先かと言ったら怒られてしまうんですけれども、まず区の仕事としまして、まずは組織改正、変な意味ではないんですけれども、組織改正がありきで、そこにやはり適正な人材配置とか、また人材育成。","respondent":"久保田行財政改革担当課長","answer":"今のご質問ですけれども、組織改正につきましては、組織で必要な仕事、区民から区民ニーズの高い仕事とか、経常の仕事等がありますけれども、仕事のほうをこういう組織でこういう仕事をやっていこうというところからこういう組織が必要だということで見直しを図っていますので。","voiceIndex":52,"id":"exchange-016"},{"speaker":"浅野委員","kind":"質問","question":"そういう意味では、その組織に対応する人材の確保ということが、先ほども質問ありました用地の件とか、そういうところで委嘱をするというのでしょうか、新しい人材が必要なところは補充というかそういう形にして、今、ある意味では過不足なくこれでスタートを切ることができたという考えでよろしいでしょうか。","respondent":"榎本人事課長","answer":"そういった意味で、昨年の第４回定例会に一般職の職員の採用の条例の制定をしましたけれども、多様な人材を集められるようなところをそれぞれ取り入れながら、今後も人材の育成確保に努めていきたいというふうに考えています。","voiceIndex":54,"id":"exchange-017"},{"speaker":"伊藤委員","kind":"確認","question":"済みません、確認だけなんですけれども、先ほど話にあったまちづくり事業部の用地担当課長、新設です、これはつまり、先ほど答弁があったような条例を視野に入れながら対処していくのでしょうかということが１つ。どこが集約していくのでしょうかという単純な疑問です。その２つを教えてください。","respondent":"榎本人事課長","answer":"専門的な人材というのは、一般的な区の採用競争試験ではなかなか確保できない。","voiceIndex":56,"id":"exchange-018"},{"speaker":"武内副委員長","kind":"質問","question":"よろしいですか。ほかにありますでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-019"},{"speaker":"菊地委員","kind":"質問・要望","question":"今の説明ですと、１６６億円、これまでと同額を今後はそれぞれの都道府県市区町村で集めるということなんですが、そうすると、国が出資していた同額の１６６億円というのは、これでストップをするというか、機構が変わるわけですから当然そうなるのかもしれないですけれども、要は、地方分権を踏まえてというよりも、国がお金を出さなくなったというだけの考え方なんですか。","respondent":"日下部企画財政課長","answer":"これはどういうことかといいますと、国がお金を出さなくなったというようなご指摘でありますけれども、そうではなくて、さっきご説明させていただきましたように、地方が単独ではできない、共同で資金の調達をする機関が、公庫が廃止になった。","voiceIndex":63,"id":"exchange-020"},{"speaker":"菊地委員","kind":"質問・要望","question":"ただ、そもそもの公営企業の金融公庫のところでも、政令ですか、ここでは１５の事業に対してという話を聞くところですけれども、そもそも１８事業と設定されていたような気がするんです。法律ではここでは、今、１５事業と書いてありますけれども、法律で定められているものは５事業ぐらいしか出ていなかったんですけれども、それは何かの関係かちょっと教えていただきたいんです。","respondent":"日下部企画財政課長","answer":"これが政令の中で後追いで整理をされまして、政令では１０事業が指定をされる、こういう形で１５事業ということで対象が決められた、そういう経過です。","voiceIndex":65,"id":"exchange-021"},{"speaker":"菊地委員","kind":"意見","question":"そうすると、おっしゃったとおり、区民生活、住民にとって極めて重要な事業がここの中で貸付されるということなんですけれども、その１５の事業というのが、ここから地方の財政状況を考えていくと、１５の事業を維持していくというのは非常に大変な状況になるのかなというような気がするんですけれども、この事業そのものが縮小されていくという懸念というのはあるのかどうか、ちょっとそこも。","respondent":"日下部企画財政課長","answer":"つまり、公庫が廃止になった、じゃあ、廃止になっただけでは、これはやっぱりそういう非常に密接な住民に通じる事業の継続なり運営というのは非常に厳しくなります。","voiceIndex":67,"id":"exchange-022"},{"speaker":"土井委員","kind":"質問・要望","question":"国には確かに６団体が、届け出ているのは６団体、地方自治法に届け出ると書いてあるんですから、だから、届け出ているのは６団体なんだろうけれども、その６団体が何たるやということで言ったら、確かに市長会であり、市議会であり、議長会であるということになっているんだけれども、その下にはどうなっているのかさっぱり、会は届け出たんだからそのとおりなんだけれども。","respondent":"日下部企画財政課長","answer":"ただ、全国の自治体が一同に介してという機会がなかなかないということもありますし、また、どういう形で意見を集約するか、これは今後の課題だというふうに考えておりますけれども、６団体で全体の割り振りをして、それを踏まえて。","voiceIndex":69,"id":"exchange-023"},{"speaker":"土井委員","kind":"質問","question":"今もお話があったんですけれども、確かに６団体の全国組織というものが、政府登録観光旅館みたいなところに登録してあるんです。国のほうに。そこはいいんです、そのとおりだと仮にしましょう。思っていませんけれども、そういう意識を持ってそれらのものにずっと対処していかない限り、その流れは何万年たっても直らない、化石になってしまうと思うんですけれども、その辺はどうでしょうか。","respondent":"日下部企画財政課長","answer":"今回のこの成立も含めまして、今回、１つの改革の流れの中でこういう形で新機構を設立していくことになったわけですが、国のほうとしても、今回はっきりと、この改革に当たっては、国が人、金、物。","voiceIndex":71,"id":"exchange-024"},{"speaker":"土井委員","kind":"意見","question":"地方６団体という形の中で、今までもさまざまなものに政府やほかに対して意見を申し上げるという事例があった。今回もこの設立には諸手を挙げて賛成の意見も出されている。きょうのところは終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":73,"id":"exchange-025"},{"speaker":"伊藤委員","kind":"質問・要望","question":"何点かお伺いといいましょうか、いろいろあるんですけれども、６ページのところの文章ですけれども、非常に気になっているのが、この中に区が入っていないんですね。わかりやすいところですけれども、基礎自治体であるとなっているんですけれども、区が入っていないのに区が支出することに決めたということですから、区長会がこのことを了承したんですかということが１つ。","respondent":"日下部企画財政課長","answer":"それから３点目の、この資金としての活用でありますけれども、これは全体の資金計画の中で、さっきも申し上げました、かつてこれを活用させていただいた経緯もありますし、今後も全体の資金計画の中で検討すべきものというふうに考えております。","voiceIndex":74,"id":"exchange-026"},{"speaker":"伊藤委員","kind":"質問・要望","question":"市の中に入っていると理解すべきだ、もうそれはそのとおり理解する。だけれども、出資については２３区も負担しているのは事実ですよね。ところが、７ページはそうじゃない。ですから、経営審議委員会はそれは金融専門で入るでしょう。それから、今までの公庫の情報、既に公庫の情報がここにあるわけですから、それをどう引きついでいくんですかということを、わかればお答えいただければと思います。","respondent":"日下部企画財政課長","answer":"経営審議委員会のメンバーですが、これは確認した段階では、まだこれは設立の段階で任命されるということでありますので、これはまた追って確認をしていきたいと思いますが、今、委員のご指摘の点はもっともでもありますし、そういう意味では、地方自治の現状。","voiceIndex":76,"id":"exchange-027"},{"speaker":"伊藤委員","kind":"質問","question":"経営審議委員会がどういうメンバーで構成されていくか、やっぱり地方自治に顔を向けた人がやるのと同時に、個別のことですからあれですけれども、どこかの銀行のように追加資金をやるような、そういうことがあってはいけないわけですから、そういう意味でも、この経営審議委員会の人選については、ぜひ各議会の意向を聞いて進めていってくださいということをお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-028"},{"speaker":"菊地委員","kind":"質問","question":"済みません、１つだけさっきの、関連というか、地方自治体で出資したくないというのは別として、できないぐらいの財政状況というのは財政再建団体に近いぐらいの団体の中で、もちろん品川よりも、こういうお金ではもちろんないにしろ、地方債を発行していても支払えみたいな、こういう感じで出資の割り当てになっているのか、ちょっとそこだけ教えていただけますか。","respondent":"日下部企画財政課長","answer":"ちょっと全国の各自治体の状況はなかなか把握も難しいところではありますけれども、確かに厳しいところもあろうかと思います。","voiceIndex":79,"id":"exchange-029"},{"speaker":"菊地委員","kind":"意見","question":"自治体そのものもそうでしょうし、その機構そのものも財政悪化していくという流れがあるのに、さっきの話ではないですけれども、段階的に縮減を図るみたいな、事業そのものを縮減を図っていく流れというのは、そういう状況の中で積み上げられていくのかなというような、これはちょっと聞いている意見をどんどん答えられる話ではないかと思うんですけれども、いずれにしろ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":81,"id":"exchange-030"},{"speaker":"武内副委員長","kind":"質問","question":"ほかに。よろしいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-031"},{"speaker":"菊地委員","kind":"意見","question":"一方はプールの解体とかがありますけれども、もちろんこれは契約が決まって契約をする際に、解体工事とかにかかわるときに、騒音の問題だとか、ほこりの問題まで多分契約の中にはどうこうとうたうことはないのかもしれませんけれども、当然工事の中ではまちづくり事業部との事前打ち合わせだとか、そういう流れがあるんでしょうけれども、よく行政が出すような工事についても、解体の作業のほこりだとか。","respondent":"宍戸施設担当課長","answer":"その中でいろいろな注意事項等をずっと記載してございまして、解体工事の場合には、散水ですとか、騒音、振動、法令内におさめるようにといったようなことのほか、注意事項について仕様書の中でお約束していただくようなことになっています。","voiceIndex":87,"id":"exchange-032"},{"speaker":"菊地委員","kind":"質問・要望","question":"だから、基準内でおさめるという中身ではなくて、どれだけきっちりした防音体制なり何なりの中でその工事が進められるかという、そういう中身をぜひ業者のところと区のほうでしっかりとした打ち合わせをして、その上でその工事にかかるという体制をもっと強化をしていただきたいなというのはお願いなんです。それだけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-033"},{"speaker":"武内副委員長","kind":"質問","question":"ほかにございませんでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":90,"id":"exchange-034"},{"speaker":"原委員","kind":"確認","question":"確認だけです。１点。この１０ページのところで、第２期解体別途となっていますから、今回のことに関しては、左側の校舎というだけの意味ですね。","respondent":"阿部経理課長","answer":"そのとおりです。","voiceIndex":95,"id":"exchange-035"},{"speaker":"土井委員","kind":"質問","question":"後々の話なんですけれども、今お伺いしたところ、第２期解体である体育館は、現場工事事務所としてお使いいただくということになるんですが、そうしたときに、一番最後の解体、本当の解体のときに、お金がかかるわけですし、そこら辺、使っている方で壊していただけるのかなというような思いがあったものでちょっと聞いてみたんです。どうお考えでしょうか。安く解体してもらうとか。","respondent":"阿部経理課長","answer":"今回の、じゃあ、第２期の解体のことですけれども、それの費用につきましては、新築本体工事のほうに含めて考えるということになります。","voiceIndex":97,"id":"exchange-036"},{"speaker":"武内副委員長","kind":"質問","question":"ほかに。よろしいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":99,"id":"exchange-037"},{"speaker":"武内副委員長","kind":"質問","question":"本件については、よろしいですね。ほかにその他で何かありますでしょうか。","respondent":"阿部経理課長","answer":"掲載の内容といたしましては、工事のスケジュールや採用する工法、さらには通常の業務を行いつつ工事を進めてまいりますので、本庁舎の２階の出入り口や、同じく本庁舎２階の駐車場が使えなくなること、駐輪場所の一部変更があることなどです。","voiceIndex":103,"id":"exchange-038"},{"speaker":"菊地委員","kind":"質問","question":"今、総合評価でというお話がありましたけれども、総務委員会での視察の中でも聞いてきたと思うんですけれども、第三者のところでの、あれは委員会というんですか、その設置をこれから行う、行われてきた、あるいは法律の変更があるとか、何かその辺をちょっとお聞かせください。","respondent":"阿部経理課長","answer":"ただ、従来は、総合評価方式を入れるかどうかの段階と、その基準をつくる段階、あともう１つは、落札者を決定する段階、その３段階で聞かなければいけないという法律になってございましたけれども、３月に施行令の改正がございまして。","voiceIndex":106,"id":"exchange-039"},{"speaker":"菊地委員","kind":"質問・要望","question":"その基準は、今日、口頭の報告なものですからよくわからないところなんですけれども、基準というのは、例えば委員会に公表して差し支えないと言ったらおかしいけど、何かしていただきたいものだというふうに思います。だから、それだけ巨額の工事ですから、それが実際に総合評価でやるとなれば、その基準が作られ、その基準の中身は一体何なのかというのは、議会の場にぜひ。終わった後なのかな。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-040"},{"speaker":"伊藤委員","kind":"質問・要望","question":"１つ１つやっていくと時間がかかると思いますが、要は、そういうことに対して議会としても意見があるし、それから、それに対して区としては工事をやりながらも、そういうことに対して十分な配慮をしておく必要があるでしょうから、ということについて、やはりどこかで、当該の委員会はどこかわかりませんけれども、まとめて説明していただきたいし、それから工事自体の計画についてではなくて。","respondent":"市岡総務部長","answer":"この工事に伴う、例えばご指摘いただいた庁有車等の今後の調整ですけれども、一度この委員会でも若干のご説明を申し上げましたが、いずれにしても、庁舎を利用しながら、あるいは区民の方に来庁していただきながら、あるいは議会活動も行いながらの工事ですので。","voiceIndex":114,"id":"exchange-041"},{"speaker":"武内副委員長","kind":"質問","question":"ぜひよろしくお願いします。ほかによろしいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":116,"id":"exchange-042"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1780#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":39070,"voices":117}},{"id":"h20-20080417-14","meetingId":"h20-cm04","date":"2008年4月17日","dateIso":"2008-04-17","committee":"行財政改革特別委員会","time":"午後１時０２分～午後３時２３分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を66件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の財政（歳入）に関すること","agenda":"の財政（歳入）に関すること","exchanges":[{"speaker":"山内委員","kind":"質問","question":"今、ここで考えられる施設、例えばネーミングライツをすることによって企業にも利益をもたらす、そして、品川区にも歳入という形で利益をもらたすような箇所は、行政のほうで何カ所ぐらいあるのかと、もちろん具体的な数字は出てこないかと思うんですけれども、もし教えていただければと思うんです。","respondent":"日下部企画財政課長","answer":"実際にどうかというのは別にいたしまして、今、委員のご質問にありますような施設ということで、さっき、ご説明申し上げましたが、施設の来場者へのＰＲとか、メディアへの露出度とか、そういった点を勘案いたしますと、あくまでも私の個人的な考え方ですが。","voiceIndex":14,"id":"exchange-001"},{"speaker":"阿部委員","kind":"提案","question":"ちょっと似たような質問になるんですが、今のご説明を伺いながら、三つぐらい種類があるのかなと思って聞いていました。一つは、スタジアム等々、メディア露出が非常に多くて、高額な契約金が取れるもの、それから、三つ目を先に言うと、地域密着型の停留所みたいなもの、その中間ぐらいで、ホール、文化施設などがあるかなと考えておりました。以上の三つの点について、それぞれお考えを伺えればと思います。","respondent":"日下部企画財政課長","answer":"今後、施設として整備していくものの可能性ということでありますけれども、これからどういうものを整備していくのかということで、今現在、予定しているものは、例えばいろいろな大型の施設の整備は、大体ひと区切りついている面もありますし。","voiceIndex":16,"id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"初めに、命名権ということなんですけれども、２００３年の東京スタジアムの「味の素スタジアム」が一番最初であったということなんですけれども、命名権というのが活用できるようになった根拠というか、根拠法で何か変わったことがあったのかどうか、その辺をお聞きしたい。この辺で、導入に当たって、どういう経過を経てやってきたのか、その辺でわかるところがあったら、教えてください。","respondent":"日下部企画財政課長","answer":"実際の収入というのは、公的な施設ということになりますと、受益者負担とは言いつつも、どうしてもやはり使用料収入というのはそれほど多くは見込めないというところがありますので、その点の埋め合わせも含めて、命名権を活用するという流れです。","voiceIndex":18,"id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"導入をめぐる課題というところで、４点挙がっていて、かなりいろいろ問題点はあるかなと思っているんです。今、ちょっとやりとりがありましたけれども、可能性というところでは、ある部分もあるんだと思うんですが、区が現在、命名権の活用に対して、どの程度論議がされているのか。もしその辺がわかったら、教えていただきたいと思います。","respondent":"日下部企画財政課長","answer":"公式に検討を進めているというような経過は、特にございません。","voiceIndex":20,"id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その研究の中に、ぜひ区民の広い意見を取り入れていっていただきたいと思います。区のところでは渋谷区だけだったので、ちょっと問い合わせなんかもしたんですけれども、じっくりとした検討のもとではないような受け取り方を私はしたんです。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-005"},{"speaker":"中塚委員","kind":"質問","question":"幾つか伺いたいんですけれども、導入をめぐる課題の中で、(2)で、スポンサー企業としての適格性のところで、ふさわしいかどうかが問われるんだと。さっき、個人的な意見という言い方をしていたので、そんなに強く聞く気はないんですけれども、いや、きゅりあんはみんなで決めたのに、何でって思ってしまったので、ちょっと答えられる範囲で結構ですので、教えていただけますか。","respondent":"日下部企画財政課長","answer":"最初にきゅりあんのお話ですが、これはあくまで、山内委員のほうから、可能性があるとしたらこれはどういうものが考えられるかということで、あくまで仮定の話としてお答えしたものでありまして、私どもとして、今、きゅりあんの名前をどうしよう、こうしようとか。","voiceIndex":23,"id":"exchange-006"},{"speaker":"高橋委員","kind":"質問","question":"ちょっとお尋ねしたいのは、例えば、渋谷区で年間８,０００万円というのが入って、５年で４億円ですけれども、そういうのは歳入のどこに入って、税金等というのは、どこにどう支払うのか、ちょっと教えてください。","respondent":"日下部企画財政課長","answer":"一般的には、例えば、諸収入の中で広告料収入というような位置付けで収入をしているケースも多いようです。その辺は、最終的には、各自治体によってまた多少違う面があると承知をしております。","voiceIndex":25,"id":"exchange-007"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"ちょうど二、三日前の読売新聞の夕刊に出ていたんですよね。企業の問題、企業の流れがわからないところで大変な話だなと思うので、ちょっと難しいとは思います。そういう点で、あまり公共施設的なという難しさを考えないで、野球施設みたいなものは、管理費のために、例えば電気代とか、利用者が安くできるためにそういうネーミングライツを使ってみるとか、何かその辺、どうでしょうか。","respondent":"日下部企画財政課長","answer":"そういう形で協賛をしてくれるところがあれば、多少なりとも、そういう維持管理の経費に充てられるとか、そういうようなことも考えられますので、その点も、命名権を考えるに当たっての一つの検討課題ではないかと、このように認識をしております。","voiceIndex":27,"id":"exchange-008"},{"speaker":"石田（慎）委員","kind":"質問","question":"停留所では、バス停の柱とか、屋根とかの新調は企業がしたとなっているんですが、ほかは全部、例えばスタジアム等の看板等の設置というのは、契約金内で各自治体等が工事を行うのか。それとも、その工事費はまた別に徴収をするのかということを、ちょっと教えていただければと思います。","respondent":"日下部企画財政課長","answer":"すべてを確認したわけではないんですけれども、やはり大体、そういう看板の付け替えとかに、相当お金がかかるんです。これは契約の中でも別立てで負担をいただくというようなケースが、結構多いようです。","voiceIndex":29,"id":"exchange-009"},{"speaker":"高橋委員","kind":"質問","question":"ちょっと議論の場が違うのかなとも思ったんですが、いかがでしょうか。","respondent":"日下部企画財政課長","answer":"区も、ご案内のように、広報紙だけではなくて、ホームページとか、とにかくいろいろ幅広い形で収入を確保するというような努力は、今後とも続けていきたいと考えておりますので、今、ご指摘があったような点も、今後の一つの課題ではないかと認識をしております。","voiceIndex":31,"id":"exchange-010"}]},{"id":"topic-02","title":"の特定事件調査のまとめ","agenda":"の特定事件調査のまとめ","exchanges":[{"speaker":"山内委員","kind":"質問","question":"検討課題の３番なんですが、昨日の総務委員会の中で、今後の耐震工事に当たっての、いわゆる契約のあり方というものが、総合評価方式を導入されるということでお話があったということを伺ったんですけれども、その経緯といたしましては、法改正があって、学識経験者を３回から１回にすると、いわゆる簡素化をされたということで、総合評価方式を導入するという話があったんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-011"},{"speaker":"山内委員","kind":"質問","question":"そうすると、今後は、総合評価方式も含めて検討課題というか、そういう形で、こういう委員会を通していろいろと勉強していくという形になっていくということでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-012"},{"speaker":"山内委員","kind":"意見","question":"これはあくまでも案なので、やはりそれは入れていくべきだと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":41,"id":"exchange-013"},{"speaker":"中塚委員","kind":"質問","question":"委員会のまとめなので、やっぱり１年間の議論の中で実ってきたものという言い方ですか、それはやっぱりまとめに反映させるべきだと思うんです。山内委員の意識は、意識としておっしゃるのは別として、今はまとめの話なので、今までの議論のその仕切りの中で進めるべきではないのかなと、私は思ったので、一言。","respondent":"鈴木（ひ）委員長","answer":"でも、そういうふうに３月末に地方自治法施行令が変わって、急遽、それを試行していくということで、実際に区としてもやっていくということになっていくと、総務委員会の報告でもされたわけですので、そういうふうな変更ということはあり得るかなとは思いますので。","voiceIndex":43,"id":"exchange-014"},{"speaker":"原委員","kind":"意見","question":"私も総務委員会なので、正式にこちらのほうには上がってきていないので、委員長のおっしゃるように、５月ということもわかるんですけれども、ただ、具体的には毎日毎日動いておりますので、これは会派ではなくて、私の意見としては、正副委員長で、このことについてちょっともう少し踏み込んで話していただくといいかなという気がいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":45,"id":"exchange-015"},{"speaker":"中塚委員","kind":"意見","question":"まだ報告もされていない中身を、議論もされていない中で、正副委員長に一任と言われても、どうまとめていいのかと察するんですけれども、それはちょっと、私の意見は違います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":46,"id":"exchange-016"},{"speaker":"原委員","kind":"質問・要望","question":"資料的に出ていないんだったらいいんですけれども、出ていますので、実際には行政というのは動いているんで、特別委員会と常任委員会で違うということでは、やっぱり区民に対してはいち早く敏速に対応していくのが、我々の仕事だと考えておりますので、この辺のところを、だから、入れ込めということではなくて、そういう考えを、ちょっと委員長、副委員長でお話をいただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-017"},{"speaker":"鈴木（ひ）委員長","kind":"意見","question":"正式に、きちんと資料もそろえた上で、その法的なものも含めて、５月に改めてきちんとした形でご報告いただきますけれども、昨日、総務委員会で報告があったということもありますので、わかる範囲でご報告をいただくことは可能だと思うんです。ここの中身に入っていることですので、わかる範囲で、ご報告いただくということにしますか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":48,"id":"exchange-018"},{"speaker":"山内委員","kind":"質問","question":"それは、ぜひそうしてください。もう既に、９月２７日の行財政改革特別委員会でも資料も出ているということなんです。ですから、それをちゃんと踏まえた段階で、私の意見としては、やはり総合評価方式も導入するべきではないかということなので、それはよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-019"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"まとめる部分は、さっき、みんな納得したと思うんですけれども、昨日の説明では、山内委員がおっしゃったのは、総合評価方式に変わったということですよね。山内委員もおっしゃったけれども、今まで、総合評価方式だと、３回専門の学識経験者が入っているのが、そこら辺が変わったとか、その概略部分を教えていただくのがこの委員会ではないかなと思うんですけれども、いかがでしょうか。","respondent":"市岡総務部長","answer":"具体的な中身というよりは、ある意味で、この間の経過を、もう一度ちょっと確認するというご説明になろうかと思いますので、委員会として、そういう答弁をするということをご指示いただければ、担当の課長のほうから、説明させていただきたいと思います。","voiceIndex":51,"id":"exchange-020"},{"speaker":"阿部委員","kind":"質問","question":"ところが、５月１３日には、もうこの検討事項の提言をまとめる文面を固めるのであると、それがこの日程で可能なのかなと。ここから「簡易型」という文字を取ればいいという話では、当然ないですし、簡易型は簡易型で、多分残るのでしょうから、ちょっとそこら辺は、５月１３日に全部できるという日程でのお考えなんでしょうか。これは委員長に伺いたいんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-021"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"総合評価方式をどう判断するかというのは次の委員会になってしまうと思うので、その分は、その委員会で審議した上で、１項目追加するかしないかを、またその場で諮って、１回休憩を取って、こんな文言でどうですかということは、正副委員長で調整した上で、皆さんに提示して、再度、そこで検討してもらうという形しか方法はないと思うんです。","respondent":"鈴木（ひ）委員長","answer":"途中で休憩を取ってまとめるということもあるかもしれないんですけれども、この委員会としては、この提言そのものは、全会一致で、委員会としてまとまったものを行政のほうに提言という形で出していきたいと考えておりますので、そういう形で、総合評価方式のことについては。","voiceIndex":57,"id":"exchange-022"},{"speaker":"阿部委員","kind":"質問","question":"５月に十分な時間が取れれば、それはそれで構わないと思います。ただ、それまでの間に委員会を開いてはいけないものなんでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-023"},{"speaker":"武内委員","kind":"確認","question":"ちょっと確認なんですけれども、品川区が今までやってきた簡易型と、昨日、総務委員会で報告のあった総合評価方式の違い。今まで３回だったのが１回になって、この部分があるか、ないかの違いだけなんですか。それとも、ほかにいっぱいあるんだったら、また説明を受けなければいけないんですけれども、学識経験者に１回だけ意見をいただくと、大きな違いはそこだけなのかどうか、教えてください。","respondent":"阿部経理課長","answer":"ただ、これは委託の簡易型ですので、委託の場合はさまざまなものがありますので、その辺が、工事と委託の基準をつくるときの大きな違いかなと考えています。","voiceIndex":61,"id":"exchange-024"},{"speaker":"武内委員","kind":"質問","question":"そうしますと、工事のほうは入札ですよね。ただ、それに当たっては、非常に客観性を持った透明性、公平性の確保に努めなさいと、あくまでも随意契約ですから。今、お話の出た、総務委員会の方では、入札するわけですから、そういう面では、それはそれとしてどう取り組むかは別としても、３番のほうを検討することによって、こっちのほうがハードルが高いような気がするんです、これを出すことのほうが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":63,"id":"exchange-025"},{"speaker":"鈴木（ひ）委員長","kind":"意見","question":"今、正副委員長でも調整させていただいて、委員長としては、今、武内委員からもご意見がありましたけれども、５月に報告をいただいて、それを受けてまとめに反映をさせていくということで進めていきたいと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":64,"id":"exchange-026"},{"speaker":"阿部委員","kind":"意見","question":"委員長、副委員長のご決定でしたら、それに従います。ただ、新しい総合評価方式がこう変わったということだけではなくて、従来の簡易型との関係や、そのすみ分けですとか、そういったことも議論した上でのまとめということにすべきであると思いますので、そこの論点も、しっかり５月１３日の中では議論できるように、よろしくご配慮いただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":65,"id":"exchange-027"},{"speaker":"中塚委員","kind":"意見","question":"もうまとめの段階なので、具体的に、４の一番最後に、「また、総括シートの内容は議会が指定管理者の実態を把握できるものに改善すること」という形で加えると、僕はもっと言いたいこともあるけれども、総括シートの中身も具体的に落とし込みたいところはあるけれども、そういうことを盛り込んだらどうかなと思いました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":67,"id":"exchange-028"},{"speaker":"原委員","kind":"質問・要望","question":"私個人としましては、開示というか、議会報告を受けることは大賛成だと思います。議会にどこまで報告されるか、これがいろいろな案件上の問題で、企業名が個別に出てきてしまうということは、いいことなのか、悪いことなのか、それが与える影響ですとか、その辺まで加味しなくてはいけませんので、これは慎重に扱っていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-029"},{"speaker":"中塚委員","kind":"質問","question":"ただ、１点指摘すると、企業名という話が出ましたけれども、指定管理者自身は、企業自身は公のものですから、それはやっぱり当然、隠しようがないと言えば、隠しようがない。やっぱり、公の事業を担うわけですから、担っている責任というのはきちんと、受ける側とチェックする側と、もちろん議決をする議会側のそれぞれの責任というのは、やっぱり大事なのかなと、ちょっと意見だけ述べします。","respondent":"福田企画部長","answer":"私どもが指定管理者の実態を把握して、それを議会、あるいは、この委員会に、情報を隠蔽するとか、隠匿するとかということは毛頭考えておらないんですけれども、ただ、どのように報告をするか、これはやはり、私どもの執行機関の裁量ということもありますので、できれば。","voiceIndex":70,"id":"exchange-030"},{"speaker":"原委員","kind":"質問・要望","question":"私どもの仕事というのは、やっぱり監査という意味合いなので、今のご意見は非常にわかりますので、文言的には、当然に行政側から出てくる。ただ、我々は、それを区民にわかりやすく普通の言葉で説明をしていかなくてはいけませんので、そこの形になるようなご協力をいただきたいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-031"},{"speaker":"中塚委員","kind":"質問・要望","question":"その辺の議論は、指定管理者制度そのものの問題点にもなってしまうのかなと思うんです。今のは、その資料をもっと改善していただきたいという話なのかなと。指定管理者制度そのものの議論であれば、私ももっと大いにやりたいとは思いますけれども、それについての意見もありますけれども、私は、そういうふうに感じます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-032"},{"speaker":"原委員","kind":"質問","question":"私も、中塚委員がおっしゃるとおりだと思いますので、ストレートに言いますと、政務調査費を使ってダイレクトに調査をする。ですから、行政のほうから上がってくるものと、我々が行動をして、行政で活動して、いろいろな場所、場面を見て、検証をして、そこに対してのすれ違いがあれば、いろいろな、こういう委員会ででも答弁をされればいいのではないかなと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-033"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"ですから、この総括シートに基づいて、またそれ以外に議会のほうから行政にこういう資料が欲しいとか、それはその可能性はありますけれども、総括シートそのもので、事業者から出た書類に基づいて、総括シートをもっと変えた上で、議会の報告のためにやれというのは、ちょっと流れが違うのではないかなと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-034"},{"speaker":"中塚委員","kind":"意見","question":"ただ、先ほど言ったのは、行政機関のそういうモニタリングだけではなくて、議会への資料だったり、もちろん総括シートの中身だったり、その視点は欠かしてはいけない、この間の行財政改革特別委員会の議論だったのではないかなと思ったので、もう１回言いますと、その検証を行うことの後に、「また総括シートの内容が、議会が指定管理者の実態を把握できるものに改善すること」。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":76,"id":"exchange-035"},{"speaker":"阿部委員","kind":"質問","question":"少し総括シートの話からずれるかもしれませんが、指定管理者の情報は、総括シートが唯一のルートということでなければいけないということでもないのかなと考えています。ちょっときついかもしれませんけれども、業者側の自主性ということを盛り込んでいただけるか、ここには書かないけれども検討は可能か、その辺を、どちらでもいいんですけれども、ご意見を伺えれば。","respondent":"福田企画部長","answer":"私どもも、それを積極的に把握をして、できるだけご議決に耐えられるような資料をつくる、これは原則だろうと考えていますし、そのことを、さらに指定管理者に働きかけてまいりたいと思っています。","voiceIndex":77,"id":"exchange-036"},{"speaker":"武内委員","kind":"意見","question":"私どもも、４番と同じような意見を入れさせていただいて、中塚委員とか、いろいろお話がありましたけれども、１番から４番全部、そういう面では、例えば１番の評価の観点とか、配点とかそういうものも含めて、できる限り、議会が知っていかなければいけない部分があるんですけれども、これはあくまで行政で行っていただくための提言という形になるので、そういう整合性を持たせる意味では。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":79,"id":"exchange-037"},{"speaker":"阿部委員","kind":"質問","question":"国の役所なんかは、この数年でかなり改革が進んで、むしろどこかの省庁では、もう８割ぐらいが、物品購入は入札でやっているんだというような話も、これは不確かですけれども、そんな話を聞きました。それとも、いや、品川区は随意契約中心でやるんだという強い意思があってやっていることなのか、ちょっとその辺をお伺いできればと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":80,"id":"exchange-038"},{"speaker":"阿部委員","kind":"質問","question":"そうですね。議論といっても、法律で定まっていることなので、多分、反対はできないと思うんですけれども、それをあえて書くかどうかという、むしろ判断の問題になるかと思いますが、どうでしょうか。ただ、役所の契約は入札がベースということは、これはもう基本の「き」なので、どうでしょうか。私は、もちろんあえて、やはりこういうことは、原則は書いていくべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-039"},{"speaker":"鈴木（真）副委員長","kind":"意見","question":"今の言葉尻をとらえるわけではないけれども、品川区は随意契約を中心でいう、その言葉をこのまま残してしまっていいのか、どうか、ちょっと非常に疑問に思うんです。経理の立場として、契約の立場として、随意契約中心って、そのままでいいのか。そこら辺、逆にお答えをもらったほうがいいのではないかと思うんです。それは委員長に仕切ってもらいますけれども。","respondent":"阿部経理課長","answer":"委員のお言葉で、随意契約中心ということですけれども、随意契約は限られた場合にできるですので、随意契約を中心にやっているというわけではございません。","voiceIndex":83,"id":"exchange-040"},{"speaker":"武内委員","kind":"意見","question":"今回、簡易型総合評価方式を、品川区が品川区版で取り入れたということは、随意契約の中でもさらに透明性ですとか、そういったものを確保するために、簡易型総合評価方式というものをやっているんですよという中で、それをこの１年かけて、ある程度勉強したわけなので、そういった面では、ここに含まれているという判断で、阿部委員のおっしゃったことは当然なことなんですが、あえて書くかどうかというのは。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":86,"id":"exchange-041"},{"speaker":"阿部委員","kind":"意見","question":"それで、あえて書くかどうかというのは、では、品川区の実態はどうなっているかということと関連すると思うんです。ただ、「記」より下に書くとすると、確かにちょっと上の表現をいじる必要はあるかと思いますが、その辺の文章の組み立てについては、より流れのよいように後でできると思いますので、むしろ入れていただけるかどうかというところで、ご検討いただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":87,"id":"exchange-042"},{"speaker":"原委員","kind":"質問","question":"会派ではなくて、私個人の考えとしましては、もうモラルの問題だと思うんです。当然、品川区は行政ですから、私としては、「記」の前に入れるのであれば、「もう少し活発な自由な競争」とか、その程度の言葉ぐらいでいいのではないかなという感触を持っております。ですから、正副委員長にお任せをしたいと、私は思っております。","respondent":"鈴木（ひ）委員長","answer":"この提言というのは、この委員会として、全会で一致できる中身ということで、正副委員長で検討させていただいた結果の文言なんですね。","voiceIndex":88,"id":"exchange-043"},{"speaker":"阿部委員","kind":"質問","question":"ですから、最終的に書くかどうかは別として、今の委員長の説明の仕方はちょっと理屈に合っていないのではないかと、こういう言い方をしたら申しわけないですけれども、ちょっと違うのではないかと思います。どう言ったらいいんですか、全会一致の部分だけというのはわかりますけれども、でも、入札を重視でいくという意見自体は、反対意見が、今のところはまだ出ていないと思いますが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":90,"id":"exchange-044"},{"speaker":"中塚委員","kind":"質問","question":"さっき、原委員のほうからあった、「より活発な自由な競争」というのがどういう意味合いだったのかなと思います。この間、契約の仕組みの問題、僕は仕組みの問題のほうが強いのかなと思いますけれども、例えば、安かろう悪かろうではだめだと、だけれども、単純な入札だと一番安いところになるのが明らか。そういう意味では、どういう意味なのか、もしよければ教えていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-045"},{"speaker":"原委員","kind":"質問","question":"ですから、制度的に随意契約なのか、一般競争入札なのか、その辺ということよりも、公明正大にという意味合いで、先ほど、申し上げたです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":92,"id":"exchange-046"},{"speaker":"中塚委員","kind":"質問","question":"そのときに、中身が現状ではよくわかりにくいというので、それぞれの具体性が必要ではないかと、把握が必要ではないか、もっと資料性が向上したほうがいいのではないかと。ほかの委員会もそれぞれあったと思うんですけれども、行政に対して、ちゃんと説明してくださいという意味で、あくまでまとめなので、そちらに対する注文ですから、そういう意味で、私は必要なのかという思いで述べさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":93,"id":"exchange-047"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"ですから、今、急に皆さんでやっている中ですから、では、どういう文章をまとめようかというのは、まだ腹案も何もないですけれども、これから考えなければいけない部分でしょうけれども、ちょっとそこら辺を、皆さんがほんとうに全部を入札制度にしろという、もっと活発な入札制度にするのか、そこら辺をどうするかによって、また文言が全然変わってくると思うんです。","respondent":"市岡総務部長","answer":"例えば、品川区がほかの自治体と比べて特段に随意契約の数が多いとか、そういう事実がもしあるとすれば、それは改めていろいろ議論する必要があると思いますが、ちょっとこの場で、品川区が随意契約に偏重しているような前提の文言が入るというのは、我々の認識としては。","voiceIndex":94,"id":"exchange-048"},{"speaker":"阿部委員","kind":"質問・要望","question":"随意契約でなく、競争入札でできるものは、なじむものは、それが一番よいものについては、不断に見直しの努力を行っていくべきだと、それは品川区だけではなくて、どの自治体もまだまだ努力の余地のあるところだと思いますし、逆に、意識的に努力をしなければ、前年度と同じ、同じ、同じところでいってしまうと、行政としては、そういうところに陥りがちであると思いますので、それはあくまでも、最初に。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-049"},{"speaker":"飯沼委員","kind":"提案","question":"競争入札を基本とし、という、ここのところには異論はないんですけれども、ここまでできている文章で、どこをどういじると、どうかわってくるのかなというところにおいて、具体的に、このような文言をというところでご提案をいただいたほうが、よろしいのではないか。お任せします、ということではなく、提案として、それでみんなが了承するのか、しないのかということ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":97,"id":"exchange-050"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"それに基づいて、この「より的確な判断」という言葉でどうかなと。これは個人案です。ですからまだ、ここの委員会で、阿部委員の指摘のあった部分を、正式に文言を直してこうですよではなくて、もう１回正副委員長でまとめるんでしたら、また調整しますけれども、その辺で判断できないかなという気も、ちょっとしますけれども。ご意見があれば、ほかの方に聞いたほうがいいと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":98,"id":"exchange-051"},{"speaker":"武内委員","kind":"意見","question":"さっき意見は申し述べましたけれども、やっぱり総括シート１枚でわかるというのは、それをつくるというのは非常に難しいと思うので、やっぱりいろいろな角度で、我々も調べなければいけないし、情報をいただかなければいけないので、それだけを、という形に限定するよりは、こういう表現でいってもらいたいと、重ねてお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":100,"id":"exchange-052"},{"speaker":"中塚委員","kind":"提案","question":"総括シートだけでは、というのであれば、共産党としては、事業計画書とか、事業報告書とか、資料提供の充実とか、ただ、さっきから言っているように、そこまでは提案しているわけではなくて、思いとしては含んでいますけれども、ぜひ、反映していただきたいと思っています。この文言を追加していただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":101,"id":"exchange-053"},{"speaker":"山内委員","kind":"質問・要望","question":"４番の最後のほうに、「速やかな事業改善および翌年度以降に活用できるよう充実を図り」というような文言であらわされているので、そこまで具体的なことを言ってしまうときりがないと思うんです。ですから、やはり、こういう形での表現というものが一番的確であると思うので、私は、これで、あとは正副委員長で決めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":102,"id":"exchange-054"},{"speaker":"中塚委員","kind":"意見","question":"今、山内委員のほうから、「充実」に含まれているのではないかというお話でしたが、もしお聞かせ願えれば、現状では不十分だというところで一致できれば、今の総括シートの中身はやっぱりわかりにくいと。もし、よろしければ、ほかの会派の方々のご意見が聞けたらなと。終わりにします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":103,"id":"exchange-055"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"「充実を図る」というのは、何事でも、何か変わっていけば、そこを直していくのが充実を図っていくことではないですか。ですから、正副委員長の立場、副委員長の立場ということで言わせていただければ、この４項目をまとめた中でご理解をいただければ、先ほどの文言修正をこれから検討するということにして、まとめさせていただければと思うんです。これは、自分の意見です。は委員長の判断になります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":104,"id":"exchange-056"}]},{"id":"topic-03","title":"行財政改革特別委員会を再開いたします。 次に、財政（歳入）に関すること","agenda":"行財政改革特別委員会を再開いたします。 次に、財政（歳入）に関すること","exchanges":[{"speaker":"阿部委員","kind":"質問","question":"すみません、黙っていようと思ったんですけれども、１点だけ。４番のところで、「区民生活への影響がない」とありますが、これは「区民生活および区内経済への影響がない範囲」と、ちょっと足しておいたほうがいいのではないかなと思うんですけれども、皆様のご意見はいかがでしょうか。私はあったほうがいいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":110,"id":"exchange-057"},{"speaker":"阿部委員","kind":"意見","question":"区民生活というと、どうしても区内在住者の家計みたいなイメージがあるんですけれども、品川区も行政施策の対象を昼間人口にまで持ってきておりますので、そういう意味では、それを区民生活というイメージでとらえるのには、少々言葉のニュアンスとして無理があるかなと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":112,"id":"exchange-058"},{"speaker":"鈴木（真）副委員長","kind":"意見","question":"そうすると、全然、この文言と一致しなくなる部分が出てくると思うんです。その反対部分はわかるけれども、直接区民に負担があると大きいから、間接的な方に負担をかける部分、例えば、さっき言った、東京都の、都に来る方にホテル税ということで１万円以上の場合に、１００円か２００円かけているけれども、そういう形ならできるのではないかなと、自民党としては、そういうつもりです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":113,"id":"exchange-059"},{"speaker":"原委員","kind":"質問","question":"個人的意見でございまして、私のほうとしては、区民生活ということだけではなくて、ちょっと民主党寄りになるのかわかりませんけれども、区民全体、ですから行政を含めて向上していきたいという意味合いを含めて、だから、経済というのはちょっと適切ではないかもわかりませんけれども、ただ、基本的、個人的には賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":114,"id":"exchange-060"},{"speaker":"武内委員","kind":"意見","question":"今の議論で、「区民生活への影響がない範囲」というのは、非常に漠然として、なかなかとらえづらいところがありますね。あくまで文言のことで、社会経済の状況、変化を踏まえながらなんだから、当然、区民生活とか、区内産業とかへの影響を考えなければいけないわけなんで、あえて、区民生活とか、産業とか入れずに、抜いてしまうということも、一つの考えかなと。正副委員長にお任せしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":115,"id":"exchange-061"},{"speaker":"飯沼委員","kind":"質問・要望","question":"２点目の「減免制度の運用のあり方について検討すること」となっていますけれども、ぜひ、減免制度というのは、この間、質問の中でも、件数が大変少なくて不十分であるという意味では、拡充をしていく意味も含められているというか、その思いがこもっているところで受けとめていただきたいなと思います。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":117,"id":"exchange-062"},{"speaker":"中塚委員","kind":"質問・要望","question":"「区民生活への影響がない範囲」を取ることは絶対に反対です。人々の暮らしの懐に手を突っ込んで、新たな課税をするというのは絶対に認められません。それだけは、はっきりと言わせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":118,"id":"exchange-063"},{"speaker":"阿部委員","kind":"質問","question":"ちょっと蒸し返しになるみたいで申しわけないんですが、区内経済云々のところは、多分、突き詰めると折り合いがつかないところだと思いますので、ここでやるのはやめますが、ただ、直接区民から徴収するものでなくても、例えば、ある業界に対して課税をすることで、その地域内での経済が活性化せずに終わってしまったときの、区民の逸失利益というものも考えると、やはり区内業者ではないというんでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":119,"id":"exchange-064"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"ホテルと、ちょっと言ったんですけれども、例えば、あのときも出ていたけれども、ワンルームマンションに対する課税もありましたよね。ですから、区の方向性を出したときに、あのときも言ったと思うんですけれども、抑止の方向を出す意味で、何かそういうことも考えられないかなという意味で、検討しておいてもらいたいと。","respondent":"鈴木（ひ）委員長","answer":"ここはあくまでも慎重に、「引き続き研究するよう努めること」という文言になっておりますので、一致して出せたらと思っているところです。","voiceIndex":120,"id":"exchange-065"},{"speaker":"武内委員","kind":"意見","question":"さっき、中塚委員からあったので、ちょっと勘違いされてはいけないので、１点だけ。９月ぐらいまで考えますという話があったんですけれども、ワンルームマンション税だって、直接、区内業者ではなくても、かけることによって、それが区民が購入する金額に跳ね返る場合だってあるわけだし、なかなかわかりづらい部分が出てくるんで、そういった面で、区民生活だけ入れてしまうと、というような意味です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":122,"id":"exchange-066"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5836#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":39918,"voices":127}},{"id":"h20-20080418-16","meetingId":"h20-cm04","date":"2008年4月18日","dateIso":"2008-04-18","committee":"街づくり特別委員会","time":"午後１時０３分～午後３時２５分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"八潮まちづくり検討委員会からの提言","agenda":"八潮まちづくり検討委員会からの提言","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"今、最後にこれからの取り扱いについての説明に若干触れておられましたけれども、議会のほうがどういうふうになっていくか、これからの新しい次年度の特別委員会にかかわりますが、そこに議会側の主体的な運営の中で入っていくのかどうかということは、今入っていなかったと思うんですけども、それにしても、多岐にわたっていろいろな分野での項目が提言されていますので、これを区として。","respondent":"日下部企画財政課長","answer":"関係部署との関係でありますけれども、これは以前からご報告していますけれども、庁内に八潮プロジェクトということで、これは実質的にはほぼすべての部にわたるわけでありますけれども、関係の部課長が一堂に会しまして、また、必要に応じまして、関係の部課ということで。","voiceIndex":14,"id":"exchange-001"},{"speaker":"西本委員","kind":"質問","question":"そういう関係をどういうふうに調整していくのかなというところがあるんですが、そういう状況をわかった上で、この提言ができているのか、あくまでも八潮地区という限定された中で、もちろん、そうなのだろうなと思うんですけど、そういう形なのか、そこのところの調整の仕方、考え方はいかがでしょうか。","respondent":"日下部企画財政課長","answer":"ですから、そういう意味では品川区全体の、例えばいろいろな状況でありますとか、そういうものがその中にどれほど勘案されているかというのは、そういった点からすると、またちょっと違う面があるかと思いますけれども、いずれにしましても、地域の声は地域の声と受けとめまして。","voiceIndex":16,"id":"exchange-002"},{"speaker":"西本委員","kind":"質問・要望","question":"ぜひいろいろ調整を図っていただきたいんですが、やはり、八潮地区の関係者は当然そこに住まわれていますので、「わがまち」という形で非常に熱心にいろいろ考えられて、こういうふうにしようと思っているので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"資料の１枚めくったところの、多分、八潮でもあるんですけど、逆にこの検討委員会のほうで学校跡地の有効利用について課題としてそれを話し合うことで立ち上げたということなので、今度は提言も出たということなんですけれども、今後の検討委員会の活動の方向性について今つかんでいることをお伺いしたいと思います。","respondent":"日下部企画財政課長","answer":"今ご質問がありましたように、当面する課題として学校跡地ということで、いわば集中的に検討いただいたわけでありますけれども、八潮の問題というのは、やはり、いろいろな課題もありますので、きのうも会長とちょっとお話ししましたが、会長のほうとしましても。","voiceIndex":19,"id":"exchange-004"},{"speaker":"大沢委員","kind":"質問・要望","question":"今、ちょっと新聞で言われていた、いろいろなまちづくりの上で、これまで大学との連携、高度経済成長のときにできて、今、高齢化が進んだ団地に対して、「学」が一緒にタッグを組んでいろいろな検討を始めていくというようなことを聞きましたけれども、そこの部分について、今後進めるうえで、再生のために「学」とこれからどのようなかかわりを持っていくのか、もし。","respondent":"日下部企画財政課長","answer":"この間、特に八潮団地について、そういう大学と一緒になってというような話は特には今のところございませんけれども、ただ、八潮団地は比較的まだ２５年ですが、大体４０年ぐらいたった団地の再生をめぐっては。","voiceIndex":23,"id":"exchange-005"},{"speaker":"石田委員","kind":"質問・要望","question":"今度、１２月に向けて都市計画等もそれがうまくいけば、そういう形で動きができるようになってくるんだろうと。そのときに、これはもちろんご意見を伺いながらやっていくんだろうけれども、じゃあ、他の地域からの集客をどうするんだ。そういうことも、やっぱり方向性が違うことだって、それは地域の方とあるわけですから、そこら辺の考え方はしっかり出していってほしいなと思います。","respondent":"日下部企画財政課長","answer":"ただ、具体的に出てきております中身というのは、高齢化が進む。そうすると、じゃあ、高齢化に対応した形で、例えば施設をどうやって整備したらいいかと、どうしてもそういう面がかなり中心になってあります。","voiceIndex":25,"id":"exchange-006"},{"speaker":"石田委員","kind":"質問","question":"今、一緒に質問すればよかったんだけど、この提言書をきのう区長も参加されて受け取ったと聞いたんだけれども、地域でこういうのがあって、区長が受け取ったなんていうのは、今まであったのかなと思うんだけど、初めてみたいな気がしているんだけれども、ということは、区長も結構ちゃんとこういうようにやっていただいたことに対して。","respondent":"日下部企画財政課長","answer":"その辺はやはり区長といたしましても、特に地域の皆さん方がまちの活性化について非常に強い思いを抱いていらっしゃると。それがもとになって、自治会が中心になってこういう検討会も組織された。","voiceIndex":27,"id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、先ほどもどなたかがおっしゃっていましたけれども、全国にはいろいろなこういう八潮団地以外に、もっと経験豊かに実績を、「学」との連携とかという話もありましたけど、それだけにこだわらずに、まちをどういうふうにつくってきたか、どういうふうな研究を専門家と一緒にやってきたかという事例って、わりとあるんじゃないかなと思いますので、そういうところも本当に紹介しながら、区としても。","respondent":"日下部企画財政課長","answer":"１つは、確かにいろいろと活性化に当たっては、いろいろな面での多様な視点、幅広い物の見方、考え方も含めて、進めていかなければいけませんので、そういった点では、やはり行政が果たす役割というのは非常に重要だと考えていますので、今後ともできる限り地域の自治会。","voiceIndex":30,"id":"exchange-008"},{"speaker":"南委員","kind":"質問・要望","question":"意見の調整もそうなんですけれども、例えば、私も以前、一般質問で紹介させていただきましたけど、専門家の講習会の設定だとか、そういうことも含めて、ぜひ支援をしていくべきだと思いますので、その点については改めて要望としてお伝えして、時間の関係もありますので終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-009"}]},{"id":"topic-02","title":"特定事件調査の新・水とみどりのネットワーク構想","agenda":"特定事件調査の新・水とみどりのネットワーク構想","exchanges":[{"speaker":"南委員","kind":"確認","question":"その努力はあったということを改めて再確認したんですけれども、議会側の意見を最終案に載せるのに、議会側の意見を出す場面が今日しかないのかなと思ったんですけど、１４日のときは最終案として提示されるということですから、私は今日の委員会も、そういう意味では議会側の意見を出す機会が今日しかないのかなと思ったので、その辺で委員長に確認したいんですけど、４０分に視察に出ちゃいますよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-010"},{"speaker":"南委員","kind":"質問","question":"そうすると、日程からいうと八潮のところのこれもあったので、どういうふうにその意見を……。終わってから、また再開してやる予定なんですか。なかなかちょっと意見を……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-011"},{"speaker":"南委員","kind":"質問","question":"わかりました。じゃあ、１つ。私はそういうふうに理解したんですけど、本当はどうなんでしょうか。","respondent":"松代管理工事課長、藤田道路公園課長","answer":"これはもう国も東京都もそのような形でやっておりますので、そのような方向で区も今後取り上げて、ある程度目標の数値を示す中で、今後も取り組んでまいりたいということで、この前ご説明したところです。加えまして、今までカウントしてきた緑被率については当然、みどりの実態調査の中でも引き続き数値化は続けていくということで考えてあります。","voiceIndex":43,"id":"exchange-012"},{"speaker":"南委員","kind":"質問","question":"単純に水辺、沼にしても、池にしても、水を入れるというのが、みどり率という言葉の関係でよくわからないんです。だから、さっきヒートアイランドとの関係でそういうふうにカウントしたいのかなというふうに印象を持ったので、そういうふうに聞いたんですけれども、いろいろな緑があるのはそれは当然知っていますけれども、その辺を教えてください。","respondent":"岩田まちづくり事業部長","answer":"ですから、みどり率というのはこう考えていただければいいと思うんですけど、より自然的なものが都市の中にどれぐらいあるのか。","voiceIndex":46,"id":"exchange-013"},{"speaker":"南委員","kind":"質問","question":"そういう緑が与える人間生活への影響ということを考えたときに、もっと緑を増やすという方向で、このみどり率というのを考えていくのかどうか。今ある更地、裸地みたいな、あるいは、そこに水等々も入れてというところが、そういう方向を目指しているというふうには、なかなか今までの説明ではちょっととらえられなかったので、その辺についてはどうなんですか。","respondent":"松代管理工事課長、家壽田下水道河川課長","answer":"この広くみどり率という点で示したのは、１つには、今おっしゃったように、緑を増やすと。若干ちょっと私からみどり率について水の観点から申し上げますと、裸地は緑でないというのは、確かにそうなんですけれども、水循環の構成要素としては大変重要でして、降った雨が都市型水害を起こさないでしみ込んでくれるということは。","voiceIndex":48,"id":"exchange-014"},{"speaker":"南委員","kind":"質問","question":"ですから、裸地をカウントしていくということは、その時点では入るけれども、いずれそうじゃない部分になっていかざるを得ないという部分がありますので、その辺について、やっぱり緑をどういうふうに増やしていくかという、それは行政としても大変な苦労のところだと思うので、これは意見で終わりたいんですけれども、みどり率の設定そのものはわかりましたけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"みどり率の発想ですけれども、区民がその施策の推進の進みぐあいを具体的とか客観的に把握する時点で、測定数値は何を使うかというのはすごく大事だと思うんですけれども、先ほどのお話で、緑被率のほうも引き続き追っていくということだったんですけれども、まず１点、これまでは５年ごとにカウントしたということなんですけれども。","respondent":"松代管理工事課長","answer":"今回の２回のパブリックコメントもホームページで掲載をしてお知らせをしましたが、ホームページをご覧になってご意見を賜ったというのもございましたので、こういったものを今後とも引き続き掲載をしながら、今後、順次更新等を進めて。","voiceIndex":52,"id":"exchange-016"},{"speaker":"石田委員","kind":"質問・要望","question":"１点だけいいですか。ちょっと気になる答弁というか、書き方があったので、そこだけ。そのボランティアとは何かということを、ぜひ考慮の中に入れていただきたい。そこの部分のボランティアとは何かということは、ぜひ考慮していくのであれば、先ほどのそのやりがいで顕彰するのも１つだろうけど、そういうことも含めて、これをやっていくなら考えていただきたい。これだけは意見としてです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-017"},{"speaker":"西本委員","kind":"質問","question":"簡単に教えてください。このパブコメですけれども、この７通というのはどこから来た７通なのかということと、それは全部どういう方から得られたものなのか。それから、その７通という結果について、これで十分と思っているのか。パブコメのレベルとしてはどういうふうに考えたらいいのかということで、お願いします。","respondent":"松代管理工事課長","answer":"中間のまとめのときにもパブコメでいただいた内容等を含めて、先ほど言いましたように、公園等へ私どもも出かけましてアンケート調査をする中で、こういうご意見がきていますので、今後もご意見を聞く、または周知をする方法等については今後も研究してまいりたいと。","voiceIndex":55,"id":"exchange-018"},{"speaker":"西本委員","kind":"意見","question":"告知のほうのやり方はどういう形に、パブリックコメントでこういうのをくださいという投げ方はどういう形にされていますか。","respondent":"松代管理工事課長","answer":"前回のときにもご説明しましたが、広報紙にこのようなカラー刷りで入れ、お示しをしております。これが基本でございまして、次に、ホームページで原案の内容等をすべてご覧いただけるような形で掲載をしております。","voiceIndex":57,"id":"exchange-019"},{"speaker":"西本委員","kind":"質問・要望","question":"要するに、広報紙、それとホームページに載せて、前回が意見１３名、それが今回は７通という、そういう中からコメントをとって、興味のある方がしっかりとしたご意見をいただいたということで、非常に質の高いご意見かなと思ってはいるんですけれども、そこを特にパブリックコメントの中身と重なると思うんですが、そこの検証もいろいろ考えていただきたいなと思っているので、数が少なくても。","respondent":"福田企画部長、松代管理工事課長","answer":"ご意見をちょうだいし、それを反映する。それから。もう１つはそのパブリックコメントの目的物を広く宣伝する。こういう目的がありますので、これらのことを勘案しながら、ご意見の趣旨を十分生かしてまいりたいと思います。その後、東品川海上公園のオープン後１年たちました屋上庭園を含めてご覧いただければなと。最後に、品川南ふ頭公園が３月の末に完成し、４月１日からオープンをしています。","voiceIndex":59,"id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6362#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":18993,"voices":64}}]);
